#[test]
fn adopt_large_mod_bootstraps_existing_mod_authoring_artifacts() {
    let root = unique_temp_dir("adopt-existing-large-mod");
    let mod_root = root.join("existing_mod");
    fs::create_dir_all(mod_root.join("common").join("country_tags")).unwrap();
    fs::create_dir_all(mod_root.join("common").join("national_focus")).unwrap();
    fs::create_dir_all(mod_root.join("common").join("decisions")).unwrap();
    fs::create_dir_all(mod_root.join("common").join("ideas")).unwrap();
    fs::create_dir_all(mod_root.join("common").join("dynamic_modifiers")).unwrap();
    fs::create_dir_all(mod_root.join("events")).unwrap();
    fs::create_dir_all(mod_root.join("localisation")).unwrap();
    fs::write(
        mod_root.join("descriptor.mod"),
        "name=\"KXC Scale Existing Mod\"\nsupported_version=\"*\"\n",
    )
    .unwrap();
    fs::write(
        mod_root
            .join("common")
            .join("country_tags")
            .join("00_tags.txt"),
        "CHI = \"countries/China.txt\"\nCPC = \"countries/Communist China.txt\"\nGER = \"countries/Germany.txt\"\n",
    )
    .unwrap();
    fs::write(
        mod_root
            .join("localisation")
            .join("sample_l_simp_chinese.yml"),
        "\u{feff}l_simp_chinese:\n sample:0 \"样例\"\n",
    )
    .unwrap();

    let output = root.join("adopt.json");
    cmd_adopt_large_mod(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--max-countries".to_string(),
        "2".to_string(),
        "--output".to_string(),
        output.to_string_lossy().to_string(),
    ])
    .unwrap();

    let report = read_utf8_lossy(&output).unwrap();
    let blueprint_path = mod_root.join(".hoi4skill").join("large_mod_blueprint.yml");
    let manifest_path = mod_root
        .join(".hoi4skill")
        .join("work_packages")
        .join("manifest.json");
    let request_template = mod_root.join(".hoi4skill").join("package_requests.md");
    assert!(report.contains("\"schema\": \"hoi4skill.large_mod_adopt_existing.v1\""));
    assert!(report.contains("\"status\": \"adopted\""));
    assert!(report.contains("\"country_count\": 2"));
    assert!(blueprint_path.is_file());
    assert!(manifest_path.is_file());
    assert!(request_template.is_file());
    let blueprint = read_utf8_lossy(&blueprint_path).unwrap();
    assert!(blueprint.contains("name: \"KXC Scale Existing Mod\""));
    assert!(blueprint.contains("id: \"chi\""));
    assert!(blueprint.contains("id: \"cpc\""));
    assert!(!blueprint.contains("id: \"ger\""));
    assert!(blueprint.contains("dynamic_modifier_content"));

    let gate_output = root.join("authoring_gate.json");
    cmd_large_mod_authoring_gate(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--output".to_string(),
        gate_output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let gate = read_utf8_lossy(&gate_output).unwrap();
    fs::remove_dir_all(&root).unwrap();
    assert!(gate.contains("\"schema\": \"hoi4skill.large_mod_authoring_gate.v1\""));
    assert!(gate.contains("\"mod\": \"KXC Scale Existing Mod\""));
    assert!(gate.contains("missing author-work-packages manifest"));
    assert!(gate.contains("author-work-packages"));
}

#[test]
fn large_mod_ownership_map_marks_shared_edit_surfaces() {
    let root = unique_temp_dir("large-mod-ownership-map");
    let blueprint_path = root.join("blueprint.yml");
    let mod_root = root.join("mod");
    let output = root.join("ownership_map.json");

    cmd_plan_large_mod(&[
        "--text".to_string(),
        "name: Test Grand Campaign\ncountries: RUS, GER\nregions: europe\nsystems: black monday"
            .to_string(),
        "--name".to_string(),
        "Test Grand Campaign".to_string(),
        "--acronym".to_string(),
        "TGC".to_string(),
        "--output".to_string(),
        blueprint_path.to_string_lossy().to_string(),
    ])
    .unwrap();

    cmd_init_large_mod(&[
        "--blueprint".to_string(),
        blueprint_path.to_string_lossy().to_string(),
        "--output".to_string(),
        mod_root.to_string_lossy().to_string(),
    ])
    .unwrap();

    cmd_large_mod_ownership_map(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--output".to_string(),
        output.to_string_lossy().to_string(),
    ])
    .unwrap();

    let json = read_utf8_lossy(&output).unwrap();
    assert!(json.contains("\"schema\": \"hoi4skill.large_mod_ownership_map.v1\""));
    assert!(json.contains("\"package_count\": 4"));
    assert!(json.contains("\"shared_path_count\""));
    assert!(json.contains("\"id\": \"country_rus\""));
    assert!(json.contains("\"identity_terms\": [\"RUS\", \"country_rus\", \"rus\", \"tgc_rus\"]"));
    assert!(json.contains("\"path\": \"events\""));
    assert!(json.contains("\"owner_count\": 3"));
    assert!(json.contains("\"path\": \"localisation/simp_chinese\""));
    assert!(json.contains("\"owner_count\": 4"));
    assert!(json.contains("\"requires_identity_terms\": true"));
    assert!(json.contains("split-changed-work-packages"));
    assert!(json.contains("Do not assign shared paths by directory prefix alone"));
}

