#[test]
fn run_work_package_execute_writes_repair_bundle_when_blocked() {
    let root = unique_temp_dir("run-work-package-execute-blocked");
    let blueprint_path = root.join("blueprint.yml");
    let mod_root = root.join("mod");
    let output_dir = root.join("run");
    let game_root = root.join("Hearts of Iron IV");

    cmd_plan_large_mod(&[
        "--text".to_string(),
        "name: Test Grand Campaign\ncountries: RUS\nregions: europe".to_string(),
        "--name".to_string(),
        "Test Grand Campaign".to_string(),
        "--acronym".to_string(),
        "TGC".to_string(),
        "--output".to_string(),
        blueprint_path.to_string_lossy().to_string(),
    ])
    .unwrap();
    cmd_init_large_mod(&[
        "--blueprint".to_string(),
        blueprint_path.to_string_lossy().to_string(),
        "--output".to_string(),
        mod_root.to_string_lossy().to_string(),
    ])
    .unwrap();
    fs::create_dir_all(game_root.join("documentation")).unwrap();
    fs::create_dir_all(game_root.join("common").join("national_focus")).unwrap();
    fs::create_dir_all(game_root.join("events")).unwrap();
    fs::create_dir_all(game_root.join("common").join("ideas")).unwrap();
    fs::write(
        game_root
            .join("documentation")
            .join("effects_documentation.md"),
        "## Effects\n\n## add_political_power\n\n## add_stability\n",
    )
    .unwrap();
    fs::write(
        game_root.join("common").join("national_focus").join("tst.txt"),
        "focus_tree = {\n id = tst_tree\n country = { factor = 0 modifier = { add = 10 tag = TST } }\n focus = {\n  id = TST_repair_focus\n  icon = GFX_goal_generic_political_pressure\n  x = 0\n  y = 0\n  cost = 10\n  completion_reward = { add_stability = 0.05 }\n }\n}\n",
    )
    .unwrap();
    fs::write(
        game_root.join("events").join("tst_events.txt"),
        "add_namespace = tst\ncountry_event = {\n id = tst.1\n title = tst.1.t\n desc = tst.1.d\n is_triggered_only = yes\n option = { name = tst.1.a add_stability = 0.05 }\n}\n",
    )
    .unwrap();
    fs::write(
        game_root.join("common").join("ideas").join("tst_ideas.txt"),
        "ideas = {\n country = {\n  TST_repair_spirit = {\n   picture = generic_political_reform\n   modifier = { stability_factor = 0.05 }\n  }\n }\n}\n",
    )
    .unwrap();

    let result = cmd_run_work_package(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--package".to_string(),
        "country_rus".to_string(),
        "--request".to_string(),
        "写俄国国策、事件链、决议、民族精神、动态修正和本地化".to_string(),
        "--game-root".to_string(),
        game_root.to_string_lossy().to_string(),
        "--output-dir".to_string(),
        output_dir.to_string_lossy().to_string(),
        "--execute".to_string(),
    ]);
    let err = result.unwrap_err();
    assert!(err.contains("work package run failed"));
    assert!(err.contains("repair_bundle_country_rus"));

    let execution_report = read_utf8_lossy(&output_dir.join("execution_report.json")).unwrap();
    assert!(execution_report.contains("\"schema\": \"hoi4skill.work_package_run_execution.v1\""));
    assert!(execution_report.contains("\"status\": \"failed\""));
    assert!(execution_report.contains("dependency_gate"));
    assert!(execution_report.contains("blocked"));
    assert!(execution_report.contains("system_political_paths"));

    let repair_dir = mod_root
        .join(".hoi4skill")
        .join("repair_bundle_country_rus");
    let repair_bundle = read_utf8_lossy(&repair_dir.join("repair_bundle.json")).unwrap();
    assert!(repair_bundle.contains("\"schema\": \"hoi4skill.ai_repair_bundle.v1\""));
    assert!(repair_bundle.contains("\"status\": \"repair_prompt_ready\""));
    assert!(repair_bundle.contains("\"validation_ok\": false"));
    assert!(repair_bundle.contains("\"source\": \"run-work-package\""));
    assert!(repair_bundle.contains("\"retrieval_status\": \"ok\""));
    assert!(repair_bundle.contains("retrieved_code_context.md"));
    assert!(repair_bundle.contains("retrieved_code_context.json"));
    assert!(repair_bundle.contains("input_repair_prompt.md"));
    let retrieved_markdown =
        read_utf8_lossy(&repair_dir.join("retrieved_code_context.md")).unwrap();
    assert!(retrieved_markdown.contains("hoi4skill.work_package_retrieved_repair_context.v1"));
    assert!(retrieved_markdown.contains("add_stability"));
    assert!(retrieved_markdown.contains("Related Indexed Symbols"));
    assert!(retrieved_markdown
        .contains("if no matching symbol or example exists, stop and ask for evidence"));
    let retrieved_json = read_utf8_lossy(&repair_dir.join("retrieved_code_context.json")).unwrap();
    assert!(retrieved_json.contains("\"status\": \"ok\""));
    assert!(retrieved_json.contains("\"related_symbols\""));
    assert!(retrieved_json.contains("\"examples\""));
    let failed_output = read_utf8_lossy(&repair_dir.join("failed_output.md")).unwrap();
    assert!(failed_output.contains("hoi4skill.work_package_run_failed_output.v1"));
    assert!(failed_output.contains("package is blocked by dependency package"));
    let repair_prompt = read_utf8_lossy(&repair_dir.join("repair_prompt.md")).unwrap();
    assert!(repair_prompt.contains("hoi4skill.ai_repair_prompt.v1"));
    assert!(repair_prompt.contains("hoi4skill.work_package_run_failed_output.v1"));
    assert!(repair_prompt.contains("hoi4skill.work_package_retrieved_repair_context.v1"));
    let input_repair_prompt = read_utf8_lossy(&repair_dir.join("input_repair_prompt.md")).unwrap();
    assert!(input_repair_prompt.contains("hoi4skill.work_package_input_repair_prompt.v1"));
    assert!(input_repair_prompt.contains("hoi4skill-input:focus_layout"));
    assert!(input_repair_prompt.contains("hoi4skill-input:event_cards"));
    assert!(input_repair_prompt.contains("hoi4skill-input:dynamic_modifier_intent"));
    assert!(input_repair_prompt.contains("apply-work-package-repair"));
    assert!(input_repair_prompt.contains("Do not output diffs, final Clausewitz files"));
}

