#[test]
fn p63_stale_plan_gate_blocks_changed_knowledge_and_missing_changed_files() {
    let root = unique_temp_dir("stale-plan-gate");
    let plan = root.join("transaction.json");
    let clean_kb = root.join("kb_clean.json");
    let stale_kb = root.join("kb_stale.json");
    let report = root.join("stale_gate.json");
    let p63 = root.join("p63.json");
    fs::create_dir_all(&root).unwrap();
    fs::write(
        &plan,
        "{\n  \"schema\": \"hoi4skill.mod_transaction_plan.v1\",\n  \"changed_files\": [\"events/generated_events.txt\"]\n}\n",
    )
    .unwrap();
    fs::write(
        &clean_kb,
        "{\n  \"schema\": \"hoi4skill.knowledge_base_refresh.v1\",\n  \"files\": [{\"cache_key\": \"target_mod:events/a.txt\", \"hash\": \"a\", \"change\": \"unchanged\"}]\n}\n",
    )
    .unwrap();
    fs::write(
        &stale_kb,
        "{\n  \"schema\": \"hoi4skill.knowledge_base_refresh.v1\",\n  \"files\": [{\"cache_key\": \"dependency_mod:events/a.txt\", \"hash\": \"b\", \"change\": \"changed\"}]\n}\n",
    )
    .unwrap();

    cmd_stale_plan_gate(&[
        "--input".to_string(),
        plan.to_string_lossy().to_string(),
        "--knowledge".to_string(),
        clean_kb.to_string_lossy().to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        report.to_string_lossy().to_string(),
    ])
    .unwrap();
    let stale_err = cmd_stale_plan_gate(&[
        "--input".to_string(),
        plan.to_string_lossy().to_string(),
        "--knowledge".to_string(),
        stale_kb.to_string_lossy().to_string(),
        "--require-passed".to_string(),
    ])
    .unwrap_err();
    let no_files = root.join("no_files.json");
    fs::write(&no_files, "{\"schema\":\"x\"}").unwrap();
    let no_files_err = cmd_stale_plan_gate(&[
        "--input".to_string(),
        no_files.to_string_lossy().to_string(),
        "--knowledge".to_string(),
        clean_kb.to_string_lossy().to_string(),
        "--require-passed".to_string(),
    ])
    .unwrap_err();
    cmd_core_capability_audit(&[
        "--phase".to_string(),
        "P63".to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        p63.to_string_lossy().to_string(),
    ])
    .unwrap();

    let json = read_utf8_lossy(&report).unwrap();
    let p63_json = read_utf8_lossy(&p63).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(json.contains("\"schema\": \"hoi4skill.stale_plan_gate.v1\""));
    assert!(json.contains("\"status\": \"plan_fresh\""));
    assert!(json.contains("events/generated_events.txt"));
    assert!(stale_err.contains("changed/stale source evidence"));
    assert!(no_files_err.contains("no changed_files"));
    assert!(p63_json.contains("\"phase_filter\": \"P63\""));
    assert!(p63_json.contains("\"command\": \"stale-plan-gate\""));
    assert!(p63_json.contains("\"command\": \"knowledge-delta-refresh\""));
}

