#[test]
fn p74_to_p80_phase_audit_and_weak_ai_suite_are_registered() {
    let root = unique_temp_dir("p74-p80-phase-audit");
    let target = root.join("target_mod");
    let game_root = root.join("Hearts of Iron IV");
    fs::create_dir_all(&target).unwrap();
    fs::create_dir_all(&game_root).unwrap();
    let weak = root.join("weak_ai.json");
    cmd_weak_ai_regression_suite(&[
        "--game-root".to_string(),
        game_root.to_string_lossy().to_string(),
        "--mod-root".to_string(),
        target.to_string_lossy().to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        weak.to_string_lossy().to_string(),
    ])
    .unwrap();
    let mut phase_jsons = Vec::new();
    for phase_id in ["P74", "P75", "P76", "P77", "P78", "P79", "P80"] {
        let phase = root.join(format!("{phase_id}.json"));
        cmd_core_capability_audit(&[
            "--phase".to_string(),
            phase_id.to_string(),
            "--require-passed".to_string(),
            "--output".to_string(),
            phase.to_string_lossy().to_string(),
        ])
        .unwrap();
        phase_jsons.push(read_utf8_lossy(&phase).unwrap());
    }
    let weak_json = read_utf8_lossy(&weak).unwrap();
    fs::remove_dir_all(&root).unwrap();
    assert!(weak_json.contains("\"schema\": \"hoi4skill.weak_ai_regression_suite.v1\""));
    assert!(weak_json.contains("\"case_count\": 10"));
    assert!(weak_json.contains("unknown_modifier_typo"));
    assert!(phase_jsons
        .iter()
        .any(|json| json.contains("\"phase_filter\": \"P74\"")));
    assert!(phase_jsons
        .iter()
        .any(|json| json.contains("map-release-gate")));
    assert!(phase_jsons
        .iter()
        .any(|json| json.contains("\"phase_filter\": \"P80\"")));
    assert!(phase_jsons
        .iter()
        .any(|json| json.contains("weak-ai-regression-suite")));
}

