#[test]
fn p94_map_transaction_gate_unifies_risk_reports_and_blocks_ungated_topology() {
    let root = unique_temp_dir("p94-map-transaction-gate");
    fs::create_dir_all(&root).unwrap();
    let audit = root.join("map_data_audit.json");
    let intent = root.join("map_intent.json");
    let state = root.join("state_transaction.json");
    let topology = root.join("map_topology.json");
    let gate = root.join("map_transaction_gate.json");
    let phase = root.join("p94.json");
    fs::write(
        &audit,
        "{\n  \"schema\": \"hoi4skill.map_data_audit.v1\",\n  \"ok\": true,\n  \"status\": \"map_data_audit_ready\"\n}\n",
    )
    .unwrap();
    fs::write(
        &intent,
        "{\n  \"schema\": \"hoi4skill.map_intent_plan.v1\",\n  \"ok\": true,\n  \"status\": \"map_intent_ready\"\n}\n",
    )
    .unwrap();
    fs::write(
        &state,
        "{\n  \"schema\": \"hoi4skill.state_transaction_plan.v1\",\n  \"ok\": true,\n  \"status\": \"state_transaction_ready\"\n}\n",
    )
    .unwrap();
    fs::write(
        &topology,
        "{\n  \"schema\": \"hoi4skill.map_topology_plan.v1\",\n  \"ok\": true,\n  \"status\": \"map_topology_review_pack_ready\"\n}\n",
    )
    .unwrap();

    cmd_map_transaction_gate(&[
        "--report".to_string(),
        audit.to_string_lossy().to_string(),
        "--report".to_string(),
        intent.to_string_lossy().to_string(),
        "--report".to_string(),
        state.to_string_lossy().to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        gate.to_string_lossy().to_string(),
    ])
    .unwrap();
    let topology_err = cmd_map_transaction_gate(&[
        "--report".to_string(),
        audit.to_string_lossy().to_string(),
        "--report".to_string(),
        intent.to_string_lossy().to_string(),
        "--report".to_string(),
        topology.to_string_lossy().to_string(),
        "--require-passed".to_string(),
    ])
    .unwrap_err();
    cmd_core_capability_audit(&[
        "--phase".to_string(),
        "P94".to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        phase.to_string_lossy().to_string(),
    ])
    .unwrap();

    let json = read_utf8_lossy(&gate).unwrap();
    let phase_json = read_utf8_lossy(&phase).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(json.contains("\"schema\": \"hoi4skill.map_transaction_gate.v1\""));
    assert!(json.contains("\"status\": \"map_transaction_ready\""));
    assert!(json.contains("low:state_history_or_province_set"));
    assert!(topology_err.contains("map-topology-gate manual confirmation"));
    assert!(phase_json.contains("\"phase_filter\": \"P94\""));
    assert!(phase_json.contains("\"command\": \"map-transaction-gate\""));
    assert!(phase_json.contains("map-data-audit + map-intent-plan + province-query"));
}

