    fs::write(logs_dir.join("error.log"), "").unwrap();
    fs::write(logs_dir.join("map.log"), "").unwrap();
    fs::write(logs_dir.join("setup.log"), "").unwrap();
    let plan = root.join("runtime_session_plan.json");
