#[test]
fn p23_history_scenario_apply_writes_reviewable_patch_pack_only() {
    let root = unique_temp_dir("p23-history-scenario-apply");
    let mod_root = root.join("target_mod");
    fs::create_dir_all(&mod_root).unwrap();
    fs::write(
        mod_root.join("descriptor.mod"),
        "name=\"Target Mod\"\nsupported_version=\"*\"\n",
    )
    .unwrap();
    let plan = root.join("history_scenario.json");
    fs::write(
        &plan,
        "{\n  \"schema\": \"hoi4skill.history_scenario_plan.v1\",\n  \"ok\": true,\n  \"targets\": {\"tag\": \"GER\", \"enemy_tag\": \"FRA\", \"technology_year\": 1936},\n  \"state\": {\"id\": 42, \"province_sample\": [123]},\n  \"leader_matches\": [{\"id\": \"GER_test_leader\", \"file\": \"common/characters/GER.txt\"}],\n  \"oob\": {\"id\": \"GER_1936\", \"file\": \"history/units/GER_1936.txt\"},\n  \"war_template\": \"history/diplomacy/00_wars.txt\",\n  \"technologies\": [\"infantry_weapons\", \"support_weapons\"],\n  \"planned_effects\": [\"GER receives all indexed 1936 technologies (2)\"],\n  \"planned_files\": [\"history/countries/GER.txt\", \"history/states/42.txt\", \"history/units/GER_1936.txt\", \"history/diplomacy/war.txt\"],\n  \"blockers\": []\n}\n",
    )
    .unwrap();
    let output = root.join("apply.json");
    cmd_history_scenario_apply(&[
        "--input".to_string(),
        plan.to_string_lossy().to_string(),
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--execute".to_string(),
        "--final-check".to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        output.to_string_lossy().to_string(),
    ])
    .unwrap();

    let report = read_utf8_lossy(&output).unwrap();
    let country_patch = read_utf8_lossy(
        &mod_root
            .join(".hoi4skill")
            .join("history_scenario_apply")
            .join("country_history_patch.txt"),
    )
    .unwrap();
    let state_patch = read_utf8_lossy(
        &mod_root
            .join(".hoi4skill")
            .join("history_scenario_apply")
            .join("state_history_patch.txt"),
    )
    .unwrap();
    assert!(!mod_root.join("history").exists());
    fs::remove_dir_all(&root).unwrap();

    assert!(report.contains("\"schema\": \"hoi4skill.history_scenario_apply.v1\""));
    assert!(report.contains("\"status\": \"history_scenario_patch_pack_written\""));
    assert!(country_patch.contains("recruit_character = GER_test_leader"));
    assert!(country_patch.contains("infantry_weapons = 1"));
    assert!(country_patch.contains("support_weapons = 1"));
    assert!(state_patch.contains("owner = GER"));
    assert!(state_patch.contains("controller = GER"));
}

