#[test]
fn p28_ambiguity_gate_requires_user_answers_for_icons_flags_and_aliases() {
    let root = unique_temp_dir("p28-ambiguity");
    let game_root = root.join("Hearts of Iron IV");
    let mod_root = root.join("target_mod");
    fs::create_dir_all(game_root.join("common").join("country_tags")).unwrap();
    fs::create_dir_all(game_root.join("localisation").join("simp_chinese")).unwrap();
    fs::create_dir_all(game_root.join("interface")).unwrap();
    fs::create_dir_all(mod_root.join("gfx").join("flags").join("medium")).unwrap();
    fs::create_dir_all(mod_root.join("gfx").join("flags").join("small")).unwrap();
    fs::write(
        game_root
            .join("common")
            .join("country_tags")
            .join("00_tags.txt"),
        "CHI = \"countries/CHI.txt\"\nCPC = \"countries/CPC.txt\"\nPRC = \"countries/PRC.txt\"\n",
    )
    .unwrap();
    fs::write(
        game_root
            .join("localisation")
            .join("simp_chinese")
            .join("countries_l_simp_chinese.yml"),
        "l_simp_chinese:\n  CHI:0 \"中华民国\"\n  CHI_DEF:0 \"中华民国\"\n  CPC:0 \"中华人民共和国\"\n  PRC:0 \"中华人民共和国\"\n  KMT_ICON_SAMPLE:0 \"£GFX_kmt_party_icon 国民党\"\n",
    )
    .unwrap();
    fs::write(
        game_root.join("interface").join("test_icons.gfx"),
        "spriteTypes = { spriteType = { name = \"GFX_kmt_party_icon\" texturefile = \"gfx/interface/kmt.dds\" } }\n",
    )
    .unwrap();
    fs::write(mod_root.join("gfx").join("flags").join("CHI.tga"), "fake").unwrap();
    fs::write(
        mod_root
            .join("gfx")
            .join("flags")
            .join("medium")
            .join("CHI.tga"),
        "fake",
    )
    .unwrap();

    let report = root.join("ambiguity.json");
    let err = cmd_ambiguity_report(&[
        "--game-root".to_string(),
        game_root.to_string_lossy().to_string(),
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--text".to_string(),
        "【国民党图标】【中华民国国旗】中华民国国民政府宣布【中华人民共和国领导人】到场"
            .to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        report.to_string_lossy().to_string(),
    ])
    .unwrap_err();
    assert!(err.contains("Flag placeholder"));
    assert!(err.contains("中华人民共和国领导人"));

    let report_json = read_utf8_lossy(&report).unwrap();
    assert!(report_json.contains("\"schema\": \"hoi4skill.ambiguity_report.v1\""));
    assert!(report_json.contains("\"kind\": \"flag\""));
    assert!(report_json.contains("\"kind\": \"leader_alias\""));
    assert!(report_json.contains("\"id\": \"CPC\""));
    assert!(report_json.contains("\"id\": \"PRC\""));
    assert!(report_json.contains("missing gfx/flags triplet"));
    assert!(!report_json.contains("icon_国民党图标"));

    let answers = root.join("answers.json");
    fs::write(
        &answers,
        "{\n  \"flag_中华民国国旗\": \"CHI\",\n  \"leader_alias_中华人民共和国领导人\": \"CPC\",\n  \"text_country_alias_中华人民共和国\": \"CPC\"\n}\n",
    )
    .unwrap();
    let resolved = root.join("resolved_intent.json");
    cmd_answer_ambiguity(&[
        "--input".to_string(),
        report.to_string_lossy().to_string(),
        "--answers".to_string(),
        answers.to_string_lossy().to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        resolved.to_string_lossy().to_string(),
    ])
    .unwrap();
    cmd_ambiguity_gate(&[
        "--input".to_string(),
        resolved.to_string_lossy().to_string(),
        "--require-passed".to_string(),
    ])
    .unwrap();
    fs::remove_dir_all(&root).unwrap();
}

