#[test]
fn p23_oob_relocation_rewrites_locations_and_adds_armored_divisions() {
    let root = unique_temp_dir("p23-oob-relocation");
    let game_root = root.join("Hearts of Iron IV");
    let mod_root = root.join("target_mod");
    fs::create_dir_all(game_root.join("common").join("country_tags")).unwrap();
    fs::create_dir_all(game_root.join("common").join("units")).unwrap();
    fs::create_dir_all(game_root.join("history").join("states")).unwrap();
    fs::create_dir_all(game_root.join("localisation").join("simp_chinese")).unwrap();
    fs::create_dir_all(mod_root.join("history").join("units")).unwrap();
    fs::write(
        mod_root.join("descriptor.mod"),
        "name=\"Target Mod\"\nsupported_version=\"*\"\n",
    )
    .unwrap();
    fs::write(
        game_root
            .join("common")
            .join("country_tags")
            .join("00_tags.txt"),
        "PRC = \"countries/PRC.txt\"\n",
    )
    .unwrap();
    fs::write(
        game_root.join("common").join("units").join("00_units.txt"),
        "sub_units = { light_armor = { } motorized = { } }\n",
    )
    .unwrap();
    fs::write(
        game_root.join("history").join("states").join("601-Jiangxi.txt"),
        "state = { id = 601 name = \"STATE_601\" history = { owner = CHI } provinces = { 100 101 } }\n",
    )
    .unwrap();
    fs::write(
        game_root.join("history").join("states").join("622-Shaanbei.txt"),
        "state = { id = 622 name = \"STATE_622\" history = { owner = PRC } provinces = { 10 11 } }\n",
    )
    .unwrap();
    fs::write(
        game_root
            .join("localisation")
            .join("simp_chinese")
            .join("state_l_simp_chinese.yml"),
        "l_simp_chinese:\n  STATE_601:0 \"江西省\"\n  STATE_622:0 \"陕北\"\n",
    )
    .unwrap();
    fs::write(
        mod_root.join("history").join("units").join("PRC_1936.txt"),
        "division = { name = \"红军一师\" location = 10 division_template = \"红军步兵师\" }\ndivision = { name = \"红军二师\" location = 11 division_template = \"红军步兵师\" }\n",
    )
    .unwrap();

    let plan = root.join("oob_relocation.json");
    cmd_oob_relocation_plan(&[
        "--game-root".to_string(),
        game_root.to_string_lossy().to_string(),
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--tag".to_string(),
        "PRC".to_string(),
        "--oob".to_string(),
        "PRC_1936".to_string(),
        "--text".to_string(),
        "红军装甲师，十六坦五摩托车，共两个师，部署到江西省".to_string(),
        "--regiment".to_string(),
        "light_armor=16".to_string(),
        "--regiment".to_string(),
        "motorized=5".to_string(),
        "--source-state-id".to_string(),
        "622".to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        plan.to_string_lossy().to_string(),
    ])
    .unwrap();
    let apply = root.join("oob_relocation_apply.json");
    cmd_oob_relocation_apply(&[
        "--input".to_string(),
        plan.to_string_lossy().to_string(),
        "--execute".to_string(),
        "--final-check".to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        apply.to_string_lossy().to_string(),
    ])
    .unwrap();

    let plan_json = read_utf8_lossy(&plan).unwrap();
    let apply_json = read_utf8_lossy(&apply).unwrap();
    let oob =
        read_utf8_lossy(&mod_root.join("history").join("units").join("PRC_1936.txt")).unwrap();
    let backup_exists = mod_root
        .join(".hoi4skill")
        .join("oob_relocation_backup")
        .join("PRC_1936.txt")
        .exists();
    fs::remove_dir_all(&root).unwrap();

    assert!(plan_json.contains("\"schema\": \"hoi4skill.oob_relocation_plan.v1\""));
    assert!(plan_json.contains("\"target_provinces\": [100, 101]"));
    assert!(plan_json.contains("\"source_provinces\": [10, 11]"));
    assert!(plan_json.contains("\"sub_unit\": \"light_armor\", \"count\": 16"));
    assert!(plan_json.contains("\"sub_unit\": \"motorized\", \"count\": 5"));
    assert!(apply_json.contains("\"schema\": \"hoi4skill.oob_relocation_apply.v1\""));
    assert!(apply_json.contains("\"status\": \"oob_relocation_applied\""));
    assert!(backup_exists);
    assert!(oob.contains("name = \"红军一师\" location = 100"));
    assert!(oob.contains("name = \"红军二师\" location = 101"));
    assert!(oob.contains("division_template = {\n\tname = \"红军装甲师\""));
    assert!(oob.contains("light_armor = { x = 0 y = 0 }"));
    assert!(oob.contains("motorized = { x = 1 y = 3 }"));
    assert!(oob.contains("name = \"红军装甲师 1\""));
    assert!(oob.contains("name = \"红军装甲师 2\""));
}

