    assert!(taxonomy_json.contains("\"id\": \"field_hospital\", \"class\": \"support_company\""));
    assert!(intent_json.contains("\"schema\": \"hoi4skill.unit_intent_classify.v1\""));
    assert!(intent_json.contains("\"id\": \"owb_axe_girl\""));
    assert!(intent_json.contains("\"id\": \"field_hospital\""));
