#[test]
fn p93_oob_template_resolve_uses_parent_mod_aliases_without_hardcoding() {
    let root = unique_temp_dir("p93-oob-template-resolve");
    let game_root = root.join("Hearts of Iron IV");
    let mod_root = root.join("target_mod");
    let parent_mod = root.join("parent_mod");
    fs::create_dir_all(game_root.join("common").join("units")).unwrap();
    fs::create_dir_all(parent_mod.join("common").join("units")).unwrap();
    fs::create_dir_all(parent_mod.join("localisation").join("simp_chinese")).unwrap();
    fs::create_dir_all(&mod_root).unwrap();
    fs::write(
        game_root.join("common").join("units").join("00_units.txt"),
        "sub_units = { infantry = { sprite = infantry } }\n",
    )
    .unwrap();
    fs::write(
        parent_mod
            .join("common")
            .join("units")
            .join("custom_units.txt"),
        "sub_units = { owb_axe_girl = { sprite = infantry } owb_ghoul = { sprite = infantry } }\n",
    )
    .unwrap();
    fs::write(
        parent_mod
            .join("localisation")
            .join("simp_chinese")
            .join("custom_units_l_simp_chinese.yml"),
        "l_simp_chinese:\n  owb_axe_girl:0 \"刀斧少女\"\n  owb_ghoul:0 \"尸鬼\"\n",
    )
    .unwrap();

    let taxonomy = root.join("unit_taxonomy.json");
    let resolved = root.join("oob_template_resolve.json");
    let phase = root.join("p93.json");
    cmd_unit_taxonomy_build(&[
        "--game-root".to_string(),
        game_root.to_string_lossy().to_string(),
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--dependency-mod".to_string(),
        parent_mod.to_string_lossy().to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        taxonomy.to_string_lossy().to_string(),
    ])
    .unwrap();
    cmd_oob_template_resolve(&[
        "--taxonomy".to_string(),
        taxonomy.to_string_lossy().to_string(),
        "--text".to_string(),
        "创建废土突击师，五刀斧少女三尸鬼".to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        resolved.to_string_lossy().to_string(),
    ])
    .unwrap();
    cmd_core_capability_audit(&[
        "--phase".to_string(),
        "P93".to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        phase.to_string_lossy().to_string(),
    ])
    .unwrap();

    let json = read_utf8_lossy(&resolved).unwrap();
    let phase_json = read_utf8_lossy(&phase).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(json.contains("\"schema\": \"hoi4skill.oob_template_resolve.v1\""));
    assert!(json.contains("\"status\": \"oob_template_resolved\""));
    assert!(json.contains("\"kind\": \"land\""));
    assert!(json.contains("\"id\": \"owb_axe_girl\""));
    assert!(json.contains("\"id\": \"owb_ghoul\""));
    assert!(json.contains("\"sub_unit\": \"owb_axe_girl\", \"count\": 5"));
    assert!(json.contains("\"sub_unit\": \"owb_ghoul\", \"count\": 3"));
    assert!(json.contains("unit aliases are read from indexed game/parent/target common/units"));
    assert!(phase_json.contains("\"phase_filter\": \"P93\""));
    assert!(phase_json.contains("\"command\": \"oob-template-resolve\""));
    assert!(phase_json.contains("unit-taxonomy-build + oob-kind-classify + division-template-plan + air-oob-plan + naval-oob-plan"));
}

