#[test]
fn p25_division_template_routes_regiments_and_support_then_applies_to_oob() {
    let root = unique_temp_dir("p25-division-template");
    let game_root = root.join("Hearts of Iron IV");
    let mod_root = root.join("target_mod");
    fs::create_dir_all(game_root.join("common").join("units")).unwrap();
    fs::create_dir_all(game_root.join("localisation").join("simp_chinese")).unwrap();
    fs::create_dir_all(mod_root.join("history").join("units")).unwrap();
    fs::write(
        game_root.join("common").join("units").join("00_units.txt"),
        "sub_units = { infantry = { sprite = infantry } artillery_brigade = { sprite = artillery } engineer = { group = support } recon = { group = support } logistics_company = { group = support } }\n",
    )
    .unwrap();
    fs::write(
        game_root
            .join("localisation")
            .join("simp_chinese")
            .join("units_l_simp_chinese.yml"),
        "l_simp_chinese:\n  infantry:0 \"步兵\"\n  artillery_brigade:0 \"炮兵\"\n  engineer:0 \"工兵\"\n  recon:0 \"侦察\"\n  logistics_company:0 \"后勤\"\n",
    )
    .unwrap();
    fs::write(
        mod_root.join("history").join("units").join("PRC_1936.txt"),
        "# existing OOB\n",
    )
    .unwrap();

    let taxonomy = root.join("unit_taxonomy.json");
    cmd_unit_taxonomy_build(&[
        "--game-root".to_string(),
        game_root.to_string_lossy().to_string(),
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        taxonomy.to_string_lossy().to_string(),
    ])
    .unwrap();
    let plan = root.join("division_template_plan.json");
    cmd_division_template_plan(&[
        "--taxonomy".to_string(),
        taxonomy.to_string_lossy().to_string(),
        "--text".to_string(),
        "红军突击师，九步兵三炮兵，支援连：工兵、侦察、后勤".to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        plan.to_string_lossy().to_string(),
    ])
    .unwrap();
    cmd_division_template_audit(&[
        "--input".to_string(),
        plan.to_string_lossy().to_string(),
        "--require-passed".to_string(),
    ])
    .unwrap();
    let apply = root.join("division_template_apply.json");
    cmd_division_template_apply(&[
        "--input".to_string(),
        plan.to_string_lossy().to_string(),
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--oob".to_string(),
        "PRC_1936".to_string(),
        "--execute".to_string(),
        "--final-check".to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        apply.to_string_lossy().to_string(),
    ])
    .unwrap();

    let plan_json = read_utf8_lossy(&plan).unwrap();
    let oob =
        read_utf8_lossy(&mod_root.join("history").join("units").join("PRC_1936.txt")).unwrap();
    let apply_json = read_utf8_lossy(&apply).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(plan_json.contains("\"schema\": \"hoi4skill.division_template_plan.v1\""));
    assert!(plan_json.contains("\"sub_unit\": \"infantry\", \"count\": 9"));
    assert!(plan_json.contains("\"sub_unit\": \"artillery_brigade\", \"count\": 3"));
    assert!(plan_json.contains("\"support\": [{\"sub_unit\": \"engineer\", \"count\": 1"));
    assert!(plan_json.contains("\"sub_unit\": \"recon\", \"count\": 1"));
    assert!(plan_json.contains("\"sub_unit\": \"logistics_company\", \"count\": 1"));
    assert!(apply_json.contains("\"status\": \"division_template_applied\""));
    assert!(oob.contains("division_template = {\n\tname = \"红军突击师\""));
    assert!(oob.contains("\tregiments = {"));
    assert!(oob.contains("infantry = {"));
    assert!(oob.contains("artillery_brigade = {"));
    assert!(oob.contains("\tsupport = {"));
    assert!(oob.contains("engineer = {"));
    assert!(oob.contains("recon = {"));
    assert!(oob.contains("logistics_company = {"));
}

