    let transition_json = read_utf8_lossy(&transition).unwrap();
    let flag_json = read_utf8_lossy(&flag).unwrap();
    let name_json = read_utf8_lossy(&name).unwrap();
    let formation_json = read_utf8_lossy(&formation).unwrap();
