        read_utf8_lossy(&run_dir.join("inputs").join("localisation_placeholders.txt")).unwrap();
    let dry_run =
        read_utf8_lossy(&mod_root.join(".hoi4skill/country_dry_run_country_rus.json")).unwrap();
    let content = read_utf8_lossy(&mod_root.join(".hoi4skill/content_country_rus.json")).unwrap();
