    fs::write(
        mod_root
            .join("common")
            .join("national_focus")
            .join("tgc_rus_focus.txt"),
        "focus_tree = {\n id = tgc_rus_focus_tree\n country = { tag = RUS }\n focus = { id = tgc_rus_opening_congress x = 0 y = 0 completion_reward = { add_political_power = 50 } }\n}\n",
    )
