#[test]
fn large_mod_ai_output_insurance_retrieves_related_code_for_bad_ai_output() {
    let root = unique_temp_dir("large-mod-ai-output-insurance");
    let blueprint_path = root.join("blueprint.yml");
    let mod_root = root.join("mod");
    let game_root = root.join("Hearts of Iron IV");
    let output = root.join("ai_output_insurance.json");
    let markdown_output = root.join("ai_output_insurance.md");

    cmd_plan_large_mod(&[
        "--text".to_string(),
        "name: Test Grand Campaign\ncountries: RUS\nregions: europe".to_string(),
        "--name".to_string(),
        "Test Grand Campaign".to_string(),
        "--acronym".to_string(),
        "TGC".to_string(),
        "--output".to_string(),
        blueprint_path.to_string_lossy().to_string(),
    ])
    .unwrap();
    cmd_init_large_mod(&[
        "--blueprint".to_string(),
        blueprint_path.to_string_lossy().to_string(),
        "--output".to_string(),
        mod_root.to_string_lossy().to_string(),
    ])
    .unwrap();
    fs::create_dir_all(game_root.join("documentation")).unwrap();
    fs::create_dir_all(game_root.join("common").join("dynamic_modifiers")).unwrap();
    fs::write(
        game_root
            .join("documentation")
            .join("effects_documentation.md"),
        "## Effects\n\n## add_political_power\n\n## add_stability\n\n## add_dynamic_modifier\n",
    )
    .unwrap();
    fs::write(
        game_root
            .join("documentation")
            .join("modifiers_documentation.md"),
        "## Modifiers\n\n## stability_factor\n\n## production_factory_max_efficiency_factor\n",
    )
    .unwrap();
    fs::write(
        game_root
            .join("documentation")
            .join("triggers_documentation.md"),
        "## Triggers\n\n## has_war\n\n## has_idea\n",
    )
    .unwrap();
    fs::write(
        game_root
            .join("common")
            .join("dynamic_modifiers")
            .join("tgc_dynamic.txt"),
        "tgc_rus_made_in_country = { icon = GFX_goal_generic_construct_civ_factory production_factory_max_efficiency_factor = temp_tgc_rus_made_in_country }\n",
    )
    .unwrap();

    cmd_large_mod_ai_output_insurance(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--package".to_string(),
        "country_rus".to_string(),
        "--game-root".to_string(),
        game_root.to_string_lossy().to_string(),
        "--text".to_string(),
        "AI输出：completion_reward = { add_politicalpower = 25 }\nvalidator: effect context `completion_reward` uses unknown effect `add_politicalpower`\nvalidator: trigger context `available` uses unknown trigger `haswar`\nlocalisation key `bad` uses unindexed icon `missing_icon`\n【国民党图标】宣布训政\n中国制造 的效果 建造速度+10%\nadd_ideas = tgc_rus_made_in_country".to_string(),
        "--output".to_string(),
        output.to_string_lossy().to_string(),
        "--markdown-output".to_string(),
        markdown_output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let json = read_utf8_lossy(&output).unwrap();
    let markdown = read_utf8_lossy(&markdown_output).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(json.contains("\"schema\": \"hoi4skill.ai_output_insurance.v1\""));
    assert!(json.contains("\"status\": \"ok\""));
    assert!(json.contains("\"retrieval_ok\": true"));
    assert!(json.contains("\"analysis\""));
    assert!(json.contains("\"direct_clausewitz_code\": true"));
    assert!(json.contains("\"dynamic_modifier_as_national_spirit\": true"));
    assert!(json.contains("\"blocking_count\": 3"));
    assert!(json.contains("\"repair_plan\""));
    assert!(json.contains("\"id\": \"direct_clausewitz_code\""));
    assert!(json.contains("\"id\": \"dynamic_modifier_as_national_spirit\""));
    assert!(json.contains("\"id\": \"suspicious_code_tokens\""));
    assert!(json.contains("\"id\": \"localisation_placeholder_or_icon\""));
    assert!(json.contains("plan-dynamic-modifier-change"));
    assert!(json.contains("do not replace add_dynamic_modifier/scripted_effect protocol"));
    assert!(json.contains("author-placeholder-plan"));
    assert!(json.contains("check-text-alignment"));
    assert!(json.contains("\"add_politicalpower\""));
    assert!(json.contains("check-code-symbol effect add_politicalpower"));
    assert!(json.contains("check-code-symbol trigger haswar"));
    assert!(json.contains("dynamic modifier scripted_effect protocol"));
    assert!(json.contains("localisation placeholders icon spriteType"));
    assert!(json.contains("\"schema\": \"hoi4skill.work_package_retrieved_repair_context.v1\""));
    assert!(json.contains("add_political_power"));
    assert!(json.contains("has_war"));
    assert!(json.contains("tgc_rus_made_in_country"));
    assert!(json.contains("If retrieval_ok is false"));
    assert!(markdown.contains("AI Output Insurance"));
    assert!(markdown.contains("Blocking Analysis"));
    assert!(markdown.contains("direct_clausewitz_code: `true`"));
    assert!(markdown.contains("Repair Plan"));
    assert!(markdown.contains("dynamic_modifier_as_national_spirit"));
    assert!(markdown.contains("localisation_placeholder_or_icon"));
    assert!(markdown.contains("Suspect AI Output"));
    assert!(markdown.contains("Retrieved Local Evidence"));
    assert!(markdown.contains("Rust writers still assemble final Clausewitz"));
}

#[test]
fn ai_output_insurance_queries_extract_validation_error_symbols() {
    let package = WorkPackage {
        id: "country_rus".to_string(),
        kind: "country".to_string(),
        title: "RUS Country Content".to_string(),
        allowed_paths: Vec::new(),
        deliverables: Vec::new(),
        validation_steps: Vec::new(),
    };
    let map = parse_args(&[]);
    let queries = ai_output_insurance_queries(
        &package,
        "completion_reward = { add_politicalpower = 25 }\nerror: effect context `completion_reward` uses unknown effect `add_politicalpower`\nlocalisation key `bad` uses unindexed icon `missing_icon`\ntrigger context `available` uses unknown trigger haswar",
        &map,
    );

    assert!(queries.contains(&"add_politicalpower".to_string()));
    assert!(queries.contains(&"effect add_politicalpower".to_string()));
    assert!(queries.contains(&"check-code-symbol effect add_politicalpower".to_string()));
    assert!(queries.contains(&"compile-intent strict-code-index".to_string()));
    assert!(queries.contains(&"structured work package inputs".to_string()));
    assert!(queries.contains(&"haswar".to_string()));
    assert!(queries.contains(&"trigger haswar".to_string()));
    assert!(queries.contains(&"check-code-symbol trigger haswar".to_string()));
    assert!(queries.contains(&"missing_icon".to_string()));
    assert!(queries.contains(&"resource_id missing_icon".to_string()));
    assert!(queries.contains(&"check-code-symbol resource_id missing_icon".to_string()));
    assert!(queries.contains(&"localisation placeholders icon spriteType".to_string()));
    assert!(queries.contains(&"author-placeholder-plan localisation".to_string()));
}

