#[test]
fn run_work_packages_batches_ready_packages_and_skips_blocked_packages() {
    let root = unique_temp_dir("run-work-packages-batch");
    let blueprint_path = root.join("blueprint.yml");
    let mod_root = root.join("mod");
    let plan_output = root.join("run_queue_plan.json");
    let ready_output = root.join("run_queue_ready.json");

    cmd_plan_large_mod(&[
        "--text".to_string(),
        "name: Test Grand Campaign\ncountries: RUS\nregions: europe".to_string(),
        "--name".to_string(),
        "Test Grand Campaign".to_string(),
        "--acronym".to_string(),
        "TGC".to_string(),
        "--output".to_string(),
        blueprint_path.to_string_lossy().to_string(),
    ])
    .unwrap();
    cmd_init_large_mod(&[
        "--blueprint".to_string(),
        blueprint_path.to_string_lossy().to_string(),
        "--output".to_string(),
        mod_root.to_string_lossy().to_string(),
    ])
    .unwrap();

    cmd_run_work_packages(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--max-packages".to_string(),
        "2".to_string(),
        "--output".to_string(),
        plan_output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let plan = read_utf8_lossy(&plan_output).unwrap();
    assert!(plan.contains("\"schema\": \"hoi4skill.run_work_packages.v1\""));
    assert!(plan.contains("\"execute\": false"));
    assert!(plan.contains("\"selected_count\": 2"));
    assert!(plan.contains("\"status\": \"planned\""));
    assert!(plan.contains("run-work-package"));
    assert!(plan.contains("large-mod-capability-audit"));

    cmd_run_work_packages(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--ready-only".to_string(),
        "--max-packages".to_string(),
        "16".to_string(),
        "--output".to_string(),
        ready_output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let ready = read_utf8_lossy(&ready_output).unwrap();
    assert!(ready.contains("\"schema\": \"hoi4skill.run_work_packages.v1\""));
    assert!(ready.contains("\"status\": \"skipped_blocked\""));
    assert!(ready.contains("country_rus"));
    assert!(ready.contains("system_political_paths"));
    assert!(ready.contains("Batch execution is still package-scoped"));
}

