#[test]
fn large_mod_request_template_can_feed_author_work_packages() {
    let root = unique_temp_dir("large-mod-request-template");
    let blueprint_path = root.join("blueprint.yml");
    let mod_root = root.join("mod");
    let template = mod_root.join(".hoi4skill").join("package_requests.md");
    let manifest = mod_root.join(".hoi4skill").join("author_queue.json");
    let blocked_gate = root.join("authoring_gate_blocked.json");
    let ready_gate = root.join("authoring_gate_ready.json");
    let blocked_summary_gate = root.join("authoring_gate_blocked_summary.json");
    let repair_gate = root.join("authoring_gate_author_queue_repair.json");

    cmd_plan_large_mod(&[
        "--text".to_string(),
        "name: Test Grand Campaign\ncountries: RUS\nregions: europe".to_string(),
        "--name".to_string(),
        "Test Grand Campaign".to_string(),
        "--acronym".to_string(),
        "TGC".to_string(),
        "--output".to_string(),
        blueprint_path.to_string_lossy().to_string(),
    ])
    .unwrap();
    cmd_init_large_mod(&[
        "--blueprint".to_string(),
        blueprint_path.to_string_lossy().to_string(),
        "--output".to_string(),
        mod_root.to_string_lossy().to_string(),
    ])
    .unwrap();

    cmd_large_mod_authoring_gate(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--output".to_string(),
        blocked_gate.to_string_lossy().to_string(),
    ])
    .unwrap();
    let blocked_gate_text = read_utf8_lossy(&blocked_gate).unwrap();
    assert!(blocked_gate_text.contains("\"schema\": \"hoi4skill.large_mod_authoring_gate.v1\""));
    assert!(blocked_gate_text.contains("\"authoring_ready\": false"));
    assert!(blocked_gate_text.contains("missing package request template"));
    assert!(blocked_gate_text.contains("\"id\": \"national_focus\""));
    assert!(blocked_gate_text.contains("\"id\": \"events\""));
    assert!(blocked_gate_text.contains("\"id\": \"decisions\""));
    assert!(blocked_gate_text.contains("\"id\": \"national_spirits\""));
    assert!(blocked_gate_text.contains("\"id\": \"dynamic_modifiers\""));
    assert!(blocked_gate_text.contains("\"id\": \"localisation\""));

    cmd_large_mod_request_template(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--package".to_string(),
        "country_rus".to_string(),
        "--output".to_string(),
        template.to_string_lossy().to_string(),
    ])
    .unwrap();
    let template_text = read_utf8_lossy(&template).unwrap();
    assert!(template_text.contains("hoi4skill.large_mod_request_template.v1"));
    assert!(template_text.contains("## country_rus"));
    assert!(template_text.contains("国策："));
    assert!(template_text.contains("事件文案："));
    assert!(template_text.contains("动态修正："));
    assert!(template_text.contains("本地化："));

    let unfilled = cmd_author_work_packages(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--input".to_string(),
        template.to_string_lossy().to_string(),
        "--plan-only".to_string(),
        "--output".to_string(),
        manifest.to_string_lossy().to_string(),
    ])
    .unwrap_err();
    assert!(unfilled.contains("no filled package requests found"));

    fs::write(
        &template,
        template_text.replace(
            "国策：TODO 写这个包要新增或修改的国策标题、路线和效果，例如：整顿政府，效果：政治点数 +50。",
            "国策：没收资本家，效果：稳定度 -10%",
        ),
    )
    .unwrap();

    cmd_author_work_packages(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--input".to_string(),
        template.to_string_lossy().to_string(),
        "--plan-only".to_string(),
        "--output".to_string(),
        manifest.to_string_lossy().to_string(),
    ])
    .unwrap();
    let manifest_text = read_utf8_lossy(&manifest).unwrap();
    assert!(manifest_text.contains("\"schema\": \"hoi4skill.author_work_packages.v1\""));
    assert!(manifest_text.contains("\"status\": \"planned\""));
    assert!(manifest_text.contains("\"request_count\": 1"));
    assert!(manifest_text.contains("country_rus"));
    assert!(manifest_text.contains("\"project_author_queue\""));
    assert!(manifest_text.contains("\"refreshed_artifacts\""));
    assert!(manifest_text.contains("run_summary.json"));
    assert!(manifest_text.contains("input_repair_queue.json"));
    assert!(manifest_text.contains("authoring_gate.json"));
    let package_manifest = read_utf8_lossy(
        &mod_root
            .join(".hoi4skill")
            .join("author_queue")
            .join("country_rus.json"),
    )
    .unwrap();
    assert!(package_manifest.contains("没收资本家"));
    assert!(!package_manifest.contains("TODO"));
    assert!(!package_manifest.contains("- title:"));
    assert!(mod_root.join(".hoi4skill/run_summary.json").is_file());
    assert!(mod_root
        .join(".hoi4skill/input_repair_queue.json")
        .is_file());
    assert!(mod_root.join(".hoi4skill/authoring_gate.json").is_file());
    let auto_gate = read_utf8_lossy(&mod_root.join(".hoi4skill/authoring_gate.json")).unwrap();
    assert!(auto_gate.contains("\"authoring_ready\": true"));
    assert!(auto_gate.contains("\"status\": \"ready\""));
    assert!(auto_gate.contains("\"author_queue_status\": \"planned\""));

    cmd_large_mod_authoring_gate(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--output".to_string(),
        ready_gate.to_string_lossy().to_string(),
    ])
    .unwrap();
    let ready_gate_text = read_utf8_lossy(&ready_gate).unwrap();
    assert!(ready_gate_text.contains("\"authoring_ready\": true"));
    assert!(ready_gate_text.contains("\"status\": \"ready\""));
    assert!(ready_gate_text.contains("\"package_request_template\""));
    assert!(ready_gate_text.contains("\"author_queue\""));
    assert!(ready_gate_text.contains("\"author_queue_status\": \"planned\""));
    assert!(ready_gate_text.contains("\"failed_repair_ready_count\": 0"));
    assert!(ready_gate_text.contains("\"input_repair_queue_status\": \"ok\""));

    fs::write(
        mod_root.join(".hoi4skill").join("run_summary.json"),
        "{\n  \"schema\": \"hoi4skill.large_mod_run_summary.v1\",\n  \"status\": \"needs_review\"\n}\n",
    )
    .unwrap();
    cmd_large_mod_authoring_gate(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--output".to_string(),
        blocked_summary_gate.to_string_lossy().to_string(),
    ])
    .unwrap();
    let blocked_summary_text = read_utf8_lossy(&blocked_summary_gate).unwrap();
    assert!(blocked_summary_text.contains("\"authoring_ready\": false"));
    assert!(blocked_summary_text.contains("\"run_summary_status\": \"needs_review\""));
    assert!(blocked_summary_text.contains("run summary status is needs_review"));
    cmd_large_mod_run_summary(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--output".to_string(),
        mod_root
            .join(".hoi4skill")
            .join("run_summary.json")
            .to_string_lossy()
            .to_string(),
    ])
    .unwrap();

    fs::write(
        &manifest,
        "{\n  \"schema\": \"hoi4skill.author_work_packages.v1\",\n  \"status\": \"needs_repair\",\n  \"failed_repair_ready_count\": 1\n}\n",
    )
    .unwrap();
    cmd_large_mod_authoring_gate(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--output".to_string(),
        repair_gate.to_string_lossy().to_string(),
    ])
    .unwrap();
    let repair_gate_text = read_utf8_lossy(&repair_gate).unwrap();
    assert!(repair_gate_text.contains("\"authoring_ready\": false"));
    assert!(repair_gate_text.contains("\"status\": \"blocked\""));
    assert!(repair_gate_text.contains("\"author_queue_status\": \"needs_repair\""));
    assert!(repair_gate_text.contains("\"failed_repair_ready_count\": 1"));
    assert!(repair_gate_text.contains("author queue has packages needing repair"));
}

#[test]
fn large_mod_authoring_bootstrap_creates_safe_starting_artifacts() {
    let root = unique_temp_dir("large-mod-authoring-bootstrap");
    let blueprint_path = root.join("blueprint.yml");
    let mod_root = root.join("mod");
    let bootstrap = root.join("authoring_bootstrap.json");

    cmd_plan_large_mod(&[
        "--text".to_string(),
        "name: Test Grand Campaign\ncountries: RUS\nregions: europe".to_string(),
        "--name".to_string(),
        "Test Grand Campaign".to_string(),
        "--acronym".to_string(),
        "TGC".to_string(),
        "--output".to_string(),
        blueprint_path.to_string_lossy().to_string(),
    ])
    .unwrap();
    cmd_init_large_mod(&[
        "--blueprint".to_string(),
        blueprint_path.to_string_lossy().to_string(),
        "--output".to_string(),
        mod_root.to_string_lossy().to_string(),
    ])
    .unwrap();

    cmd_large_mod_authoring_bootstrap(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--output".to_string(),
        bootstrap.to_string_lossy().to_string(),
    ])
    .unwrap();

    let bootstrap_text = read_utf8_lossy(&bootstrap).unwrap();
    assert!(bootstrap_text.contains("\"schema\": \"hoi4skill.large_mod_authoring_bootstrap.v1\""));
    assert!(bootstrap_text.contains("\"status\": \"bootstrapped\""));
    assert!(bootstrap_text.contains("package_requests.md"));
    assert!(bootstrap_text.contains("author-work-packages"));
    assert!(mod_root.join(".hoi4skill/package_requests.md").is_file());
    assert!(mod_root.join(".hoi4skill/run_summary.json").is_file());
    assert!(mod_root
        .join(".hoi4skill/input_repair_queue.json")
        .is_file());
    assert!(mod_root.join(".hoi4skill/authoring_gate.json").is_file());
    assert!(!mod_root.join(".hoi4skill/author_queue.json").is_file());

    let gate = read_utf8_lossy(&mod_root.join(".hoi4skill/authoring_gate.json")).unwrap();
    assert!(gate.contains("\"authoring_ready\": false"));
    assert!(gate.contains("missing author-work-packages manifest"));
    assert!(!gate.contains("missing package request template"));
    assert!(!gate.contains("missing run summary"));
    assert!(!gate.contains("missing input repair queue"));
}

#[test]
fn author_work_packages_batches_multiple_user_requests() {
    let root = unique_temp_dir("author-work-packages");
    let blueprint_path = root.join("blueprint.yml");
    let mod_root = root.join("mod");
    let game_root = root.join("Hearts of Iron IV");
    let requests = root.join("package_requests.md");
    let manifest = root.join("author_queue.json");

    cmd_plan_large_mod(&[
        "--text".to_string(),
        "name: Test Grand Campaign\ncountries: RUS\nregions: europe".to_string(),
        "--name".to_string(),
        "Test Grand Campaign".to_string(),
        "--acronym".to_string(),
        "TGC".to_string(),
        "--output".to_string(),
        blueprint_path.to_string_lossy().to_string(),
    ])
    .unwrap();
    cmd_init_large_mod(&[
        "--blueprint".to_string(),
        blueprint_path.to_string_lossy().to_string(),
        "--output".to_string(),
        mod_root.to_string_lossy().to_string(),
    ])
    .unwrap();
    fs::create_dir_all(game_root.join("documentation")).unwrap();
    fs::write(
        game_root
            .join("documentation")
            .join("effects_documentation.md"),
        "## Effects\n\n## add_political_power\n\n## add_stability\n",
    )
    .unwrap();
    fs::write(
        &requests,
        "## country_rus\n中国国策：没收资本家\n事件文案：俄国政府宣布清算资本家\n效果：稳定度 -10%\n\npackage: system_political_paths\n决议：召开政治路线会议\n民族精神：路线争论\n效果：政治点数 +25\n",
    )
    .unwrap();

    cmd_author_work_packages(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--input".to_string(),
        requests.to_string_lossy().to_string(),
        "--game-root".to_string(),
        game_root.to_string_lossy().to_string(),
        "--output".to_string(),
        manifest.to_string_lossy().to_string(),
        "--allow-failure".to_string(),
    ])
    .unwrap();

    let text = read_utf8_lossy(&manifest).unwrap();
    assert!(text.contains("\"schema\": \"hoi4skill.author_work_packages.v1\""));
    assert!(text.contains("\"request_count\": 2"));
    assert!(text.contains("country_rus"));
    assert!(text.contains("system_political_paths"));
    assert!(text.contains("author_queue"));
    assert!(text.contains("repair_bundle_country_rus"));
    assert!(text.contains("input_repair_prompt.md"));
    assert!(text.contains("apply-work-package-repair"));
    assert!(mod_root
        .join(".hoi4skill")
        .join("author_queue")
        .join("country_rus.json")
        .is_file());
    let project_manifest = mod_root.join(".hoi4skill").join("author_queue.json");
    assert!(project_manifest.is_file());
    let project_text = read_utf8_lossy(&project_manifest).unwrap();
    assert!(project_text.contains("\"schema\": \"hoi4skill.author_work_packages.v1\""));
    assert!(project_text.contains("\"refreshed_artifacts\""));
    assert!(mod_root.join(".hoi4skill/run_summary.json").is_file());
    assert!(mod_root
        .join(".hoi4skill/input_repair_queue.json")
        .is_file());
    assert!(mod_root.join(".hoi4skill/authoring_gate.json").is_file());
}

#[test]
fn author_work_packages_text_auto_dispatches_mixed_user_request() {
    let root = unique_temp_dir("author-work-packages-text-dispatch");
    let blueprint_path = root.join("blueprint.yml");
    let mod_root = root.join("mod");
    let manifest = root.join("author_queue.json");
    fs::create_dir_all(&root).unwrap();
    fs::write(
        &blueprint_path,
        r#"schema: "hoi4skill.large_mod_blueprint.v1"
name: "Text Dispatch Test"
acronym: "TDT"
default_language: "simp_chinese"
summary: |-
  Test mixed natural-language request dispatch.
countries:
regions:
systems:
  - id: focus_content
    name: Focus Content
    priority: major
  - id: event_content
    name: Event Content
    priority: major
  - id: decision_content
    name: Decision Content
    priority: major
  - id: national_spirit_content
    name: National Spirit Content
    priority: major
  - id: dynamic_modifier_content
    name: Dynamic Modifier Content
    priority: major
  - id: localisation_content
    name: Localisation Content
    priority: major
milestones:
asset_needs:
localisation_languages:
  - simp_chinese
"#,
    )
    .unwrap();
    cmd_init_large_mod(&[
        "--blueprint".to_string(),
        blueprint_path.to_string_lossy().to_string(),
        "--output".to_string(),
        mod_root.to_string_lossy().to_string(),
    ])
    .unwrap();

    cmd_author_work_packages(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--text".to_string(),
        "国策：没收资本家 效果：增加民族精神 资本家的反抗；事件文案：【红色：【中共旗子】【中华人民共和国】领导人【中共领导人】】宣布中华人民共和国成立；决议：镇压资本家 花费25政治点数 效果稳定度+5%；民族精神：资本家的反抗 稳定度 -10%；动态修正：中国制造 建造速度+10%；生产效率上限 +0.05；本地化：【国民党图标】【中华民国国旗】中华民国国民政府训政。".to_string(),
        "--plan-only".to_string(),
        "--output".to_string(),
        manifest.to_string_lossy().to_string(),
    ])
    .unwrap();

    let generated = read_utf8_lossy(
        &mod_root
            .join(".hoi4skill")
            .join("package_requests_from_text.md"),
    )
    .unwrap();
    let manifest_text = read_utf8_lossy(&manifest).unwrap();
    assert!(mod_root.join(".hoi4skill/execution_queue.json").is_file());
    fs::remove_dir_all(&root).unwrap();

    assert!(manifest_text.contains("\"request_source\": \"text\""));
    assert!(manifest_text.contains("\"auto_dispatched\": true"));
    assert!(manifest_text.contains("\"generated_request_file\":"));
    assert!(manifest_text.contains("execution_queue.json"));
    assert!(generated.contains("## system_focus_content"));
    assert!(generated.contains("国策：没收资本家"));
    assert!(generated.contains("## system_event_content"));
    assert!(generated.contains("事件文案：【红色："));
    assert!(generated.contains("## system_decision_content"));
    assert!(generated.contains("决议：镇压资本家"));
    assert!(generated.contains("## system_national_spirit_content"));
    assert!(generated.contains("民族精神：资本家的反抗"));
    assert!(generated.contains("## system_dynamic_modifier_content"));
    assert!(generated.contains("动态修正：中国制造"));
    assert!(generated.contains("生产效率上限 +0.05"));
    assert!(generated.contains("## system_localisation_content"));
    assert!(generated.contains("本地化：【国民党图标】"));

    let focus_section = generated
        .split("## system_focus_content")
        .nth(1)
        .unwrap()
        .split("## ")
        .next()
        .unwrap();
    let event_section = generated
        .split("## system_event_content")
        .nth(1)
        .unwrap()
        .split("## ")
        .next()
        .unwrap();
    let dynamic_section = generated
        .split("## system_dynamic_modifier_content")
        .nth(1)
        .unwrap()
        .split("## ")
        .next()
        .unwrap();
    let localisation_section = generated
        .split("## system_localisation_content")
        .nth(1)
        .unwrap()
        .split("## ")
        .next()
        .unwrap();
    assert!(!focus_section.contains("动态修正"));
    assert!(!event_section.contains("本地化：【国民党图标】"));
    assert!(!dynamic_section.contains("民族精神："));
    assert!(!localisation_section.contains("决议：镇压资本家"));
}

