#[test]
fn author_work_package_csv_row_parser_handles_quotes_commas_and_escapes() {
    let cells = split_author_work_package_table_row(
        "lane,title,effect,\"文案, 带逗号\",\"他说\"\"开始\"\"\"",
    );

    assert_eq!(
        cells,
        vec![
            "lane".to_string(),
            "title".to_string(),
            "effect".to_string(),
            "文案, 带逗号".to_string(),
            "他说\"开始\"".to_string(),
        ]
    );

    let semicolon_cells = split_author_work_package_table_row(
        "package_id;content_type;title;effect;\"文案; 带分号\"",
    );
    assert_eq!(
        semicolon_cells,
        vec![
            "package_id".to_string(),
            "content_type".to_string(),
            "title".to_string(),
            "effect".to_string(),
            "文案; 带分号".to_string(),
        ]
    );

    let fullwidth_cells =
        split_author_work_package_table_row("包名，模块类型，标题，效果，\"文案，带全角逗号\"");
    assert_eq!(
        fullwidth_cells,
        vec![
            "包名".to_string(),
            "模块类型".to_string(),
            "标题".to_string(),
            "效果".to_string(),
            "文案，带全角逗号".to_string(),
        ]
    );
}

