#[test]
fn author_work_package_text_preserves_event_options_and_placeholder_preflight() {
    let root = unique_temp_dir("author-work-package-event-options-preflight");
    let blueprint_path = root.join("blueprint.yml");
    let mod_root = root.join("mod");
    let output_dir = root.join("run_country_chi");
    let output = root.join("author.json");
    fs::create_dir_all(&root).unwrap();
    cmd_plan_large_mod(&[
        "--text".to_string(),
        "name: Event Option Preflight Test\ncountries: CHI\nregions: asia".to_string(),
        "--name".to_string(),
        "Event Option Preflight Test".to_string(),
        "--acronym".to_string(),
        "EOP".to_string(),
        "--output".to_string(),
        blueprint_path.to_string_lossy().to_string(),
    ])
    .unwrap();
    cmd_init_large_mod(&[
        "--blueprint".to_string(),
        blueprint_path.to_string_lossy().to_string(),
        "--output".to_string(),
        mod_root.to_string_lossy().to_string(),
    ])
    .unwrap();

    cmd_author_work_package(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--package".to_string(),
        "country_chi".to_string(),
        "--text".to_string(),
        "事件链：开局党政会议 -> 建国宣言\n类型：news_event\n图片：GFX_report_event_generic_political_meeting\n触发：has_war = no\n描述：【红色：【中共旗子】【中华人民共和国】领导人】宣布建国\n立即效果：政治点+10\n收尾隐藏效果：稳定度+1%\n选项A：继续会议\n选项A条件：战争中\n提示A：该选项会推进建国会议。\n效果预览A：政治点+25\n效果A：政治点+25\n隐藏效果A：设置旗标 congress_continued\n后续事件A：建国宣言\n延迟A：3\n选项B：稳定局势\n提示B：降低短期风险。\n效果B：稳定度+5%\nAI权重B：25\n本地化：【国民党图标】【中华民国国旗】中华民国国民政府训政。".to_string(),
        "--plan-only".to_string(),
        "--output-dir".to_string(),
        output_dir.to_string_lossy().to_string(),
        "--output".to_string(),
        output.to_string_lossy().to_string(),
    ])
    .unwrap();

    let report = read_utf8_lossy(&output).unwrap();
    let ingest_report = read_utf8_lossy(&output_dir.join("ingest_report.json")).unwrap();
    let events = read_utf8_lossy(&output_dir.join("inputs/event_cards.txt")).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(report.contains("\"status\": \"planned\""));
    assert!(events.contains("类型：news_event"));
    assert!(events.contains("图片：GFX_report_event_generic_political_meeting"));
    assert!(events.contains("触发：has_war = no"));
    assert!(events.contains("立即效果：add_political_power = 10"));
    assert!(events.contains("收尾隐藏效果：add_stability = 0.01"));
    assert!(events.contains("选项A：继续会议"));
    assert!(events.contains("选项A条件：战争中"));
    assert!(events.contains("提示A：该选项会推进建国会议"));
    assert!(events.contains("效果预览A：add_political_power = 25"));
    assert!(events.contains("效果A：add_political_power = 25"));
    assert!(events.contains("隐藏效果A：设置旗标 congress_continued"));
    assert!(events.contains("后续事件A：建国宣言"));
    assert!(events.contains("延迟A：3"));
    assert!(events.contains("选项B：稳定局势"));
    assert!(events.contains("提示B：降低短期风险"));
    assert!(events.contains("效果B：add_stability = 0.05"));
    assert!(events.contains("AI权重B：25"));
    assert!(ingest_report.contains("\"placeholder_preflight\""));
    assert!(ingest_report.contains("\"icon_count\": 1"));
    assert!(ingest_report.contains("\"country_or_cosmetic_count\": 2"));
    assert!(ingest_report.contains("needs indexed icon evidence"));
    assert!(ingest_report.contains("needs country/cosmetic tag evidence"));
}

