#[test]
fn localisation_placeholder_preflight_classifies_color_icon_country_and_unknown() {
    let (json, questions) = work_package_localisation_placeholder_preflight_json(
        "【红色：【国民党图标】【中华民国国旗】中华民国国民政府】【未知概念】",
    );

    assert!(json.contains("\"placeholder_count\": 4"));
    assert!(json.contains("\"kind\": \"color\""));
    assert!(json.contains("\"kind\": \"icon\""));
    assert!(json.contains("\"kind\": \"country_or_cosmetic_alias\""));
    assert!(json.contains("\"kind\": \"unknown\""));
    assert!(json.contains("\"requires_author_placeholder_plan\": true"));
    assert!(questions
        .iter()
        .any(|q| q.contains("indexed icon evidence")));
    assert!(questions
        .iter()
        .any(|q| q.contains("country/cosmetic tag evidence")));
    assert!(questions
        .iter()
        .any(|q| q.contains("not a built-in placeholder")));
}

