#[test]
fn large_mod_build_workflow_runs_author_repair_and_production_from_input_dir() {
    let root = unique_temp_dir("large-mod-build-workflow");
    let blueprint_path = root.join("blueprint.yml");
    let mod_root = root.join("mod");
    let input_dir = root.join("requests");
    let repair_input_dir = root.join("ai_repair_inputs");
    let output = root.join("build_workflow.json");
    let author_output = root.join("author_workflow.json");
    let repair_output = root.join("repair_workflow.json");
    let production_output = root.join("production_workflow.json");
    let acceptance_output = root.join("build_acceptance.json");
    fs::create_dir_all(&input_dir).unwrap();
    fs::create_dir_all(&repair_input_dir).unwrap();
    fs::write(
        input_dir.join("request.csv"),
        "package,lane,title,description,effect\ncountry_chi,focus,没收资本家,整顿资本集团,增加民族精神：资本家的反抗：稳定度 -10%\ncountry_chi,event,建国宣言,【红色：中华人民共和国成立】,add_political_power = 50\ncountry_chi,decision,镇压资本家,花费25政治点数,add_stability = 0.05\n",
    )
    .unwrap();

    cmd_plan_large_mod(&[
        "--text".to_string(),
        "name: Build Workflow Test\ncountries: CHI\nregions: asia".to_string(),
        "--name".to_string(),
        "Build Workflow Test".to_string(),
        "--acronym".to_string(),
        "BWT".to_string(),
        "--output".to_string(),
        blueprint_path.to_string_lossy().to_string(),
    ])
    .unwrap();
    cmd_init_large_mod(&[
        "--blueprint".to_string(),
        blueprint_path.to_string_lossy().to_string(),
        "--output".to_string(),
        mod_root.to_string_lossy().to_string(),
    ])
    .unwrap();

    cmd_large_mod_build_workflow(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--input-dir".to_string(),
        input_dir.to_string_lossy().to_string(),
        "--repair-input-dir".to_string(),
        repair_input_dir.to_string_lossy().to_string(),
        "--package".to_string(),
        "country_chi".to_string(),
        "--plan-only".to_string(),
        "--skip-evidence-refresh".to_string(),
        "--author-workflow-output".to_string(),
        author_output.to_string_lossy().to_string(),
        "--repair-workflow-output".to_string(),
        repair_output.to_string_lossy().to_string(),
        "--production-workflow-output".to_string(),
        production_output.to_string_lossy().to_string(),
        "--acceptance-output".to_string(),
        acceptance_output.to_string_lossy().to_string(),
        "--output".to_string(),
        output.to_string_lossy().to_string(),
    ])
    .unwrap();

    let report = read_utf8_lossy(&output).unwrap();
    let author = read_utf8_lossy(&author_output).unwrap();
    let repair = read_utf8_lossy(&repair_output).unwrap();
    let production = read_utf8_lossy(&production_output).unwrap();
    let acceptance = read_utf8_lossy(&acceptance_output).unwrap();
    let generated =
        read_utf8_lossy(&mod_root.join(".hoi4skill/package_requests_from_sources.md")).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(report.contains("\"schema\": \"hoi4skill.large_mod_build_workflow.v1\""));
    assert!(report.contains("\"author_workflow\""));
    assert!(report.contains("\"repair_workflow\""));
    assert!(report.contains("\"production_workflow\""));
    assert!(report.contains("\"acceptance_report\""));
    assert!(report.contains("\"acceptance_status\""));
    assert!(report.contains("\"author_status\""));
    assert!(report.contains("\"repair_status\""));
    assert!(report.contains("\"production_status\""));
    assert!(report.contains("Use repair-input-dir only for AI repair fenced blocks"));
    assert!(author.contains("\"schema\": \"hoi4skill.large_mod_author_workflow.v1\""));
    assert!(repair.contains("\"schema\": \"hoi4skill.large_mod_repair_workflow.v1\""));
    assert!(production.contains("\"schema\": \"hoi4skill.large_mod_production_workflow.v1\""));
    assert!(acceptance.contains("\"schema\": \"hoi4skill.large_mod_build_acceptance.v1\""));
    assert!(acceptance.contains("\"raw_table_leak\": false"));
    assert!(acceptance.contains("\"source_lanes\""));
    assert!(generated.contains("事件：建国宣言"));
    assert!(generated.contains("决议：镇压资本家"));
    assert!(!generated.contains("package,lane,title,description,effect"));
}

#[test]
fn large_mod_build_acceptance_blocks_raw_table_leak_when_requested() {
    let root = unique_temp_dir("large-mod-build-acceptance-leak");
    let mod_root = root.join("mod");
    let hoi4 = mod_root.join(".hoi4skill");
    fs::create_dir_all(&hoi4).unwrap();
    let request = hoi4.join("package_requests_from_sources.md");
    let sources = hoi4.join("package_request_sources.json");
    let author = hoi4.join("large_mod_author_workflow.json");
    let repair = hoi4.join("large_mod_repair_workflow.json");
    let production = hoi4.join("large_mod_production_workflow.json");
    let output = root.join("acceptance.json");
    fs::write(
        &request,
        "# generated\npackage,lane,title,description,effect\ncountry_chi,event,建国宣言,文本,add_political_power = 50\n",
    )
    .unwrap();
    fs::write(
        &sources,
        format!(
            "{{\n  \"schema\": \"hoi4skill.author_work_package_sources.v1\",\n  \"status\": \"ok\",\n  \"request_file\": {},\n  \"source_count\": 1,\n  \"sources\": [{{\"path\": \"request.csv\", \"kind\": \"table_text\", \"packages\": [\"country_chi\"], \"lanes\": [\"event\"]}}]\n}}\n",
            json_str(&request.display().to_string())
        ),
    )
    .unwrap();
    fs::write(
        &author,
        "{\n  \"schema\": \"hoi4skill.large_mod_author_workflow.v1\",\n  \"status\": \"planned\"\n}\n",
    )
    .unwrap();
    fs::write(
        &repair,
        "{\n  \"schema\": \"hoi4skill.large_mod_repair_workflow.v1\",\n  \"status\": \"needs_ai_input_repair\"\n}\n",
    )
    .unwrap();
    fs::write(
        &production,
        "{\n  \"schema\": \"hoi4skill.large_mod_production_workflow.v1\",\n  \"status\": \"needs_review\", \"semiauto_ready\": false, \"release_ready\": false\n}\n",
    )
    .unwrap();

    let err = cmd_large_mod_build_acceptance(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--author-report".to_string(),
        author.to_string_lossy().to_string(),
        "--repair-report".to_string(),
        repair.to_string_lossy().to_string(),
        "--production-report".to_string(),
        production.to_string_lossy().to_string(),
        "--request-sources-report".to_string(),
        sources.to_string_lossy().to_string(),
        "--fail-on-blockers".to_string(),
        "--output".to_string(),
        output.to_string_lossy().to_string(),
    ])
    .unwrap_err();
    let report = read_utf8_lossy(&output).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(err.contains("ok=false"));
    assert!(report.contains("\"raw_table_leak\": true"));
    assert!(report.contains("request_file_contains_raw_table_header"));
}

#[test]
fn large_mod_build_acceptance_requires_strict_validation_and_text_alignment() {
    let root = unique_temp_dir("large-mod-build-acceptance-final-validation");
    let mod_root = root.join("mod");
    let hoi4 = mod_root.join(".hoi4skill");
    fs::create_dir_all(&hoi4).unwrap();
    let request = hoi4.join("package_requests_from_sources.md");
    let sources = hoi4.join("package_request_sources.json");
    let author = hoi4.join("large_mod_author_workflow.json");
    let repair = hoi4.join("large_mod_repair_workflow.json");
    let production = hoi4.join("large_mod_production_workflow.json");
    let validation = hoi4.join("validation.json");
    let text_alignment = hoi4.join("text_alignment.json");
    let output = root.join("acceptance.json");
    let repair_dir = root.join("build_acceptance_repair");
    fs::write(
        &request,
        "# generated\n事件：建国宣言\n效果：add_political_power = 50\n",
    )
    .unwrap();
    fs::write(
        &sources,
        format!(
            "{{\n  \"schema\": \"hoi4skill.author_work_package_sources.v1\",\n  \"status\": \"ok\",\n  \"request_file\": {},\n  \"source_count\": 1,\n  \"sources\": [{{\"path\": \"request.txt\", \"kind\": \"plain_text\", \"packages\": [\"country_chi\"], \"lanes\": [\"focus\", \"event\", \"decision\", \"national_spirit\", \"dynamic_modifier\", \"localisation\"]}}]\n}}\n",
            json_str(&request.display().to_string())
        ),
    )
    .unwrap();
    fs::write(
        &author,
        "{\n  \"schema\": \"hoi4skill.large_mod_author_workflow.v1\",\n  \"status\": \"planned\"\n}\n",
    )
    .unwrap();
    fs::write(
        &repair,
        "{\n  \"schema\": \"hoi4skill.large_mod_repair_workflow.v1\",\n  \"status\": \"ok\"\n}\n",
    )
    .unwrap();
    fs::write(
        &production,
        "{\n  \"schema\": \"hoi4skill.large_mod_production_workflow.v1\",\n  \"status\": \"ok\", \"semiauto_ready\": true, \"release_ready\": false\n}\n",
    )
    .unwrap();

    let missing_err = cmd_large_mod_build_acceptance(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--author-report".to_string(),
        author.to_string_lossy().to_string(),
        "--repair-report".to_string(),
        repair.to_string_lossy().to_string(),
        "--production-report".to_string(),
        production.to_string_lossy().to_string(),
        "--request-sources-report".to_string(),
        sources.to_string_lossy().to_string(),
        "--validation-report".to_string(),
        validation.to_string_lossy().to_string(),
        "--text-alignment-report".to_string(),
        text_alignment.to_string_lossy().to_string(),
        "--require-six-lanes".to_string(),
        "--require-ready".to_string(),
        "--require-final-validation".to_string(),
        "--write-repair-context".to_string(),
        "--repair-output-dir".to_string(),
        repair_dir.to_string_lossy().to_string(),
        "--fail-on-blockers".to_string(),
        "--output".to_string(),
        output.to_string_lossy().to_string(),
    ])
    .unwrap_err();
    let missing_report = read_utf8_lossy(&output).unwrap();
    assert!(missing_err.contains("ok=false"));
    assert!(missing_report.contains("missing_validation_report"));
    assert!(missing_report.contains("missing_text_alignment_report"));
    assert!(missing_report.contains("\"lane_completion_percent\": 100"));
    assert!(missing_report.contains("\"overall_completion_percent\""));
    assert!(repair_dir.join("manifest.json").exists());
    assert!(repair_dir.join("acceptance_repair_context.json").exists());
    assert!(repair_dir.join("acceptance_repair_context.md").exists());
    assert!(repair_dir.join("acceptance_repair_prompt.md").exists());
    let repair_manifest = read_utf8_lossy(&repair_dir.join("manifest.json")).unwrap();
    let repair_prompt = read_utf8_lossy(&repair_dir.join("acceptance_repair_prompt.md")).unwrap();
    assert!(
        repair_manifest.contains("\"schema\": \"hoi4skill.large_mod_build_acceptance_repair.v1\"")
    );
    assert!(repair_manifest.contains("\"retrieval_status\": \"missing_game_root\""));
    assert!(repair_prompt.contains("Large Mod Build Acceptance Repair Prompt"));
    assert!(repair_prompt.contains("Do not bypass build acceptance"));

    fs::write(
        &validation,
        "{\n  \"schema\": \"hoi4skill.validation_report.v1\",\n  \"ok\": true,\n  \"status\": \"ok\",\n  \"game_root\": \"C:/Games/Hearts of Iron IV\",\n  \"strict_code_index\": false,\n  \"effective_errors\": 1\n}\n",
    )
    .unwrap();
    fs::write(&text_alignment, clean_text_alignment_json()).unwrap();
    let bad_validation_err = cmd_large_mod_build_acceptance(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--author-report".to_string(),
        author.to_string_lossy().to_string(),
        "--repair-report".to_string(),
        repair.to_string_lossy().to_string(),
        "--production-report".to_string(),
        production.to_string_lossy().to_string(),
        "--request-sources-report".to_string(),
        sources.to_string_lossy().to_string(),
        "--validation-report".to_string(),
        validation.to_string_lossy().to_string(),
        "--text-alignment-report".to_string(),
        text_alignment.to_string_lossy().to_string(),
        "--require-six-lanes".to_string(),
        "--require-ready".to_string(),
        "--require-final-validation".to_string(),
        "--fail-on-blockers".to_string(),
        "--output".to_string(),
        output.to_string_lossy().to_string(),
    ])
    .unwrap_err();
    let bad_validation_report = read_utf8_lossy(&output).unwrap();
    assert!(bad_validation_err.contains("ok=false"));
    assert!(bad_validation_report.contains("strict_code_index_missing_or_false"));
    assert!(bad_validation_report.contains("validation_errors_present"));
    assert!(bad_validation_report.contains("effective_errors=1"));

    fs::write(&validation, clean_strict_validation_report_json()).unwrap();
    cmd_large_mod_build_acceptance(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--author-report".to_string(),
        author.to_string_lossy().to_string(),
        "--repair-report".to_string(),
        repair.to_string_lossy().to_string(),
        "--production-report".to_string(),
        production.to_string_lossy().to_string(),
        "--request-sources-report".to_string(),
        sources.to_string_lossy().to_string(),
        "--validation-report".to_string(),
        validation.to_string_lossy().to_string(),
        "--text-alignment-report".to_string(),
        text_alignment.to_string_lossy().to_string(),
        "--require-six-lanes".to_string(),
        "--require-ready".to_string(),
        "--require-final-validation".to_string(),
        "--fail-on-blockers".to_string(),
        "--output".to_string(),
        output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let ok_report = read_utf8_lossy(&output).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(ok_report.contains("\"ok\": true"));
    assert!(ok_report.contains("\"validation_ok\": true"));
    assert!(ok_report.contains("\"strict_code_index\": true"));
    assert!(ok_report.contains("\"text_alignment_ok\": true"));
    assert!(ok_report.contains("\"blocking_count\": 0"));
}

