    fs::create_dir_all(&interface_dir).unwrap();
    fs::write(
        scripted_gui_dir.join("test_gui.txt"),
        "scripted_gui = {\n  test_decision_gui = { context_type = decision_category window_name = \"test_decision_window\" }\n  test_standalone_gui = { context_type = player_context parent_window_token = top_bar window_name = \"test_standalone_window\" visible = { has_country_flag = open_test_gui } effects = { close_test_gui_click = { clr_country_flag = open_test_gui } } }\n}\n",
    )
