#[test]
fn gui_kind_template_gate_requires_kind_specific_template_evidence() {
    let root = unique_temp_dir("gui-kind-template-gate");
    let style_template = root.join("gui_style_template.json");
    let package_dir = root.join("style_package");
    fs::create_dir_all(&package_dir).unwrap();
    fs::write(
        &style_template,
        "{\n  \"schema\": \"hoi4skill.gui_style_template.v1\",\n  \"ok\": true,\n  \"gui_kind\": \"standalone\",\n  \"patterns\": {\"decision_attached_gui\": false, \"standalone_gui\": true, \"mount_points\": false, \"tdr_map_gui\": false}\n}\n",
    )
    .unwrap();
    let blocked_output = root.join("blocked_kind_gate.json");
    let err = cmd_gui_kind_template_gate(&[
        "--gui-kind".to_string(),
        "decision_attached".to_string(),
        "--style-template".to_string(),
        style_template.to_string_lossy().to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        blocked_output.to_string_lossy().to_string(),
    ])
    .unwrap_err();
    let blocked = read_utf8_lossy(&blocked_output).unwrap();
    assert_eq!(err, "gui-kind-template-gate did not pass");
    assert!(blocked.contains("\"kind_template_ready\": false"));
    assert!(blocked.contains("kind_specific_template_evidence:decision_attached"));

    fs::write(
        package_dir.join("gui_style_template_package.json"),
        "{\n  \"schema\": \"hoi4skill.gui_style_template_package.v1\",\n  \"status\": \"written\",\n  \"parent_mods\": [\"parent\"],\n  \"style_tokens\": \"style_tokens.json\",\n  \"control_examples\": \"control_examples.json\",\n  \"mount_examples\": \"mount_examples.json\",\n  \"resource_index\": \"resource_index.json\",\n  \"visual_template_examples\": \"visual_template_examples.json\"\n}\n",
    )
    .unwrap();
    fs::write(
        package_dir.join("style_tokens.json"),
        "{\n  \"schema\": \"hoi4skill.gui_style_tokens.v1\",\n  \"style_tokens\": {\"style_token_evidence\": [\"parent/interface/demo.gui:1\"], \"fonts\": [\"hoi_18mbs\"], \"sprites\": [\"GFX_panel\"]}\n}\n",
    )
    .unwrap();
    fs::write(
        package_dir.join("control_examples.json"),
        "{\n  \"schema\": \"hoi4skill.gui_control_examples.v1\",\n  \"controls\": [{\"control_type\": \"button\", \"usable_by_writer\": true, \"evidence\": [\"parent/interface/demo.gui:2\"]}]\n}\n",
    )
    .unwrap();
    fs::write(
        package_dir.join("mount_examples.json"),
        "{\n  \"schema\": \"hoi4skill.gui_mount_examples.v1\",\n  \"examples\": {\"scripted_guis\": [{\"id\": \"parent_decision_gui\", \"context_type\": \"decision_category\", \"window_name\": \"parent_decision_window\"}]},\n  \"mount_contracts\": {\"decision_attached\": {\"requirements\": [\"context_type=decision_category\", \"decision category must mount scripted_gui\"]}}\n}\n",
    )
    .unwrap();
    fs::write(
        package_dir.join("resource_index.json"),
        "{\n  \"schema\": \"hoi4skill.gui_resource_index.v1\",\n  \"sprites\": [\"GFX_panel\"],\n  \"fonts\": [\"hoi_18mbs\"],\n  \"evidence\": [\"parent/interface/demo.gfx:1\"]\n}\n",
    )
    .unwrap();
    fs::write(
        package_dir.join("visual_template_examples.json"),
        "{\n  \"schema\": \"hoi4skill.gui_visual_template_examples.v1\",\n  \"visual_roles\": [\"panel_background\"],\n  \"templates\": [{\"visual_role\": \"panel_background\", \"evidence\": [\"parent/interface/demo.gui:3\"]}]\n}\n",
    )
    .unwrap();
    let passed_output = root.join("passed_kind_gate.json");
    cmd_gui_kind_template_gate(&[
        "--gui-kind".to_string(),
        "decision_attached".to_string(),
        "--style-template-package".to_string(),
        package_dir
            .join("gui_style_template_package.json")
            .to_string_lossy()
            .to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        passed_output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let passed = read_utf8_lossy(&passed_output).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(passed.contains("\"schema\": \"hoi4skill.gui_kind_template_gate.v1\""));
    assert!(passed.contains("\"kind_template_ready\": true"));
    assert!(passed.contains("\"package_mount_contract_ready\": true"));
    assert!(passed.contains("\"package_kind_example_ready\": true"));
}

#[test]
fn gui_unknown_blockers_gate_blocks_saved_guess_code_and_accepts_questions() {
    let root = unique_temp_dir("gui-unknown-blockers-gate");
    let workflow = root.join("gui_request_workflow.json");
    let apply = root.join("apply_gui_intent.json");
    let safe_output = root.join("safe_unknown_gate.json");
    let blocked_output = root.join("blocked_unknown_gate.json");
    fs::create_dir_all(&root).unwrap();
    fs::write(
        &workflow,
        "{\n  \"schema\": \"hoi4skill.gui_request_workflow.v1\",\n  \"status\": \"intent_blocked\",\n  \"ok\": false,\n  \"final_code_safety_status\": \"blocked_no_clausewitz_candidate\",\n  \"blockers\": [\"unknown_gui_sprite_ref:GFX_missing_icon\"],\n  \"questions\": [\"Should GFX_missing_icon be created or mapped to an existing icon?\"],\n  \"recommended_game_code\": [\n    {\"role\": \"sprite_candidate\", \"status\": \"evidence_required\", \"written_to_mod\": false}\n  ]\n}\n",
    )
    .unwrap();
    fs::write(
        &apply,
        "{\n  \"schema\": \"hoi4skill.apply_gui_intent.v1\",\n  \"ok\": false,\n  \"changed_files\": []\n}\n",
    )
    .unwrap();
    cmd_gui_unknown_blockers_gate(&[
        "--workflow-report".to_string(),
        workflow.to_string_lossy().to_string(),
        "--apply-report".to_string(),
        apply.to_string_lossy().to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        safe_output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let safe = read_utf8_lossy(&safe_output).unwrap();
    assert!(safe.contains("\"schema\": \"hoi4skill.gui_unknown_blockers_gate.v1\""));
    assert!(safe.contains("\"unknown_blockers_ready\": true"));
    assert!(safe.contains("\"no_guessed_code_saved\": true"));

    fs::write(
        &apply,
        "{\n  \"schema\": \"hoi4skill.apply_gui_intent.v1\",\n  \"ok\": false,\n  \"changed_files\": [\"interface/bad_guess.gui\"]\n}\n",
    )
    .unwrap();
    let err = cmd_gui_unknown_blockers_gate(&[
        "--workflow-report".to_string(),
        workflow.to_string_lossy().to_string(),
        "--apply-report".to_string(),
        apply.to_string_lossy().to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        blocked_output.to_string_lossy().to_string(),
    ])
    .unwrap_err();
    let blocked = read_utf8_lossy(&blocked_output).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert_eq!(err, "gui-unknown-blockers-gate did not pass");
    assert!(blocked.contains("\"unknown_blockers_ready\": false"));
    assert!(blocked.contains("\"no_guessed_code_saved\": false"));
    assert!(blocked.contains("interface/bad_guess.gui"));
}

