#[test]
fn gui_request_workflow_blocks_compact_raw_gui_code_without_writing_intent() {
    let root = unique_temp_dir("gui-request-workflow-compact-raw-gui");
    let target = root.join("target_mod");
    let style = root.join("style_mod");
    let game_root = root.join("game_root");
    let output_dir = root.join("workflow");
    let output = root.join("workflow.json");
    write_gui_intent_test_style_mod(&style);
    fs::create_dir_all(&target).unwrap();
    fs::create_dir_all(&game_root).unwrap();
    let text_only_syntax_gate = root.join("text_only_syntax_gate.json");
    let text_only_err = cmd_gui_syntax_safety_gate(&[
        "--text".to_string(),
        "guiTypes={containerWindowType={name=\"bad_window\" buttonType={name=\"bad\"}}}"
            .to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        text_only_syntax_gate.to_string_lossy().to_string(),
    ])
    .unwrap_err();

    let err = cmd_gui_request_workflow(&[
        "--mod-root".to_string(),
        target.to_string_lossy().to_string(),
        "--style-mod".to_string(),
        style.to_string_lossy().to_string(),
        "--game-root".to_string(),
        game_root.to_string_lossy().to_string(),
        "--text".to_string(),
        "做一个工业GUI\n```txt\nguiTypes={containerWindowType={name=\"bad_window\" buttonType={name=\"bad\"}}}\n```\n".to_string(),
        "--prefix".to_string(),
        "compact_raw_panel".to_string(),
        "--output-dir".to_string(),
        output_dir.to_string_lossy().to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        output.to_string_lossy().to_string(),
    ])
    .unwrap_err();

    let report = read_utf8_lossy(&output).unwrap();
    let syntax_gate = read_utf8_lossy(&output_dir.join("gui_syntax_safety_gate.json")).unwrap();
    let text_only_syntax_gate = read_utf8_lossy(&text_only_syntax_gate).unwrap();
    assert!(!output_dir.join("gui_intent.md").exists());
    assert!(!target.join("interface").exists());
    fs::remove_dir_all(&root).unwrap();

    assert_eq!(err, "gui-request-workflow did not pass");
    assert!(report.contains("\"status\": \"intent_blocked\""));
    assert!(report.contains("raw_gui_code_in_natural_language_request"));
    assert!(report.contains("blocked_no_clausewitz_candidate"));
    assert!(report.contains("gui_evidence_required"));
    assert!(!report.contains("<verified_GFX_button_sprite>"));
    assert_eq!(text_only_err, "gui-syntax-safety-gate did not pass");
    assert!(text_only_syntax_gate.contains("\"status\": \"raw_syntax_requires_workflow_block\""));
    assert!(syntax_gate.contains("\"status\": \"raw_syntax_blocked\""));
    assert!(syntax_gate.contains("\"raw_syntax_blocked\": true"));
}

