    let report = read_utf8_lossy(&output).unwrap();
    let apply_report = read_utf8_lossy(&output_dir.join("apply_gui_intent.json")).unwrap();
    let related_context =
        read_utf8_lossy(&output_dir.join("gui_related_code_context.json")).unwrap();
    assert!(!target
        .join("interface")
        .join("apply_blocker_panel_window.gui")
        .exists());
