    assert!(report.contains("\"role\": \"apply_gui_evidence_required\""));
    assert!(report.contains("apply_or_final_check_blockers_prevent_top_level_gui_code_candidates"));
    assert!(report.contains("gui_related_code_context.json"));
    assert!(report.contains("apply_gui_intent.json"));
    assert!(!report.contains("\"role\": \"scripted_gui\""));
    assert!(!report.contains("\"role\": \"interface_gui\""));
    assert!(!report.contains("buttonType ="));
    assert!(!report.contains("<verified_GFX_button_sprite>"));
    assert!(apply_report.contains("unknown_gui_sprite_ref:GFX_button_123x34"));
