#[test]
fn gui_one_shot_gate_require_playable_blocks_without_runtime_evidence() {
    let fixture = write_gui_one_shot_success_fixture("gui-one-shot-require-playable-blocks");
    let mut args = gui_one_shot_success_args(&fixture);
    args.push("--require-playable".to_string());
    args.push("--require-passed".to_string());

    let err = cmd_gui_one_shot_gate(&args).unwrap_err();
    let report = read_utf8_lossy(&fixture.output).unwrap();
    let delivery = read_utf8_lossy(&fixture.output_dir.join("gui_delivery_report.json")).unwrap();
    let runtime_runbook =
        read_utf8_lossy(&fixture.output_dir.join("gui_runtime_evidence_runbook.json")).unwrap();
    fs::remove_dir_all(&fixture.root).unwrap();

    assert_eq!(err, "gui-one-shot-gate did not pass");
    assert!(report.contains("\"require_playable\": true"));
    assert!(report.contains("\"status\": \"runtime_delivery_not_ready\""));
    assert!(report.contains("\"ok\": false"));
    assert!(report.contains("\"delivery_ready\": false"));
    assert!(report.contains("runtime_delivery_ready_required"));
    assert!(report.contains("\"runtime_evidence_runbook_summary\""));
    assert!(report.contains("\"runtime_command_chain_ready\": true"));
    assert!(delivery.contains("\"require_playable\": true"));
    assert!(delivery.contains("\"delivery_ready\": false"));
    assert!(delivery.contains("runtime_one_shot_required_for_playable_delivery"));
    assert!(runtime_runbook.contains("\"schema\": \"hoi4skill.gui_runtime_evidence_runbook.v1\""));
    assert!(runtime_runbook.contains("\"status\": \"runtime_evidence_required\""));
    assert!(runtime_runbook.contains("\"require_playable\": true"));
    assert!(runtime_runbook.contains("\"runtime_evidence_ready\": false"));
    assert!(runtime_runbook.contains("\"runtime_command_chain_ready\": true"));
    assert!(runtime_runbook.contains("gui-runtime-one-shot-gate"));
    assert!(runtime_runbook.contains("gui-delivery-report"));
    assert!(runtime_runbook
        .contains("Do not claim playable_delivery_ready until gui-runtime-one-shot-gate passes."));
}

