#[test]
fn gui_one_shot_gate_probe_cleanup_restores_existing_and_deletes_probe_files() {
    let fixture = write_gui_one_shot_success_fixture("gui-one-shot-probe-cleanup");
    let existing_interface = fixture
        .target
        .join("interface")
        .join("one_shot_panel_window.gui");
    fs::write(&existing_interface, "preexisting user gui\n").unwrap();
    let mut args = gui_one_shot_success_args(&fixture);
    args.push("--probe-cleanup".to_string());
    args.push("--force".to_string());
    args.push("--require-passed".to_string());

    cmd_gui_one_shot_gate(&args).unwrap();

    let report = read_utf8_lossy(&fixture.output).unwrap();
    let cleanup = read_utf8_lossy(&fixture.output_dir.join("gui_probe_cleanup.json")).unwrap();
    let restored_interface = read_utf8_lossy(&existing_interface).unwrap();
    let scripted_gui = fixture
        .target
        .join("common")
        .join("scripted_guis")
        .join("one_shot_panel_gui.txt");
    let scripted_effect = fixture
        .target
        .join("common")
        .join("scripted_effects")
        .join("one_shot_panel_gui.txt");
    let loc = fixture
        .target
        .join("localisation")
        .join("simp_chinese")
        .join("one_shot_panel_gui_l_simp_chinese.yml");
    let staging = fixture
        .target
        .join(".hoi4skill")
        .join("gui_staging")
        .join("one_shot_panel_gui");

    assert!(report.contains("\"probe_cleanup_summary\""));
    assert!(report.contains("\"status\": \"cleaned\""));
    assert!(report.contains("\"requested\": true"));
    assert!(report.contains("\"blocker_count\": 0"));
    assert!(cleanup.contains("\"schema\": \"hoi4skill.gui_probe_cleanup.v1\""));
    assert!(cleanup.contains("\"ok\": true"));
    assert!(cleanup.contains("\"skipped_count\": 0"));
    assert!(cleanup.contains("interface/one_shot_panel_window.gui"));
    assert!(cleanup.contains("common/scripted_guis/one_shot_panel_gui.txt"));
    assert_eq!(restored_interface, "preexisting user gui\n");
    assert!(!scripted_gui.exists());
    assert!(!scripted_effect.exists());
    assert!(!loc.exists());
    assert!(!staging.exists());
    fs::remove_dir_all(&fixture.root).unwrap();
}

#[test]
fn gui_runtime_evidence_runbook_writes_runtime_command_chain() {
    let root = unique_temp_dir("gui-runtime-evidence-runbook");
    let mod_root = root.join("mod");
    let game_root = root.join("game");
    let workflow_dir = root.join("workflow");
    let output = workflow_dir.join("custom_runbook.json");
    fs::create_dir_all(&mod_root).unwrap();
    fs::create_dir_all(&game_root).unwrap();
    fs::create_dir_all(&workflow_dir).unwrap();
    fs::write(
        workflow_dir.join("gui_runtime_open_plan.json"),
        "{\n  \"schema\": \"hoi4skill.gui_runtime_open_plan.v1\",\n  \"window_name\": \"chen_duxiu_window\",\n  \"country_tag\": \"CHI\",\n  \"open_flag\": \"open_chen_duxiu_window\",\n  \"click_target\": \"chen_duxiu_confirm_button\"\n}\n",
    )
    .unwrap();

    cmd_gui_runtime_evidence_runbook(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--game-root".to_string(),
        game_root.to_string_lossy().to_string(),
        "--workflow-dir".to_string(),
        workflow_dir.to_string_lossy().to_string(),
        "--require-playable".to_string(),
        "--output".to_string(),
        output.to_string_lossy().to_string(),
    ])
    .unwrap();

    let report = read_utf8_lossy(&output).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(report.contains("\"schema\": \"hoi4skill.gui_runtime_evidence_runbook.v1\""));
    assert!(report.contains("\"status\": \"runtime_evidence_required\""));
    assert!(report.contains("\"require_playable\": true"));
    assert!(report.contains("\"runtime_evidence_ready\": false"));
    assert!(report.contains("\"runtime_command_chain_ready\": true"));
    assert!(report.contains("\"runtime_input_blocking_count\": 0"));
    assert!(report.contains("\"window_name\": \"chen_duxiu_window\""));
    assert!(report.contains("\"country_tag\": \"CHI\""));
    assert!(report.contains("\"open_flag\": \"open_chen_duxiu_window\""));
    assert!(report.contains("\"click_target\": \"chen_duxiu_confirm_button\""));
    assert!(report.contains("\"runtime_evidence_manifest\""));
    assert!(report.contains("gui-runtime-smoke-executor"));
    assert!(report.contains("gui-runtime-evidence-collect"));
    assert!(report.contains("gui-runtime-evidence-manifest"));
    assert!(report.contains("gui-runtime-one-shot-gate"));
    assert!(report.contains("gui-delivery-report"));
    assert!(report.contains("gui_runtime_evidence_manifest.json"));
    assert!(report.contains("This runbook is an execution plan; it is not runtime evidence."));
}

