#[test]
fn gui_one_shot_gate_blocks_style_template_package_parent_mismatch_before_write() {
    let root = unique_temp_dir("gui-one-shot-style-package-parent-mismatch");
    let target = root.join("target_mod");
    let style_a = root.join("style_a");
    let style_b = root.join("style_b");
    let game_root = root.join("game_root");
    let package_dir = root.join("style_package");
    let package_report = root.join("style_package_report.json");
    let output_dir = root.join("workflow");
    let output = root.join("one_shot.json");
    write_gui_intent_test_style_mod(&style_a);
    write_gui_intent_test_style_mod(&style_b);
    fs::create_dir_all(&target).unwrap();
    fs::create_dir_all(&game_root).unwrap();

    cmd_gui_style_template(&[
        "--parent-mod".to_string(),
        style_a.to_string_lossy().to_string(),
        "--output-dir".to_string(),
        package_dir.to_string_lossy().to_string(),
        "--output".to_string(),
        package_report.to_string_lossy().to_string(),
    ])
    .unwrap();

    let err = cmd_gui_one_shot_gate(&[
        "--mod-root".to_string(),
        target.to_string_lossy().to_string(),
        "--style-mod".to_string(),
        style_b.to_string_lossy().to_string(),
        "--style-template-package".to_string(),
        package_dir
            .join("gui_style_template_package.json")
            .to_string_lossy()
            .to_string(),
        "--game-root".to_string(),
        game_root.to_string_lossy().to_string(),
        "--text".to_string(),
        "工业统计界面：刷新工业数据".to_string(),
        "--output-dir".to_string(),
        output_dir.to_string_lossy().to_string(),
        "--require-generated".to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        output.to_string_lossy().to_string(),
    ])
    .unwrap_err();

    let report = read_utf8_lossy(&output).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert_eq!(err, "gui-one-shot-gate did not pass");
    assert!(report.contains("\"status\": \"workflow_command_failed\""));
    assert!(report.contains("\"ok\": false"));
    assert!(report.contains("style-template-package parent_mods do not match"));
    assert!(report.contains("\"parent_style_source_audit\""));
    assert!(report.contains("\"status\": \"parent_style_source_not_ready\""));
    assert!(report.contains("parent_style_source_missing"));
    assert!(report.contains("\"one_shot_delivery_decision\""));
    assert!(report.contains("\"status\": \"delivery_not_ready\""));
    assert!(report.contains("four_inputs_not_ready"));
    assert!(!target.join("interface").exists());
}

