#[test]
fn gui_one_shot_delivery_decision_ignores_nested_false_positive_bools() {
    let decision = gui_one_shot_delivery_decision_json(
        "{\"ready\": true}",
        "{\"ready\": true}",
        "{\"generated_manifest_ready\": false, \"nested\": {\"generated_manifest_ready\": true}}",
        "{\"generated_trace_ready\": false, \"nested\": {\"generated_trace_ready\": true}}",
        "{\"code_artifacts_ready\": false, \"nested\": {\"code_artifacts_ready\": true}}",
        "{\"generated_mount_ready\": false, \"nested\": {\"generated_mount_ready\": true}}",
        "{\"ready\": false, \"nested\": {\"ready\": true}}",
        false,
        false,
        true,
        false,
        true,
    );

    assert!(decision.contains("\"ready\": false"));
    assert!(decision.contains("\"status\": \"delivery_not_ready\""));
    assert!(decision.contains("\"manifest_ready\": false"));
    assert!(decision.contains("\"static_trace_ready\": false"));
    assert!(decision.contains("\"code_bundle_ready\": false"));
    assert!(decision.contains("\"runtime_mount_ready\": false"));
    assert!(decision.contains("\"unknown_symbol_safety_ready\": false"));
    assert!(decision.contains("generated_file_manifest_not_ready"));
    assert!(decision.contains("runtime_mount_entry_not_ready"));
}

#[test]
