    assert!(report.contains("\"related_code_context_query_count\": 0"));
    assert!(report.contains("\"repair_context_ready\": true"));
    assert!(report.contains("\"repair_needed\": false"));
    assert!(report.contains("\"repair_item_count\": 0"));
    assert!(report.contains("\"gui_output_audit_ready\": true"));
    assert!(report.contains("\"gui_output_audit_ok_from_apply_report\": true"));
    assert!(report.contains("\"text_alignment_ready\": true"));
    assert!(report.contains("\"text_alignment_report_available\": true"));
    assert!(report.contains("\"text_alignment_missing_count\": 0"));
    assert!(report.contains(&json_str(&final_text_alignment.display().to_string())));
    assert!(report.contains("\"strict_code_index_ready\": true"));
    assert!(report.contains("\"strict_validation_report_available\": true"));
    assert!(report.contains(&json_str(&final_strict_validation.display().to_string())));
    assert!(report.contains("\"runtime_open_plan_ready\": true"));
    assert!(report.contains("\"runtime_mount_index_ready\": true"));
    assert!(report.contains("\"runtime_open_trigger_ready\": true"));
    assert!(report.contains("\"runtime_contract_ready\": true"));
    assert!(report.contains("\"runtime_evidence_ready\": false"));
    assert!(report.contains("\"runtime_contract_forbids_playable_claim\": true"));
    assert!(report.contains("\"require_playable\": false"));
    assert!(report.contains("\"playable_ready\": false"));
    assert!(report.contains("\"playability_gate_report_available\": false"));
    assert!(report.contains("\"runtime_manifest_report_available\": false"));
    assert!(report.contains(&json_str(&runtime_open_plan.display().to_string())));
    assert!(report.contains(&json_str(&runtime_contract.display().to_string())));
    assert!(report.contains("\"script_file_ready\": true"));
    assert!(report.contains("\"completion_percent\": 100"));

    let playable_output = root.join("audit_require_playable_missing.json");
