    cmd_gui_objective_audit(&[
        "--workflow-dir".to_string(),
        workflow_dir.to_string_lossy().to_string(),
        "--require-generated".to_string(),
        "--require-playable".to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        playable_output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let playable_report = read_utf8_lossy(&playable_output).unwrap();
    assert!(playable_report.contains("\"require_playable\": true"));
    assert!(playable_report.contains("\"playable_ready\": true"));
    assert!(playable_report.contains("\"playability_gate_ready\": true"));
    assert!(playable_report.contains("\"runtime_manifest_ready\": true"));
    assert!(playable_report.contains("\"machine_runtime_evidence_ready\": true"));
    assert!(playable_report.contains("\"playable_evidence\""));
    assert!(playable_report.contains("\"completion_percent\": 100"));
