#[test]
fn gui_runtime_pixel_probe_blocks_blank_region_and_accepts_visible_pixels() {
    let root = unique_temp_dir("gui-runtime-pixel-probe");
    let mod_root = root.join("mod");
    let layout_probe = root.join("gui_runtime_layout_probe.json");
    let screenshot = root.join("gui.png");
    let blocked_output = root.join("blocked_pixel_probe.json");
    let passed_output = root.join("passed_pixel_probe.json");
    fs::create_dir_all(&mod_root).unwrap();
    fs::write(
        &layout_probe,
        "{\n  \"schema\": \"hoi4skill.gui_runtime_layout_probe.v1\",\n  \"layout_probe_ready\": true,\n  \"click_targets\": [\n    {\"name\": \"refresh_button\", \"x\": 2, \"y\": 2, \"width\": 4, \"height\": 4, \"click_x\": 4, \"click_y\": 4}\n  ]\n}\n",
    )
    .unwrap();
    let blank = vec![0u8; 10 * 10 * 4];
    write_test_png_rgba(&screenshot, 10, 10, &blank);

    let err = cmd_gui_runtime_pixel_probe(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--screenshot".to_string(),
        screenshot.to_string_lossy().to_string(),
        "--layout-probe".to_string(),
        layout_probe.to_string_lossy().to_string(),
        "--target-widget".to_string(),
        "refresh_button".to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        blocked_output.to_string_lossy().to_string(),
    ])
    .unwrap_err();
    let blocked = read_utf8_lossy(&blocked_output).unwrap();
    assert_eq!(err, "gui-runtime-pixel-probe did not pass");
    assert!(blocked.contains("\"schema\": \"hoi4skill.gui_runtime_pixel_probe.v1\""));
    assert!(blocked.contains("\"pixel_probe_ready\": false"));
    assert!(blocked.contains("pixel_target_color_range_low:refresh_button"));

    let mut visible = vec![0u8; 10 * 10 * 4];
    for y in 2..6 {
        for x in 2..6 {
            let idx = ((y * 10 + x) * 4) as usize;
            visible[idx] = if (x + y) % 2 == 0 { 220 } else { 20 };
            visible[idx + 1] = 80;
            visible[idx + 2] = 30;
            visible[idx + 3] = 255;
        }
    }
    write_test_png_rgba(&screenshot, 10, 10, &visible);
    cmd_gui_runtime_pixel_probe(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--screenshot".to_string(),
        screenshot.to_string_lossy().to_string(),
        "--layout-probe".to_string(),
        layout_probe.to_string_lossy().to_string(),
        "--target-widget".to_string(),
        "refresh_button".to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        passed_output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let passed = read_utf8_lossy(&passed_output).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(passed.contains("\"status\": \"pixel_probe_ready\""));
    assert!(passed.contains("\"pixel_probe_ready\": true"));
    assert!(passed.contains("\"target_widget\": \"refresh_button\""));
    assert!(passed.contains("\"within_screenshot\": true"));
}

#[test]
fn gui_runtime_state_probe_requires_machine_state_delta() {
    let root = unique_temp_dir("gui-runtime-state-probe");
    let mod_root = root.join("mod");
    let before_log = root.join("before.log");
    let after_log = root.join("after.log");
    let before_screenshot = root.join("before.png");
    let after_screenshot = root.join("after.png");
    let blocked_output = root.join("blocked_state_probe.json");
    let passed_output = root.join("passed_state_probe.json");
    fs::create_dir_all(&mod_root).unwrap();
    fs::write(&before_log, "opened test_gui_window\n").unwrap();
    fs::write(&after_log, "opened test_gui_window\n").unwrap();
    let mut before_pixels = vec![0u8; 8 * 8 * 4];
    let mut after_pixels = vec![0u8; 8 * 8 * 4];
    for idx in (0..before_pixels.len()).step_by(4) {
        before_pixels[idx] = 80;
        before_pixels[idx + 1] = 80;
        before_pixels[idx + 2] = 80;
        before_pixels[idx + 3] = 255;
        after_pixels[idx] = 40;
        after_pixels[idx + 1] = 180;
        after_pixels[idx + 2] = 220;
        after_pixels[idx + 3] = 255;
    }
    write_test_png_rgba(&before_screenshot, 8, 8, &before_pixels);
    write_test_png_rgba(&after_screenshot, 8, 8, &before_pixels);

    let err = cmd_gui_runtime_state_probe(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--target-widget".to_string(),
        "refresh_button".to_string(),
        "--before-log".to_string(),
        before_log.to_string_lossy().to_string(),
        "--after-log".to_string(),
        after_log.to_string_lossy().to_string(),
        "--before-screenshot".to_string(),
        before_screenshot.to_string_lossy().to_string(),
        "--after-screenshot".to_string(),
        after_screenshot.to_string_lossy().to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        blocked_output.to_string_lossy().to_string(),
    ])
    .unwrap_err();
    let blocked = read_utf8_lossy(&blocked_output).unwrap();
    assert_eq!(err, "gui-runtime-state-probe did not pass");
    assert!(blocked.contains("\"schema\": \"hoi4skill.gui_runtime_state_probe.v1\""));
    assert!(blocked.contains("\"state_probe_ready\": false"));
    assert!(blocked.contains("\"screenshot_pair_ready\": true"));
    assert!(blocked.contains("\"screenshot_changed\": false"));
    assert!(blocked.contains("post_click_state_change_not_observed"));

    fs::write(
        &after_log,
        "opened test_gui_window\nrefresh_button changed_state_token\n",
    )
    .unwrap();
    write_test_png_rgba(&after_screenshot, 8, 8, &after_pixels);
    cmd_gui_runtime_state_probe(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--target-widget".to_string(),
        "refresh_button".to_string(),
        "--before-log".to_string(),
        before_log.to_string_lossy().to_string(),
        "--after-log".to_string(),
        after_log.to_string_lossy().to_string(),
        "--before-screenshot".to_string(),
        before_screenshot.to_string_lossy().to_string(),
        "--after-screenshot".to_string(),
        after_screenshot.to_string_lossy().to_string(),
        "--expect-log-token".to_string(),
        "changed_state_token".to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        passed_output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let passed = read_utf8_lossy(&passed_output).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(passed.contains("\"status\": \"state_probe_ready\""));
    assert!(passed.contains("\"state_probe_ready\": true"));
    assert!(passed.contains("\"log_changed\": true"));
    assert!(passed.contains("\"screenshot_pair_ready\": true"));
    assert!(passed.contains("\"screenshot_changed\": true"));
    assert!(passed.contains("\"expected_token_hits\": [\"changed_state_token\"]"));
    assert!(passed.contains("\"machine_change_observed\": true"));
}

