#[test]
fn gui_runtime_launch_plan_requires_exe_descriptor_and_code_gate() {
    let root = unique_temp_dir("gui-runtime-launch-plan");
    let mod_root = root.join("mod");
    let game_root = root.join("game");
    let apply_report = root.join("applied_gui_intent.json");
    let blocked_output = root.join("blocked_launch_plan.json");
    let passed_output = root.join("passed_launch_plan.json");
    fs::create_dir_all(&mod_root).unwrap();
    fs::create_dir_all(&game_root).unwrap();
    fs::write(
        &apply_report,
        "{\n  \"schema\": \"hoi4skill.apply_gui_intent.v1\",\n  \"ok\": true,\n  \"final_check_ok\": true,\n  \"strict_validation_ok\": true,\n  \"window_name\": \"test_gui_window\"\n}\n",
    )
    .unwrap();

    let err = cmd_gui_runtime_launch_plan(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--game-root".to_string(),
        game_root.to_string_lossy().to_string(),
        "--apply-report".to_string(),
        apply_report.to_string_lossy().to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        blocked_output.to_string_lossy().to_string(),
    ])
    .unwrap_err();
    let blocked = read_utf8_lossy(&blocked_output).unwrap();
    assert_eq!(err, "gui-runtime-launch-plan did not pass");
    assert!(blocked.contains("\"schema\": \"hoi4skill.gui_runtime_launch_plan.v1\""));
    assert!(blocked.contains("\"status\": \"needs_hoi4_exe\""));
    assert!(blocked.contains("\"launch_plan_ready\": false"));

    fs::write(game_root.join("hoi4.exe"), "fake exe").unwrap();
    fs::write(mod_root.join("descriptor.mod"), "name=\"Test Mod\"\n").unwrap();
    cmd_gui_runtime_launch_plan(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--game-root".to_string(),
        game_root.to_string_lossy().to_string(),
        "--apply-report".to_string(),
        apply_report.to_string_lossy().to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        passed_output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let passed = read_utf8_lossy(&passed_output).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(passed.contains("\"status\": \"ready_to_launch\""));
    assert!(passed.contains("\"launch_plan_ready\": true"));
    assert!(passed.contains("\"descriptor_exists\": true"));
    assert!(passed.contains("\"window_name\": \"test_gui_window\""));
    assert!(passed.contains("gui-game-smoke-report"));
}

#[test]
fn gui_runtime_open_plan_requires_concrete_country_window_trigger_and_token() {
    let root = unique_temp_dir("gui-runtime-open-plan");
    let mod_root = root.join("mod");
    let apply_report = root.join("applied_gui_intent.json");
    let launch_plan = root.join("gui_runtime_launch_plan.json");
    let blocked_output = root.join("blocked_open_plan.json");
    let passed_output = root.join("passed_open_plan.json");
    fs::create_dir_all(mod_root.join("interface")).unwrap();
    fs::write(
        mod_root.join("interface").join("test_gui.gui"),
        "guiTypes = {\n containerWindowType = { name = \"test_gui_window\" position = { x = 0 y = 0 } size = { width = 420 height = 300 } }\n}\n",
    )
    .unwrap();
    fs::write(
        &apply_report,
        "{\n  \"schema\": \"hoi4skill.apply_gui_intent.v1\",\n  \"ok\": true,\n  \"final_check_ok\": true,\n  \"strict_validation_ok\": true,\n  \"window_name\": \"test_gui_window\",\n  \"changed_files\": [\"interface/test_gui.gui\"]\n}\n",
    )
    .unwrap();
    fs::write(
        &launch_plan,
        "{\n  \"schema\": \"hoi4skill.gui_runtime_launch_plan.v1\",\n  \"launch_plan_ready\": true,\n  \"window_name\": \"test_gui_window\"\n}\n",
    )
    .unwrap();

    let err = cmd_gui_runtime_open_plan(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--apply-report".to_string(),
        apply_report.to_string_lossy().to_string(),
        "--runtime-launch-plan".to_string(),
        launch_plan.to_string_lossy().to_string(),
        "--require-country".to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        blocked_output.to_string_lossy().to_string(),
    ])
    .unwrap_err();
    let blocked = read_utf8_lossy(&blocked_output).unwrap();
    assert_eq!(err, "gui-runtime-open-plan did not pass");
    assert!(blocked.contains("\"schema\": \"hoi4skill.gui_runtime_open_plan.v1\""));
    assert!(blocked.contains("\"status\": \"blocked_until_country_context\""));
    assert!(blocked.contains("missing_or_unsafe_country_tag"));
    assert!(blocked.contains("missing_runtime_open_trigger"));
    assert!(blocked.contains("\"runtime_candidate_count\": 0"));
    assert!(blocked.contains("\"candidate_selection_allowed\": false"));
    assert!(blocked.contains("\"runtime_repair_actions\":"));
    assert!(blocked.contains("Ask the user which indexed country tag/save context should be used."));
    assert!(blocked.contains("Ask how the GUI opens in game"));
    assert!(blocked.contains("\"recommended_runtime_code\":"));
    assert!(blocked.contains("--country-tag <TAG>"));
    assert!(blocked.contains("--open-flag <open_flag_or_state_token>"));
    assert!(blocked.contains("Candidate only, do not write without user approval"));

    cmd_gui_runtime_open_plan(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--apply-report".to_string(),
        apply_report.to_string_lossy().to_string(),
        "--runtime-launch-plan".to_string(),
        launch_plan.to_string_lossy().to_string(),
        "--country-tag".to_string(),
        "CHI".to_string(),
        "--open-flag".to_string(),
        "test_gui_opened".to_string(),
        "--expect-log-token".to_string(),
        "test_gui_window".to_string(),
        "--require-country".to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        passed_output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let passed = read_utf8_lossy(&passed_output).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(passed.contains("\"status\": \"open_plan_ready\""));
    assert!(passed.contains("\"open_plan_ready\": true"));
    assert!(passed.contains("\"country_tag\": \"CHI\""));
    assert!(passed.contains("\"window_name\": \"test_gui_window\""));
    assert!(passed.contains("\"open_flag\": \"test_gui_opened\""));
    assert!(
        passed.contains("\"expected_runtime_tokens\": [\"test_gui_window\", \"test_gui_opened\"]")
    );
}

#[test]
fn gui_runtime_open_plan_strict_code_index_blocks_unindexed_runtime_path() {
    let root = unique_temp_dir("gui-runtime-open-plan-strict-index");
    let mod_root = root.join("mod");
    let game_root = root.join("game");
    let apply_report = root.join("applied_gui_intent.json");
    let launch_plan = root.join("gui_runtime_launch_plan.json");
    let blocked_output = root.join("blocked_strict_open_plan.json");
    let passed_output = root.join("passed_strict_open_plan.json");
    fs::create_dir_all(mod_root.join("common").join("country_tags")).unwrap();
    fs::create_dir_all(mod_root.join("common").join("scripted_effects")).unwrap();
    fs::create_dir_all(mod_root.join("interface")).unwrap();
    fs::create_dir_all(&game_root).unwrap();
    fs::write(mod_root.join("descriptor.mod"), "name=\"Test GUI Mod\"\n").unwrap();
    fs::write(
        mod_root
            .join("common")
            .join("country_tags")
            .join("tags.txt"),
        "CHI = \"countries/CHI.txt\"\n",
    )
    .unwrap();
    fs::write(
        mod_root
            .join("common")
            .join("scripted_effects")
            .join("gui_effects.txt"),
        "open_test_gui_effect = {\n\tset_country_flag = test_gui_opened\n}\n",
    )
    .unwrap();
    fs::write(
        mod_root.join("interface").join("test_gui.gui"),
        "guiTypes = {\n\tcontainerWindowType = {\n\t\tname = \"test_gui_window\"\n\t\tbuttonType = {\n\t\t\tname = \"open_test_button\"\n\t\t\tposition = { x = 10 y = 10 }\n\t\t\tsize = { width = 120 height = 24 }\n\t\t}\n\t}\n}\n",
    )
    .unwrap();
    fs::write(
        &apply_report,
        "{\n  \"schema\": \"hoi4skill.apply_gui_intent.v1\",\n  \"ok\": true,\n  \"final_check_ok\": true,\n  \"strict_validation_ok\": true,\n  \"window_name\": \"test_gui_window\",\n  \"changed_files\": [\"interface/test_gui.gui\"]\n}\n",
    )
    .unwrap();
    fs::write(
        &launch_plan,
        "{\n  \"schema\": \"hoi4skill.gui_runtime_launch_plan.v1\",\n  \"launch_plan_ready\": true,\n  \"window_name\": \"test_gui_window\"\n}\n",
    )
    .unwrap();

    let err = cmd_gui_runtime_open_plan(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--game-root".to_string(),
        game_root.to_string_lossy().to_string(),
        "--apply-report".to_string(),
        apply_report.to_string_lossy().to_string(),
        "--runtime-launch-plan".to_string(),
        launch_plan.to_string_lossy().to_string(),
        "--country-tag".to_string(),
        "CHX".to_string(),
        "--open-effect".to_string(),
        "missing_gui_effect".to_string(),
        "--click-target".to_string(),
        "missing_button".to_string(),
        "--expect-log-token".to_string(),
        "test_gui_window".to_string(),
        "--require-country".to_string(),
        "--strict-code-index".to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        blocked_output.to_string_lossy().to_string(),
    ])
    .unwrap_err();
    let blocked = read_utf8_lossy(&blocked_output).unwrap();
    assert_eq!(err, "gui-runtime-open-plan did not pass");
    assert!(blocked.contains("\"strict_code_index\": true"));
    assert!(blocked.contains("\"status\": \"blocked_until_strict_code_index\""));
    assert!(blocked.contains("unindexed_runtime_country_tag:CHX"));
    assert!(blocked.contains("unindexed_runtime_open_effect:missing_gui_effect"));
    assert!(blocked.contains("unindexed_runtime_click_target_widget:missing_button"));
    assert!(blocked.contains("\"candidate_country_tags\": [\"CHI\"]"));
    assert!(blocked.contains("open_test_button @ interface/test_gui.gui"));
    assert!(blocked.contains("\"runtime_candidate_count\":"));
    assert!(blocked.contains("\"candidate_selection_allowed\": true"));
    assert!(blocked.contains("\"runtime_repair_actions\":"));
    assert!(blocked.contains("Choose --country-tag CHI from indexed candidates"));
    assert!(blocked.contains("Choose --click-target open_test_button from indexed candidates"));
    assert!(blocked.contains("\"recommended_runtime_code\":"));
    assert!(blocked.contains("--country-tag CHI"));
    assert!(blocked.contains("--click-target open_test_button"));
    assert!(!blocked.contains("--country-tag CHX"));
    assert!(!blocked.contains("--click-target missing_button"));

    cmd_gui_runtime_open_plan(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--game-root".to_string(),
        game_root.to_string_lossy().to_string(),
        "--apply-report".to_string(),
        apply_report.to_string_lossy().to_string(),
        "--runtime-launch-plan".to_string(),
        launch_plan.to_string_lossy().to_string(),
        "--country-tag".to_string(),
        "CHI".to_string(),
        "--open-effect".to_string(),
        "open_test_gui_effect".to_string(),
        "--click-target".to_string(),
        "open_test_button".to_string(),
        "--expect-log-token".to_string(),
        "test_gui_window".to_string(),
        "--require-country".to_string(),
        "--strict-code-index".to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        passed_output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let passed = read_utf8_lossy(&passed_output).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(passed.contains("\"status\": \"open_plan_ready\""));
    assert!(passed.contains("\"strict_code_index_ready\": true"));
    assert!(passed.contains("indexed_country_tag:CHI"));
    assert!(passed.contains("indexed_scripted_effect:open_test_gui_effect"));
    assert!(passed.contains("indexed_gui_widget:open_test_button:interface/test_gui.gui"));
}

