#[test]
fn gui_runtime_runner_dry_run_requires_launch_plan_readiness() {
    let root = unique_temp_dir("gui-runtime-runner");
    let mod_root = root.join("mod");
    let game_root = root.join("game");
    let apply_report = root.join("applied_gui_intent.json");
    let blocked_output = root.join("blocked_runner.json");
    let passed_output = root.join("passed_runner.json");
    fs::create_dir_all(&mod_root).unwrap();
    fs::create_dir_all(&game_root).unwrap();
    fs::write(
        &apply_report,
        "{\n  \"schema\": \"hoi4skill.apply_gui_intent.v1\",\n  \"ok\": true,\n  \"final_check_ok\": true,\n  \"strict_validation_ok\": true,\n  \"window_name\": \"test_gui_window\"\n}\n",
    )
    .unwrap();

    let err = cmd_gui_runtime_runner(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--game-root".to_string(),
        game_root.to_string_lossy().to_string(),
        "--apply-report".to_string(),
        apply_report.to_string_lossy().to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        blocked_output.to_string_lossy().to_string(),
    ])
    .unwrap_err();
    let blocked = read_utf8_lossy(&blocked_output).unwrap();
    assert_eq!(err, "gui-runtime-runner did not pass");
    assert!(blocked.contains("\"schema\": \"hoi4skill.gui_runtime_runner.v1\""));
    assert!(blocked.contains("\"status\": \"blocked_until_launch_plan_ready\""));
    assert!(blocked.contains("\"runner_ready\": false"));

    fs::write(game_root.join("hoi4.exe"), "fake exe").unwrap();
    fs::write(mod_root.join("descriptor.mod"), "name=\"Test Mod\"\n").unwrap();
    cmd_gui_runtime_runner(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--game-root".to_string(),
        game_root.to_string_lossy().to_string(),
        "--apply-report".to_string(),
        apply_report.to_string_lossy().to_string(),
        "--screenshot-output".to_string(),
        root.join("gui.png").to_string_lossy().to_string(),
        "--arg".to_string(),
        "-debug_smooth".to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        passed_output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let passed = read_utf8_lossy(&passed_output).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(passed.contains("\"status\": \"ready_dry_run\""));
    assert!(passed.contains("\"runner_ready\": true"));
    assert!(passed.contains("\"executed\": false"));
    assert!(passed.contains("\"baseline_status\": \"not_copied_dry_run\""));
    assert!(passed.contains("test_gui_window"));
    assert!(passed.contains("-debug_smooth"));
    assert!(passed.contains("gui-game-smoke-report"));
}

