#[test]
fn gui_runtime_one_shot_gate_blocks_without_runtime_reports() {
    let root = unique_temp_dir("gui-runtime-one-shot-blocked");
    let mod_root = root.join("mod");
    let output_dir = root.join("runtime");
    let workflow_dir = root.join("workflow");
    let output = output_dir.join("gui_runtime_one_shot_gate.json");
    fs::create_dir_all(&mod_root).unwrap();
    fs::create_dir_all(&workflow_dir).unwrap();
    fs::write(
        workflow_dir.join("gui_request_workflow.json"),
        "{\n  \"schema\": \"hoi4skill.gui_request_workflow.v1\",\n  \"status\": \"applied\",\n  \"ok\": true\n}\n",
    )
    .unwrap();
    fs::write(
        workflow_dir.join("gui_ai_context_contract.json"),
        "{\n  \"schema\": \"hoi4skill.gui_ai_context_contract.v1\",\n  \"status\": \"final_gui_written_after_checks\",\n  \"ok\": true,\n  \"final_clausewitz_write_allowed\": true,\n  \"allowed_edit_surface\": [\"gui_intent.md fields only\"]\n}\n",
    )
    .unwrap();
    fs::write(
        workflow_dir.join("gui_related_code_context.json"),
        "{\n  \"schema\": \"hoi4skill.gui_related_code_context.v1\",\n  \"status\": \"no_blocking_related_code_queries\",\n  \"query_count\": 0\n}\n",
    )
    .unwrap();

    let err = cmd_gui_runtime_one_shot_gate(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--output-dir".to_string(),
        output_dir.to_string_lossy().to_string(),
        "--workflow-dir".to_string(),
        workflow_dir.to_string_lossy().to_string(),
        "--require-playable".to_string(),
        "--require-passed".to_string(),
    ])
    .unwrap_err();

    let report = read_utf8_lossy(&output).unwrap();
    let repair_context =
        read_utf8_lossy(&workflow_dir.join("gui_runtime_repair_context.json")).unwrap();
    let repair_markdown =
        read_utf8_lossy(&workflow_dir.join("gui_runtime_repair_context.md")).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert_eq!(err, "gui-runtime-one-shot-gate did not pass");
    assert!(report.contains("\"schema\": \"hoi4skill.gui_runtime_one_shot_gate.v1\""));
    assert!(report.contains("\"status\": \"missing_runtime_evidence_contract\""));
    assert!(report.contains("\"ok\": false"));
    assert!(report.contains("\"require_playable\": true"));
    assert!(report.contains("\"runtime_evidence_ready\": false"));
    assert!(report.contains("\"playable_ready\": false"));
    assert!(report.contains("\"repair_context_ready\": true"));
    assert!(report.contains("\"repair_needed\": true"));
    assert!(report.contains("\"repair_status\": \"repair_context_ready\""));
    assert!(report.contains("gui_runtime_repair_context.json"));
    assert!(report.contains("gui_runtime_repair_context.md"));
    assert!(report.contains("\"final_runtime_acceptance\""));
    assert!(report.contains("\"acceptable\": false"));
    assert!(report.contains("\"runtime_evidence_summary\""));
    assert!(report.contains("\"missing_evidence\""));
    assert!(report.contains("gui_runtime_evidence_contract.json"));
    assert!(report.contains("gui_playability_gate.json"));
    assert!(report.contains("\"anti_hallucination_boundary\""));
    assert!(report.contains("\"must_not_claim_playable_without_runtime_evidence\": true"));
    assert!(report.contains("runtime_evidence_not_ready"));
    assert!(report.contains("playable_ready_required"));
    assert!(repair_context.contains("\"schema\": \"hoi4skill.gui_repair_loop.v1\""));
    assert!(repair_context.contains("\"repair_context_ready\": true"));
    assert!(repair_context.contains("\"repair_needed\": true"));
    assert!(repair_context.contains("\"source\": \"runtime_one_shot_gate\""));
    assert!(repair_context.contains("\"category\": \"runtime_check_failed\""));
    assert!(repair_context.contains("runtime_evidence_ready=false"));
    assert!(repair_context.contains("playable_ready=false"));
    assert!(repair_context.contains("\"final_clausewitz_write_allowed\": false"));
    assert!(repair_markdown.contains("AI output forbidden"));
}

