#[test]
fn gui_delivery_report_accepts_code_ready_but_blocks_playable_claim() {
    let root = unique_temp_dir("gui-delivery-code-ready");
    let workflow_dir = root.join("workflow");
    let runtime_dir = root.join("runtime");
    let output = workflow_dir.join("gui_delivery_report.json");
    let markdown = workflow_dir.join("gui_delivery_report.md");
    fs::create_dir_all(&workflow_dir).unwrap();
    fs::create_dir_all(&runtime_dir).unwrap();
    fs::write(
        workflow_dir.join("gui_one_shot_gate.json"),
        "{\n  \"schema\": \"hoi4skill.gui_one_shot_gate.v1\",\n  \"status\": \"generated_ready\",\n  \"ok\": true,\n  \"generated_ready\": true,\n  \"safe_blocked\": false,\n  \"repair_context_ready\": true,\n  \"repair_needed\": false\n}\n",
    )
    .unwrap();
    fs::write(
        workflow_dir.join("gui_repair_context.json"),
        "{\n  \"schema\": \"hoi4skill.gui_repair_loop.v1\",\n  \"repair_context_ready\": true,\n  \"repair_needed\": false,\n  \"final_clausewitz_write_allowed\": false\n}\n",
    )
    .unwrap();
    write_gui_delivery_ready_goal_gate(&workflow_dir);
    fs::write(
        runtime_dir.join("gui_runtime_one_shot_gate.json"),
        "{\n  \"schema\": \"hoi4skill.gui_runtime_one_shot_gate.v1\",\n  \"status\": \"missing_runtime_evidence_contract\",\n  \"ok\": false,\n  \"runtime_evidence_ready\": false,\n  \"playable_ready\": false,\n  \"repair_context_ready\": true,\n  \"repair_needed\": true\n}\n",
    )
    .unwrap();
    fs::write(
        workflow_dir.join("gui_runtime_repair_context.json"),
        "{\n  \"schema\": \"hoi4skill.gui_repair_loop.v1\",\n  \"repair_context_ready\": true,\n  \"repair_needed\": true,\n  \"final_clausewitz_write_allowed\": false\n}\n",
    )
    .unwrap();

    cmd_gui_delivery_report(&[
        "--workflow-dir".to_string(),
        workflow_dir.to_string_lossy().to_string(),
        "--runtime-dir".to_string(),
        runtime_dir.to_string_lossy().to_string(),
        "--output".to_string(),
        output.to_string_lossy().to_string(),
        "--require-passed".to_string(),
    ])
    .unwrap();

    let report = read_utf8_lossy(&output).unwrap();
    let md = read_utf8_lossy(&markdown).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(report.contains("\"schema\": \"hoi4skill.gui_delivery_report.v1\""));
    assert!(report.contains("\"status\": \"code_delivery_ready\""));
    assert!(report.contains("\"delivery_ready\": true"));
    assert!(report.contains("\"code_delivery_ready\": true"));
    assert!(report.contains("\"goal_gate_schema_ok\": true"));
    assert!(report.contains("\"static_hard_gates_ready\": true"));
    assert!(report.contains("\"style_reuse_ready\": true"));
    assert!(report.contains("\"resource_resolution_ready\": true"));
    assert!(report.contains("\"text_alignment_ready\": true"));
    assert!(report.contains("\"strict_code_index_ready\": true"));
    assert!(report.contains("\"playable_delivery_ready\": false"));
    assert!(report.contains("\"must_not_claim_playable\": true"));
    assert!(report.contains("\"runtime_repair_needed\": true"));
    assert!(report.contains("\"blockers\": []"));
    assert!(report.contains("GUI code is generated and static gates passed"));
    assert!(md.contains("code_delivery_ready: `true`"));
    assert!(md.contains("static_hard_gates_ready: `true`"));
    assert!(md.contains("playable_delivery_ready: `false`"));
}

