#[test]
fn gui_game_smoke_report_requires_runtime_evidence_and_feeds_playability_gate() {
    let root = unique_temp_dir("gui-game-smoke-report");
    let mod_root = root.join("mod");
    let apply_report = root.join("applied_gui_intent.json");
    let error_report = root.join("gui_error_regression.json");
    let visual_report = root.join("gui_visual_smoke.json");
    let launch_plan = root.join("gui_runtime_launch_plan.json");
    let screenshot = root.join("gui.png");
    let game_smoke = root.join("gui_game_smoke.json");
    let blocked_game_smoke = root.join("blocked_gui_game_smoke.json");
    let weak_game_smoke = root.join("weak_game_smoke.json");
    let gate_output = root.join("gui_playability_gate.json");
    fs::create_dir_all(&mod_root).unwrap();
    fs::write(
        &apply_report,
        "{\n  \"schema\": \"hoi4skill.apply_gui_intent.v1\",\n  \"ok\": true,\n  \"final_check_ok\": true,\n  \"strict_validation_ok\": true\n}\n",
    )
    .unwrap();
    fs::write(&error_report, "{\n  \"ok\": true\n}\n").unwrap();
    fs::write(&visual_report, "{\n  \"visual_passed\": true\n}\n").unwrap();
    fs::write(
        &launch_plan,
        "{\n  \"schema\": \"hoi4skill.gui_runtime_launch_plan.v1\",\n  \"launch_plan_ready\": true\n}\n",
    )
    .unwrap();
    fs::write(&screenshot, "fake screenshot").unwrap();
    fs::write(&weak_game_smoke, "{\n  \"ok\": true\n}\n").unwrap();

    let err = cmd_gui_playability_gate(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--apply-report".to_string(),
        apply_report.to_string_lossy().to_string(),
        "--gui-error-regression".to_string(),
        error_report.to_string_lossy().to_string(),
        "--gui-visual-smoke".to_string(),
        visual_report.to_string_lossy().to_string(),
        "--game-smoke".to_string(),
        weak_game_smoke.to_string_lossy().to_string(),
        "--require-game-smoke".to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        gate_output.to_string_lossy().to_string(),
    ])
    .unwrap_err();
    assert_eq!(err, "gui-playability-gate did not pass");

    let err = cmd_gui_game_smoke_report(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--apply-report".to_string(),
        apply_report.to_string_lossy().to_string(),
        "--gui-error-regression".to_string(),
        error_report.to_string_lossy().to_string(),
        "--gui-visual-smoke".to_string(),
        visual_report.to_string_lossy().to_string(),
        "--game-launched".to_string(),
        "--mod-enabled".to_string(),
        "--window-opened".to_string(),
        "--screenshot".to_string(),
        screenshot.to_string_lossy().to_string(),
        "--text-fit-ok".to_string(),
        "--click-evidence".to_string(),
        "button clicked in game".to_string(),
        "--require-launch-plan".to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        blocked_game_smoke.to_string_lossy().to_string(),
    ])
    .unwrap_err();
    let blocked = read_utf8_lossy(&blocked_game_smoke).unwrap();
    assert_eq!(err, "gui-game-smoke-report did not pass");
    assert!(blocked.contains("\"launch_plan_passed\": false"));
    assert!(blocked.contains("\"status\": \"blocked_launch_plan\""));

    cmd_gui_game_smoke_report(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--apply-report".to_string(),
        apply_report.to_string_lossy().to_string(),
        "--runtime-launch-plan".to_string(),
        launch_plan.to_string_lossy().to_string(),
        "--gui-error-regression".to_string(),
        error_report.to_string_lossy().to_string(),
        "--gui-visual-smoke".to_string(),
        visual_report.to_string_lossy().to_string(),
        "--game-launched".to_string(),
        "--mod-enabled".to_string(),
        "--window-name".to_string(),
        "test_gui_window".to_string(),
        "--window-opened".to_string(),
        "--screenshot".to_string(),
        screenshot.to_string_lossy().to_string(),
        "--text-fit-ok".to_string(),
        "--click-evidence".to_string(),
        "button clicked in game".to_string(),
        "--require-launch-plan".to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        game_smoke.to_string_lossy().to_string(),
    ])
    .unwrap();
    let report = read_utf8_lossy(&game_smoke).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(report.contains("\"schema\": \"hoi4skill.gui_game_smoke.v1\""));
    assert!(report.contains("\"game_smoke_passed\": true"));
    assert!(report.contains("\"game_launched\": true"));
    assert!(report.contains("\"mod_enabled\": true"));
    assert!(report.contains("\"window_opened\": true"));
    assert!(report.contains("\"launch_plan_passed\": true"));
}

#[test]
fn gui_request_workflow_resolves_indexed_sprite_and_tag_before_apply() {
    let root = unique_temp_dir("gui-request-workflow-resolve-resource");
    let target = root.join("target_mod");
    let style = root.join("style_mod");
    let game_root = root.join("game_root");
    let output_dir = root.join("workflow");
    let output = root.join("workflow.json");
    write_gui_intent_test_style_mod(&style);
    fs::create_dir_all(&target).unwrap();
    fs::create_dir_all(game_root.join("common").join("country_tags")).unwrap();
    fs::create_dir_all(game_root.join("interface")).unwrap();
    fs::write(
        game_root
            .join("common")
            .join("country_tags")
            .join("test_tags.txt"),
        "TST = \"countries/TST.txt\"\n",
    )
    .unwrap();
    fs::write(
        game_root.join("interface").join("test_gui.gfx"),
        "spriteTypes = { spriteType = { name = \"GFX_test_gui_icon\" texturefile = \"gfx/interface/test.dds\" } }\n",
    )
    .unwrap();

    cmd_gui_request_workflow(&[
        "--mod-root".to_string(),
        target.to_string_lossy().to_string(),
        "--style-mod".to_string(),
        style.to_string_lossy().to_string(),
        "--game-root".to_string(),
        game_root.to_string_lossy().to_string(),
        "--text".to_string(),
        "工业统计界面：显示【GFX_test_gui_icon图标】，目标：TST，刷新工业数据\n按钮图标：GFX_test_gui_icon".to_string(),
        "--prefix".to_string(),
        "indexed_resource_panel".to_string(),
        "--output-dir".to_string(),
        output_dir.to_string_lossy().to_string(),
        "--output".to_string(),
        output.to_string_lossy().to_string(),
    ])
    .unwrap();

    let report = read_utf8_lossy(&output).unwrap();
    let intent = read_utf8_lossy(&output_dir.join("gui_intent.md")).unwrap();
    let apply_report = read_utf8_lossy(&output_dir.join("apply_gui_intent.json")).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(report.contains("\"intent_generated\": true"));
    assert!(report.contains("\"query\": \"GFX_test_gui_icon图标\", \"status\": \"resolved\""));
    assert!(report.contains("\"query\": \"GFX_test_gui_icon\", \"status\": \"resolved\""));
    assert!(report.contains("\"query\": \"TST\", \"status\": \"resolved\""));
    assert!(report.contains("indexed_sprite:GFX_test_gui_icon"));
    assert!(report.contains("indexed_country_tag:TST"));
    assert!(!report.contains("unresolved_gui_placeholder:GFX_test_gui_icon图标"));
    assert!(!report.contains("unresolved_country_or_cosmetic_tag_reference:TST"));
    assert!(intent.contains("title: 工业统计界面：显示£GFX_test_gui_icon"));
    assert!(intent.contains("    sprite: GFX_test_gui_icon"));
    assert!(apply_report.contains("spriteType = \\\"GFX_test_gui_icon\\\""));
    assert!(!intent.contains("title: 工业统计界面：显示【GFX_test_gui_icon图标】"));
}

#[test]
fn gui_request_workflow_reuses_style_template_package_for_apply() {
    let root = unique_temp_dir("gui-request-workflow-style-package-reuse");
    let target = root.join("target_mod");
    let style = root.join("style_mod");
    let game_root = root.join("game_root");
    let style_output = root.join("style_package_source");
    let output_dir = root.join("workflow");
    let output = root.join("workflow.json");
    write_gui_intent_test_style_mod(&style);
    fs::create_dir_all(target.join("common").join("country_tags")).unwrap();
    fs::create_dir_all(target.join("interface")).unwrap();
    fs::create_dir_all(target.join("gfx").join("interface")).unwrap();
    fs::create_dir_all(game_root.join("common").join("scripted_effects")).unwrap();
    fs::create_dir_all(game_root.join("common").join("scripted_triggers")).unwrap();
    fs::write(
        target
            .join("common")
            .join("country_tags")
            .join("target_tags.txt"),
        "TST = \"countries/TST.txt\"\n",
    )
    .unwrap();
    fs::write(
        target.join("interface").join("target_gui_sprites.gfx"),
        "spriteTypes = {\n spriteType = { name = \"GFX_success_button\" texturefile = \"gfx/interface/success_button.dds\" }\n spriteType = { name = \"GFX_closebutton\" texturefile = \"gfx/interface/close.dds\" }\n}\n",
    )
    .unwrap();
    fs::write(
        target
            .join("gfx")
            .join("interface")
            .join("success_button.dds"),
        "",
    )
    .unwrap();
    fs::write(target.join("gfx").join("interface").join("close.dds"), "").unwrap();
    fs::write(
        game_root
            .join("common")
            .join("scripted_effects")
            .join("vanilla_effects.txt"),
        "set_country_flag = {}\nclr_country_flag = {}\n",
    )
    .unwrap();
    fs::write(
        game_root
            .join("common")
            .join("scripted_triggers")
            .join("vanilla_triggers.txt"),
        "has_country_flag = {}\n",
    )
    .unwrap();
    cmd_gui_style_template(&[
        "--parent-mod".to_string(),
        style.to_string_lossy().to_string(),
        "--output-dir".to_string(),
        style_output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let package_manifest = style_output.join("gui_style_template_package.json");

    cmd_gui_request_workflow(&[
        "--mod-root".to_string(),
        target.to_string_lossy().to_string(),
        "--style-mod".to_string(),
        style.to_string_lossy().to_string(),
        "--style-template-package".to_string(),
        package_manifest.to_string_lossy().to_string(),
        "--game-root".to_string(),
        game_root.to_string_lossy().to_string(),
        "--text".to_string(),
        "工业统计界面：刷新工业数据\n目标：TST\n按钮图标：GFX_success_button".to_string(),
        "--prefix".to_string(),
        "package_reuse_panel".to_string(),
        "--output-dir".to_string(),
        output_dir.to_string_lossy().to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        output.to_string_lossy().to_string(),
    ])
    .unwrap();

    let report = read_utf8_lossy(&output).unwrap();
    let apply_report = read_utf8_lossy(&output_dir.join("apply_gui_intent.json")).unwrap();
    let mount_audit = read_utf8_lossy(&output_dir.join("gui_mount_audit.json")).unwrap();
    let copied_package = read_utf8_lossy(
        &output_dir
            .join("gui_style_template_package")
            .join("gui_style_template_package.json"),
    )
    .unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(report.contains("\"status\": \"applied\""));
    assert!(report.contains("\"status\": \"provided_package_reused\""));
    assert!(report.contains("gui_mount_audit.json"));
    assert!(report.contains("\"id\": \"gui_mount_audit\""));
    assert!(report.contains("\"style_template_package_source\""));
    assert!(apply_report.contains("\"style_source\": \"style_template_file\""));
    assert!(apply_report.contains("style_template_file:"));
    assert!(mount_audit.contains("\"schema\": \"hoi4skill.gui_mount_audit.v1\""));
    assert!(mount_audit.contains("\"status\": \"passed\""));
    assert!(copied_package.contains("\"schema\": \"hoi4skill.gui_style_template_package.v1\""));
}

