#[test]
fn gui_request_workflow_resolves_parent_mount_and_country_placeholder() {
    let root = unique_temp_dir("gui-request-workflow-resolve-mount-country");
    let target = root.join("target_mod");
    let style = root.join("style_mod");
    let game_root = root.join("game_root");
    let output_dir = root.join("workflow");
    let output = root.join("workflow.json");
    write_gui_intent_test_style_mod(&style);
    fs::create_dir_all(&target).unwrap();
    fs::create_dir_all(game_root.join("common").join("country_tags")).unwrap();
    fs::create_dir_all(game_root.join("localisation").join("simp_chinese")).unwrap();
    fs::write(
        game_root
            .join("common")
            .join("country_tags")
            .join("test_tags.txt"),
        "TST = \"countries/TST.txt\"\n",
    )
    .unwrap();
    fs::write(
        game_root
            .join("localisation")
            .join("simp_chinese")
            .join("test_l_simp_chinese.yml"),
        "l_simp_chinese:\n TST:0 \"测试国\"\n",
    )
    .unwrap();

    cmd_gui_request_workflow(&[
        "--mod-root".to_string(),
        target.to_string_lossy().to_string(),
        "--style-mod".to_string(),
        style.to_string_lossy().to_string(),
        "--game-root".to_string(),
        game_root.to_string_lossy().to_string(),
        "--text".to_string(),
        "顶部工业界面：显示测试国旗帜并刷新".to_string(),
        "--gui-kind".to_string(),
        "topbar_mount".to_string(),
        "--title".to_string(),
        "显示【测试国国旗】".to_string(),
        "--prefix".to_string(),
        "mount_country_panel".to_string(),
        "--output-dir".to_string(),
        output_dir.to_string_lossy().to_string(),
        "--output".to_string(),
        output.to_string_lossy().to_string(),
    ])
    .unwrap();

    let report = read_utf8_lossy(&output).unwrap();
    let intent = read_utf8_lossy(&output_dir.join("gui_intent.md")).unwrap();
    let mount_catalog = read_utf8_lossy(&output_dir.join("gui_mount_catalog.json")).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(report.contains("\"kind\": \"parent_window_token_mount\""));
    assert!(report.contains("gui_mount_catalog.json"));
    assert!(report.contains("style_parent_window_token:top_bar"));
    assert!(report.contains("compiled_placeholder:[TST.GetFlag]"));
    assert!(mount_catalog.contains("\"schema\": \"hoi4skill.gui_mount_catalog.v1\""));
    assert!(mount_catalog.contains("\"topbar_mount\": {\"ready\": true"));
    assert!(mount_catalog.contains("\"token\": \"top_bar\""));
    assert!(mount_catalog.contains("parent_window_token:top_bar"));
    assert!(intent.contains("parent_window_token: top_bar"));
    assert!(intent.contains("title: 显示[TST.GetFlag]"));
    assert!(!intent.contains("title: 显示【测试国国旗】"));
}

