#[test]
fn gui_request_workflow_blocks_unknown_decision_category_with_candidate() {
    let root = unique_temp_dir("gui-request-workflow-decision-category-block");
    let target = root.join("target_mod");
    let style = root.join("style_mod");
    let game_root = root.join("game_root");
    let output_dir = root.join("workflow");
    let output = root.join("workflow.json");
    write_gui_intent_test_style_mod(&style);
    fs::create_dir_all(&target).unwrap();
    fs::create_dir_all(
        game_root
            .join("common")
            .join("decisions")
            .join("categories"),
    )
    .unwrap();
    fs::write(
        game_root
            .join("common")
            .join("decisions")
            .join("categories")
            .join("game_categories.txt"),
        "real_industry_category = { icon = GFX_decision_generic_industry }\n",
    )
    .unwrap();

    let err = cmd_gui_request_workflow(&[
        "--mod-root".to_string(),
        target.to_string_lossy().to_string(),
        "--style-mod".to_string(),
        style.to_string_lossy().to_string(),
        "--game-root".to_string(),
        game_root.to_string_lossy().to_string(),
        "--text".to_string(),
        "决议附属工业面板，决议分类：invented_industry_category，刷新工业数据".to_string(),
        "--gui-kind".to_string(),
        "decision_attached".to_string(),
        "--prefix".to_string(),
        "bad_decision_text_panel".to_string(),
        "--output-dir".to_string(),
        output_dir.to_string_lossy().to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        output.to_string_lossy().to_string(),
    ])
    .unwrap_err();

    let report = read_utf8_lossy(&output).unwrap();
    let ai_contract = read_utf8_lossy(&output_dir.join("gui_ai_context_contract.json")).unwrap();
    let mount_catalog = read_utf8_lossy(&output_dir.join("gui_mount_catalog.json")).unwrap();
    let related_context =
        read_utf8_lossy(&output_dir.join("gui_related_code_context.json")).unwrap();
    assert!(!output_dir.join("gui_intent.md").exists());
    assert!(!target.join("common").join("scripted_guis").exists());
    fs::remove_dir_all(&root).unwrap();

    assert_eq!(err, "gui-request-workflow did not pass");
    assert!(report.contains("\"status\": \"intent_blocked\""));
    assert!(report.contains("gui_mount_catalog.json"));
    assert!(report.contains("unknown_decision_category_mount:invented_industry_category"));
    assert!(report.contains("candidate_decision_category:real_industry_category"));
    assert!(report.contains("\"role\": \"decision_category_mount_candidate\""));
    assert!(report.contains("decision_attached_gui_requires_indexed_decision_category"));
    assert!(report.contains("\"written_to_mod\": false"));
    assert!(!report.contains("buttonType ="));
    assert!(ai_contract.contains("\"intent_authoring_allowed\": false"));
    assert!(ai_contract.contains("\"final_clausewitz_write_allowed\": false"));
    assert!(ai_contract.contains("gui_mount_catalog.json"));
    assert!(ai_contract.contains("Use gui_mount_catalog.json"));
    assert!(ai_contract.contains("unknown_decision_category_mount:invented_industry_category"));
    assert!(ai_contract.contains("gui_related_code_context.json"));
    assert!(mount_catalog.contains("\"schema\": \"hoi4skill.gui_mount_catalog.v1\""));
    assert!(mount_catalog.contains("\"decision_category\": \"real_industry_category\""));
    assert!(mount_catalog.contains("indexed_decision_category:real_industry_category"));
    assert!(related_context.contains("\"schema\": \"hoi4skill.gui_related_code_context.v1\""));
    assert!(related_context.contains("\"kind\": \"decision_category\""));
    assert!(related_context.contains("decision_category:real_industry_category"));
    assert!(related_context.contains("\"retrieval_status\": \"source_snippets_ready\""));
    assert!(related_context
        .contains("\"relative_path\": \"common/decisions/categories/game_categories.txt\""));
    assert!(related_context.contains("\"line\": 1"));
    assert!(related_context.contains(
        "\"snippet\": \"real_industry_category = { icon = GFX_decision_generic_industry }\""
    ));
    assert!(related_context.contains("do not invent final GUI code"));
}

