#[test]
fn gui_output_audit_accepts_generated_gui_files() {
    let root = unique_temp_dir("gui-output-audit-generated");
    let target = root.join("target_mod");
    let audit_output = root.join("gui_output_audit.json");
    fs::create_dir_all(target.join("common").join("scripted_guis")).unwrap();
    fs::create_dir_all(target.join("interface")).unwrap();
    fs::create_dir_all(target.join("localisation").join("simp_chinese")).unwrap();
    fs::write(
        target
            .join("common")
            .join("scripted_guis")
            .join("test_gui_main.txt"),
        "scripted_gui = {\n\ttest_gui_main = {\n\t\tcontext_type = player_context\n\t\tparent_window_token = top_bar\n\t\twindow_name = \"test_gui_window\"\n\t\tvisible = { has_country_flag = open_test_gui }\n\t\teffects = {\n\t\t\tclose_test_gui_click = { close_test_gui = yes }\n\t\t\trefresh_button_click = { refresh_test_gui = yes }\n\t\t}\n\t}\n}\n",
    )
    .unwrap();
    fs::write(
        target.join("interface").join("test_gui_window.gui"),
        "guiTypes = {\n\tcontainerWindowType = {\n\t\tname = \"test_gui_window\"\n\t\tinstantTextBoxType = { name = \"test_gui_title\" text = \"test_gui_title\" }\n\t\tbuttonType = { name = \"close_test_gui\" quadTextureSprite = \"GFX_closebutton\" }\n\t\tbuttonType = { name = \"refresh_button\" spriteType = \"GFX_button_123x34\" text = \"test_gui_refresh_button_text\" }\n\t}\n}\n",
    )
    .unwrap();
    fs::write(
        target
            .join("localisation")
            .join("simp_chinese")
            .join("test_gui_l_simp_chinese.yml"),
        "l_simp_chinese:\n test_gui_title:0 \"测试界面\"\n test_gui_refresh_button_text:0 \"刷新\"\n",
    )
    .unwrap();
    cmd_gui_output_audit(&[
        "--mod-root".to_string(),
        target.to_string_lossy().to_string(),
        "--changed".to_string(),
        "common/scripted_guis/test_gui_main.txt".to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        audit_output.to_string_lossy().to_string(),
    ])
    .unwrap();

    let report = read_utf8_lossy(&audit_output).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(report.contains("\"schema\": \"hoi4skill.gui_output_audit.v1\""));
    assert!(report.contains("\"ok\": true"));
    assert!(report
        .contains("\"final_code_safety_status\": \"candidate_only_requires_strict_code_index\""));
    assert!(report.contains("\"strict_code_index\": false"));
    assert!(report.contains("\"interface_control_type_counts\""));
    assert!(report.contains("\"control_type\": \"buttonType\""));
    assert!(report.contains("\"control_type\": \"instantTextBoxType\""));
    assert!(report.contains("\"recommended_game_code_count\": 0"));
    assert!(report.contains("\"recommended_game_code_status\": \"none\""));
    assert!(report.contains("\"blocking_count\": 0"));
}

#[test]
fn gui_output_audit_blocks_apply_and_open_plan_mismatch() {
    let root = unique_temp_dir("gui-output-audit-plan-mismatch");
    let target = root.join("target_mod");
    let apply_report = root.join("applied_gui_intent.json");
    let open_plan = root.join("gui_runtime_open_plan.json");
    let blocked_output = root.join("blocked_gui_output_audit.json");
    let passed_output = root.join("passed_gui_output_audit.json");
    fs::create_dir_all(target.join("common").join("scripted_guis")).unwrap();
    fs::create_dir_all(target.join("interface")).unwrap();
    fs::create_dir_all(target.join("localisation").join("simp_chinese")).unwrap();
    fs::write(
        target
            .join("common")
            .join("scripted_guis")
            .join("test_gui_main.txt"),
        "scripted_gui = {\n\ttest_gui_main = {\n\t\tcontext_type = player_context\n\t\twindow_name = \"wrong_window\"\n\t\teffects = {\n\t\t\tother_button_click = { refresh_test_gui = yes }\n\t\t}\n\t}\n}\n",
    )
    .unwrap();
    fs::write(
        target.join("interface").join("wrong_window.gui"),
        "guiTypes = {\n\tcontainerWindowType = {\n\t\tname = \"wrong_window\"\n\t\tbuttonType = { name = \"other_button\" }\n\t}\n}\n",
    )
    .unwrap();
    fs::write(
        &apply_report,
        "{\n  \"schema\": \"hoi4skill.apply_gui_intent.v1\",\n  \"ok\": true,\n  \"scripted_gui_id\": \"test_gui_main\",\n  \"window_name\": \"expected_window\",\n  \"changed_files\": [\"common/scripted_guis/test_gui_main.txt\", \"interface/wrong_window.gui\"]\n}\n",
    )
    .unwrap();
    fs::write(
        &open_plan,
        "{\n  \"schema\": \"hoi4skill.gui_runtime_open_plan.v1\",\n  \"open_plan_ready\": true,\n  \"window_name\": \"expected_window\",\n  \"click_target\": \"refresh_button\",\n  \"open_effect\": \"open_test_gui_effect\",\n  \"open_flag\": \"open_test_gui_flag\",\n  \"checks\": {\"mount_index_ready\": true}\n}\n",
    )
    .unwrap();

    let err = cmd_gui_output_audit(&[
        "--mod-root".to_string(),
        target.to_string_lossy().to_string(),
        "--apply-report".to_string(),
        apply_report.to_string_lossy().to_string(),
        "--runtime-open-plan".to_string(),
        open_plan.to_string_lossy().to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        blocked_output.to_string_lossy().to_string(),
    ])
    .unwrap_err();
    let blocked = read_utf8_lossy(&blocked_output).unwrap();
    assert_eq!(err, "gui-output-audit did not pass");
    assert!(blocked.contains("\"plan_audit_requested\": true"));
    assert!(blocked.contains("\"plan_audit_ready\": false"));
    assert!(
        blocked.contains("output_plan_scripted_gui_window_mismatch:test_gui_main:expected_window")
    );
    assert!(blocked.contains("output_plan_missing_window:expected_window"));
    assert!(blocked.contains("output_plan_missing_click_target:refresh_button"));
    assert!(blocked.contains("output_plan_missing_open_effect:open_test_gui_effect"));
    assert!(blocked.contains("output_plan_missing_open_flag:open_test_gui_flag"));
    assert!(blocked.contains(
        "scripted_gui_action_helper_missing_scripted_effect:test_gui_main:refresh_test_gui"
    ));
    assert!(blocked.contains("Define the missing open/close helper in common/scripted_effects"));
    assert!(blocked.contains("\"role\": \"gui_evidence_required\""));
    assert!(blocked.contains("blocked_no_clausewitz_candidate"));

    fs::write(
        target
            .join("common")
            .join("scripted_guis")
            .join("test_gui_main.txt"),
        "scripted_gui = {\n\ttest_gui_main = {\n\t\tcontext_type = player_context\n\t\twindow_name = \"expected_window\"\n\t\tvisible = { has_country_flag = open_test_gui_flag }\n\t\teffects = {\n\t\t\trefresh_button_click = { refresh_test_gui = yes }\n\t\t}\n\t}\n}\n",
    )
    .unwrap();
    fs::write(
        target.join("interface").join("expected_window.gui"),
        "guiTypes = {\n\tcontainerWindowType = {\n\t\tname = \"expected_window\"\n\t\tbuttonType = { name = \"refresh_button\" }\n\t}\n}\n",
    )
    .unwrap();
    fs::create_dir_all(target.join("common").join("scripted_effects")).unwrap();
    fs::write(
        target
            .join("common")
            .join("scripted_effects")
            .join("test_gui_main.txt"),
        "open_test_gui_effect = {\n\tset_country_flag = open_test_gui_flag\n}\nrefresh_test_gui = {\n}\n",
    )
    .unwrap();

    cmd_gui_output_audit(&[
        "--mod-root".to_string(),
        target.to_string_lossy().to_string(),
        "--apply-report".to_string(),
        apply_report.to_string_lossy().to_string(),
        "--runtime-open-plan".to_string(),
        open_plan.to_string_lossy().to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        passed_output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let passed = read_utf8_lossy(&passed_output).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(passed.contains("\"ok\": true"));
    assert!(passed.contains("\"plan_audit_requested\": true"));
    assert!(passed.contains("\"plan_audit_ready\": true"));
    assert!(
        passed.contains("scripted_gui_window:test_gui_main-&gt;expected_window")
            || passed.contains("scripted_gui_window:test_gui_main->expected_window")
    );
    assert!(passed.contains("click_target:refresh_button"));
    assert!(passed.contains("open_effect:open_test_gui_effect"));
    assert!(passed.contains("open_flag:open_test_gui_flag"));
}

