#[test]
fn gui_output_audit_blocks_missing_button_and_localisation() {
    let root = unique_temp_dir("gui-output-audit-blocked");
    let target = root.join("target_mod");
    fs::create_dir_all(target.join("common").join("scripted_guis")).unwrap();
    fs::create_dir_all(target.join("interface")).unwrap();
    fs::create_dir_all(target.join("localisation").join("simp_chinese")).unwrap();
    fs::write(
        target
            .join("common")
            .join("scripted_guis")
            .join("bad_gui.txt"),
        "scripted_gui = {\n\tbad_gui = {\n\t\tcontext_type = player_context\n\t\twindow_name = \"bad_window\"\n\t\teffects = {\n\t\t\tmissing_button_click = { bad_effect = yes }\n\t\t}\n\t}\n}\n",
    )
    .unwrap();
    fs::write(
        target.join("interface").join("bad_window.gui"),
        "guiTypes = {\n\tcontainerWindowType = {\n\t\tname = \"bad_window\"\n\t\tbuttonType = {\n\t\t\tname = \"other_button\"\n\t\t\tspriteType = \"<verified_GFX_button_sprite>\"\n\t\t\ttext = \"missing_bad_gui_text\"\n\t\t}\n\t}\n}\n",
    )
    .unwrap();
    fs::write(
        target
            .join("localisation")
            .join("simp_chinese")
            .join("bad_gui_l_simp_chinese.yml"),
        "l_simp_chinese:\n bad_other_key:0 \"坏\"\n",
    )
    .unwrap();
    let output = root.join("gui_output_audit.json");

    let err = cmd_gui_output_audit(&[
        "--mod-root".to_string(),
        target.to_string_lossy().to_string(),
        "--changed".to_string(),
        "common/scripted_guis/bad_gui.txt".to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        output.to_string_lossy().to_string(),
    ])
    .unwrap_err();

    let report = read_utf8_lossy(&output).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert_eq!(err, "gui-output-audit did not pass");
    assert!(report.contains("\"ok\": false"));
    assert!(report.contains("\"final_code_safety_status\": \"blocked_no_clausewitz_candidate\""));
    assert!(report.contains(
        "scripted_gui_click_handler_missing_interface_button:bad_gui:missing_button_click"
    ));
    assert!(report.contains("interface_text_missing_localisation:missing_bad_gui_text"));
    assert!(report.contains("interface_sprite_unresolved_template:<verified_GFX_button_sprite>"));
    assert!(report.contains("\"interface_sprite_ref_count\": 1"));
    assert!(report.contains("\"recommended_game_code\""));
    assert!(report.contains("\"recommended_game_code_count\": 2"));
    assert!(report.contains("\"recommended_game_code_status\": \"mixed_evidence_and_candidates\""));
    assert!(report.contains("\"recommended_syntax_count\":"));
    assert!(report.contains("For every scripted_gui click handler"));
    assert!(report.contains("Add missing GUI localisation"));
    assert!(report.contains("Register GUI sprite refs in interface"));
    assert!(report.contains("\"role\": \"localisation_candidate\""));
    assert!(report.contains("missing_bad_gui_text:0 \\\"<user-approved visible GUI text>\\\""));
    assert!(report.contains("\"role\": \"gui_evidence_required\""));
    assert!(report.contains("blocked_no_clausewitz_candidate"));
}

