fn write_gui_intent_test_style_mod(style: &Path) {
    let scripted_gui_dir = style.join("common").join("scripted_guis");
    let effects_dir = style.join("common").join("scripted_effects");
    let interface_dir = style.join("interface");
    fs::create_dir_all(&scripted_gui_dir).unwrap();
    fs::create_dir_all(&effects_dir).unwrap();
    fs::create_dir_all(&interface_dir).unwrap();
    fs::write(
        scripted_gui_dir.join("style_gui.txt"),
        "scripted_gui = {\n  style_standalone_gui = { context_type = player_context parent_window_token = top_bar window_name = \"style_standalone_window\" visible = { has_country_flag = open_style_gui } effects = { close_style_gui_click = { clr_country_flag = open_style_gui } } }\n}\n",
    )
    .unwrap();
    fs::write(
        effects_dir.join("style_gui_effects.txt"),
        "open_style_gui = { set_country_flag = open_style_gui set_temp_variable = { temp_style_gui = 1 } custom_effect_tooltip = style_gui_tt }\nclose_style_gui = { clr_country_flag = open_style_gui }\n",
    )
    .unwrap();
    fs::write(
        interface_dir.join("style_gui.gui"),
        "guiTypes = { containerWindowType = { name = \"style_standalone_window\" instantTextBoxType = { name = \"style_title\" font = \"hoi_30header\" text = \"style_title\" } buttonType = { name = \"close_style_gui\" quadTextureSprite = \"GFX_closebutton\" buttonFont = \"Main_14_black\" } buttonType = { name = \"style_refresh_button\" spriteType = \"GFX_button_123x34\" buttonFont = \"Main_14_black\" } } }\n",
    )
    .unwrap();
    fs::write(
        interface_dir.join("style_gui.gfx"),
        "spriteTypes = {\n spriteType = { name = \"GFX_closebutton\" texturefile = \"gfx/interface/close.dds\" }\n spriteType = { name = \"GFX_button_123x34\" texturefile = \"gfx/interface/button.dds\" }\n}\n",
    )
    .unwrap();
}

