#[test]
fn gui_mount_audit_blocks_unknown_parent_token_and_accepts_style_evidence() {
    let root = unique_temp_dir("gui-mount-audit-parent-token");
    let target = root.join("target");
    let style = root.join("style");
    let output = root.join("gui_mount_audit.json");
    write_gui_intent_test_style_mod(&style);
    fs::create_dir_all(target.join("common").join("scripted_guis")).unwrap();
    fs::create_dir_all(target.join("interface")).unwrap();
    fs::write(
        target
            .join("common")
            .join("scripted_guis")
            .join("target_gui.txt"),
        "scripted_gui = {\n target_gui = {\n  context_type = player_context\n  parent_window_token = bad_parent\n  window_name = \"target_window\"\n }\n}\n",
    )
    .unwrap();
    fs::write(
        target.join("interface").join("target_gui.gui"),
        "guiTypes = {\n containerWindowType = {\n  name = \"target_window\"\n  size = { width = 300 height = 200 }\n }\n}\n",
    )
    .unwrap();

    let err = cmd_gui_mount_audit(&[
        "--mod-root".to_string(),
        target.to_string_lossy().to_string(),
        "--style-mod".to_string(),
        style.to_string_lossy().to_string(),
        "--gui-kind".to_string(),
        "topbar_mount".to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        output.to_string_lossy().to_string(),
    ])
    .unwrap_err();
    let blocked = read_utf8_lossy(&output).unwrap();
    assert_eq!(err, "gui-mount-audit did not pass");
    assert!(blocked.contains("\"schema\": \"hoi4skill.gui_mount_audit.v1\""));
    assert!(blocked.contains("unknown_parent_window_token_mount:bad_parent"));
    assert!(blocked.contains("top_bar"));

    fs::write(
        target
            .join("common")
            .join("scripted_guis")
            .join("target_gui.txt"),
        "scripted_gui = {\n target_gui = {\n  context_type = player_context\n  parent_window_token = top_bar\n  window_name = \"target_window\"\n }\n}\n",
    )
    .unwrap();
    cmd_gui_mount_audit(&[
        "--mod-root".to_string(),
        target.to_string_lossy().to_string(),
        "--style-mod".to_string(),
        style.to_string_lossy().to_string(),
        "--gui-kind".to_string(),
        "topbar_mount".to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let passed = read_utf8_lossy(&output).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(passed.contains("\"status\": \"passed\""));
    assert!(passed.contains("\"parent_window_tokens\": [\"top_bar\"]"));
}

