#[test]
fn author_work_packages_text_keeps_effect_continuation_with_previous_lane() {
    let root = unique_temp_dir("author-work-packages-text-continuation");
    let blueprint_path = root.join("blueprint.yml");
    let mod_root = root.join("mod");
    fs::create_dir_all(&root).unwrap();
    fs::write(
        &blueprint_path,
        r#"schema: "hoi4skill.large_mod_blueprint.v1"
name: "Continuation Test"
acronym: "CNT"
default_language: "simp_chinese"
summary: |-
  Test continuation routing.
countries:
regions:
systems:
  - id: decision_content
    name: Decision Content
    priority: major
  - id: dynamic_modifier_content
    name: Dynamic Modifier Content
    priority: major
milestones:
asset_needs:
localisation_languages:
  - simp_chinese
"#,
    )
    .unwrap();
    cmd_init_large_mod(&[
        "--blueprint".to_string(),
        blueprint_path.to_string_lossy().to_string(),
        "--output".to_string(),
        mod_root.to_string_lossy().to_string(),
    ])
    .unwrap();

    cmd_author_work_packages(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--text".to_string(),
        "决议：镇压资本家\n效果：稳定度 +5%\n动态修正：中国制造\n生产效率上限 +0.05".to_string(),
        "--plan-only".to_string(),
        "--output".to_string(),
        root.join("author_queue.json").to_string_lossy().to_string(),
    ])
    .unwrap();

    let generated = read_utf8_lossy(
        &mod_root
            .join(".hoi4skill")
            .join("package_requests_from_text.md"),
    )
    .unwrap();
    fs::remove_dir_all(&root).unwrap();

    let decision_section = generated
        .split("## system_decision_content")
        .nth(1)
        .unwrap()
        .split("## ")
        .next()
        .unwrap();
    let dynamic_section = generated
        .split("## system_dynamic_modifier_content")
        .nth(1)
        .unwrap()
        .split("## ")
        .next()
        .unwrap();
    assert!(decision_section.contains("决议：镇压资本家"));
    assert!(decision_section.contains("效果：稳定度 +5%"));
    assert!(!decision_section.contains("生产效率上限 +0.05"));
    assert!(dynamic_section.contains("动态修正：中国制造"));
    assert!(dynamic_section.contains("生产效率上限 +0.05"));
    assert!(!dynamic_section.contains("效果：稳定度 +5%"));
}

