#[test]
fn work_package_run_changed_file_tracks_allowed_content_changes() {
    let root = unique_temp_dir("run-work-package-changed-file");
    let mod_root = root.join("mod");
    fs::create_dir_all(mod_root.join("common/national_focus")).unwrap();
    fs::create_dir_all(mod_root.join("events")).unwrap();
    fs::create_dir_all(mod_root.join(".hoi4skill")).unwrap();
    fs::write(
        mod_root.join("common/national_focus/RUS.txt"),
        "focus_tree = {}\n",
    )
    .unwrap();
    fs::write(mod_root.join(".hoi4skill/ignored.json"), "{}\n").unwrap();

    let package = WorkPackage {
        id: "country_rus".to_string(),
        kind: "country".to_string(),
        title: "RUS Country Content".to_string(),
        allowed_paths: vec!["common/national_focus".to_string(), "events".to_string()],
        deliverables: Vec::new(),
        validation_steps: Vec::new(),
    };
    let before = snapshot_work_package_allowed_files(&mod_root, &package).unwrap();
    fs::write(
        mod_root.join("common/national_focus/RUS.txt"),
        "focus_tree = { focus = { id = rus_opening } }\n",
    )
    .unwrap();
    fs::write(
        mod_root.join("events/rus_events.txt"),
        "add_namespace = rus\n",
    )
    .unwrap();
    fs::write(
        mod_root.join(".hoi4skill/ignored.json"),
        "{\"changed\":true}\n",
    )
    .unwrap();

    let changed = diff_work_package_allowed_files(&mod_root, &package, &before).unwrap();
    assert_eq!(
        changed,
        vec![
            "common/national_focus/RUS.txt".to_string(),
            "events/rus_events.txt".to_string()
        ]
    );
    let changed_file = write_work_package_run_changed_file(&mod_root, &package, &changed).unwrap();
    let changed_text = read_utf8_lossy(&changed_file).unwrap();
    assert!(changed_text.contains("common/national_focus/RUS.txt"));
    assert!(changed_text.contains("events/rus_events.txt"));
    assert!(!changed_text.contains(".hoi4skill"));
}

#[test]
fn work_package_success_evidence_blocks_missing_sample_acceptance_content() {
    let root = unique_temp_dir("run-work-package-success-evidence");
    let blueprint_path = root.join("blueprint.yml");
    let mod_root = root.join("mod");
    let output_dir = root.join("run");

    cmd_plan_large_mod(&[
        "--text".to_string(),
        "name: Test Grand Campaign\ncountries: RUS\nregions: europe".to_string(),
        "--name".to_string(),
        "Test Grand Campaign".to_string(),
        "--acronym".to_string(),
        "TGC".to_string(),
        "--output".to_string(),
        blueprint_path.to_string_lossy().to_string(),
    ])
    .unwrap();
    cmd_init_large_mod(&[
        "--blueprint".to_string(),
        blueprint_path.to_string_lossy().to_string(),
        "--output".to_string(),
        mod_root.to_string_lossy().to_string(),
    ])
    .unwrap();
    fs::create_dir_all(&output_dir).unwrap();
    fs::write(output_dir.join("run.json"), "{}\n").unwrap();
    let changed_file = mod_root.join(".hoi4skill").join("changed_country_rus.txt");
    fs::write(&changed_file, "events/rus_events.txt\n").unwrap();

    let package = WorkPackage {
        id: "country_rus".to_string(),
        kind: "country".to_string(),
        title: "RUS Country Content".to_string(),
        allowed_paths: vec!["events".to_string()],
        deliverables: Vec::new(),
        validation_steps: Vec::new(),
    };
    let mut steps = Vec::new();
    let args = vec![
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--package".to_string(),
        "country_rus".to_string(),
    ];
    let map = parse_args(&args);
    let err = run_work_package_success_evidence(
        &package,
        &mod_root,
        &output_dir,
        &changed_file,
        &mut steps,
        &map,
    )
    .unwrap_err();

    assert!(err.contains("large-mod-sample-acceptance did not accept"));
    let sample_acceptance =
        read_utf8_lossy(&mod_root.join(".hoi4skill/sample_acceptance_country_rus.json")).unwrap();
    assert!(sample_acceptance.contains("\"accepted\": false"));
    assert!(sample_acceptance.contains("\"six_content_families_ok\": false"));
    assert!(sample_acceptance.contains("\"id\": \"event_chain\", \"ok\": false"));
    assert!(steps
        .iter()
        .any(|step| step.name == "package_sample_acceptance" && step.status == "failed"));
    let playtest = read_utf8_lossy(&mod_root.join(".hoi4skill/playtest_country_rus.json")).unwrap();
    assert!(playtest.contains("\"schema\": \"hoi4skill.playtest_report.v1\""));
    assert!(playtest.contains("\"status\": \"needs_review\""));
    assert!(playtest.contains("manual in-game playtest not completed"));
    let playtest_gate = read_utf8_lossy(&mod_root.join(".hoi4skill/playtest_gate.json")).unwrap();
    assert!(playtest_gate.contains("\"playtest_complete\": false"));
    assert!(playtest_gate.contains("playtest_needs_review"));
    assert!(!mod_root.join(".hoi4skill/release_gate.json").exists());
    assert!(!mod_root.join(".hoi4skill/evidence_pack.json").exists());
    assert!(!output_dir.join("evidence/evidence_steps.json").exists());
    assert!(steps
        .iter()
        .any(|step| step.name == "playtest_report_skeleton"));
    assert!(!steps
        .iter()
        .any(|step| step.name == "release_gate_snapshot"));
}

