#[test]
fn large_mod_release_gate_blocks_prewrite_runtime_evidence() {
    let root = unique_temp_dir("large-mod-release-gate-prewrite-runtime");
    let blueprint_path = root.join("blueprint.yml");
    let mod_root = root.join("mod");
    let blocked_output = root.join("release_gate_blocked.json");
    let passed_output = root.join("release_gate_passed.json");
    let prewrite = root.join("runtime_prewrite.json");

    cmd_plan_large_mod(&[
        "--text".to_string(),
        "name: Test Grand Campaign\ncountries: RUS".to_string(),
        "--name".to_string(),
        "Test Grand Campaign".to_string(),
        "--acronym".to_string(),
        "TGC".to_string(),
        "--output".to_string(),
        blueprint_path.to_string_lossy().to_string(),
    ])
    .unwrap();
    cmd_init_large_mod(&[
        "--blueprint".to_string(),
        blueprint_path.to_string_lossy().to_string(),
        "--output".to_string(),
        mod_root.to_string_lossy().to_string(),
    ])
    .unwrap();

    for (name, text) in [
        ("mod_index.json", "{\n  \"schema\": \"hoi4skill.mod_index.v1\"\n}\n"),
        ("ai_context_contract.json", clean_ai_context_contract_json()),
        (
            "ownership_map.json",
            "{\n  \"schema\": \"hoi4skill.large_mod_ownership_map.v1\"\n}\n",
        ),
        (
            "dependency_graph.json",
            "{\n  \"schema\": \"hoi4skill.large_mod_dependency_graph.v1\",\n  \"cycle_count\": 0\n}\n",
        ),
        (
            "loc_audit.json",
            "{\n  \"schema\": \"hoi4skill.loc_audit.v1\",\n  \"missing_count\": 0\n}\n",
        ),
        ("text_alignment.json", clean_text_alignment_json()),
        (
            "gfx_audit.json",
            "{\n  \"schema\": \"hoi4skill.gfx_audit.v1\",\n  \"missing_sprites_count\": 0\n}\n",
        ),
        (
            "logic_audit.json",
            "{\n  \"schema\": \"hoi4skill.logic_audit.v1\",\n  \"issue_count\": 0\n}\n",
        ),
        ("validation.json", clean_strict_validation_report_json()),
        ("error_log_report.json", clean_error_log_report_json()),
        ("merge_gate.json", clean_large_mod_merge_gate_json()),
        (
            "regression_gate.json",
            "{\n  \"schema\": \"hoi4skill.large_mod_regression_gate.v1\",\n  \"regression_passed\": true,\n  \"blocking_count\": 0\n}\n",
        ),
        (
            "playtest_gate.json",
            "{\n  \"schema\": \"hoi4skill.large_mod_playtest_gate.v1\",\n  \"playtest_complete\": true,\n  \"missing_report_count\": 0,\n  \"needs_review_count\": 0,\n  \"blocked_package_count\": 0\n}\n",
        ),
        ("capability_audit.json", clean_capability_audit_json()),
        ("content_audit.json", clean_content_audit_json()),
        (
            "work_package_status.json",
            "{\n  \"schema\": \"hoi4skill.work_package_status.v1\",\n  \"status\": \"ok\"\n}\n",
        ),
        (
            "readiness.json",
            "{\n  \"schema\": \"hoi4skill.work_package_readiness.v1\",\n  \"blocked_count\": 0,\n  \"missing_package_count\": 0\n}\n",
        ),
    ] {
        fs::write(mod_root.join(".hoi4skill").join(name), text).unwrap();
    }
    fs::write(
        &prewrite,
        "{\n  \"schema\": \"hoi4skill.runtime_evidence_gate.v1\",\n  \"ok\": true,\n  \"status\": \"prewrite_evidence_ready\",\n  \"checks\": {\"route_prewrite_only\": true},\n  \"blockers\": []\n}\n",
    )
    .unwrap();

    cmd_large_mod_release_gate(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--report".to_string(),
        prewrite.to_string_lossy().to_string(),
        "--output".to_string(),
        blocked_output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let blocked = read_utf8_lossy(&blocked_output).unwrap();
    assert!(blocked.contains("\"releasable\": false"));
    assert!(blocked.contains("runtime_prewrite.json"));
    assert!(blocked.contains("runtime_evidence_status=prewrite_evidence_ready"));
    assert!(blocked.contains("route_prewrite_only=true"));

    fs::write(
        &prewrite,
        "{\n  \"schema\": \"hoi4skill.runtime_evidence_gate.v1\",\n  \"ok\": true,\n  \"status\": \"runtime_evidence_ready\",\n  \"checks\": {\"route_prewrite_only\": false},\n  \"blockers\": []\n}\n",
    )
    .unwrap();
    cmd_large_mod_release_gate(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--report".to_string(),
        prewrite.to_string_lossy().to_string(),
        "--require-passed".to_string(),
        "--output".to_string(),
        passed_output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let passed = read_utf8_lossy(&passed_output).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(passed.contains("\"releasable\": true"));
}

