#[test]
fn large_mod_release_gate_requires_clean_regression_gate() {
    let root = unique_temp_dir("large-mod-release-regression-gate");
    let blueprint_path = root.join("blueprint.yml");
    let mod_root = root.join("mod");
    let missing_output = root.join("release_gate_missing_regression.json");
    let failing_output = root.join("release_gate_failing_regression.json");
    let missing_merge_evidence_output = root.join("release_gate_missing_merge_evidence.json");
    let bad_merge_output = root.join("release_gate_bad_merge.json");
    let passed_output = root.join("release_gate_passed_regression.json");

    cmd_plan_large_mod(&[
        "--text".to_string(),
        "name: Test Grand Campaign\ncountries: RUS\nregions: europe\nsystems: black monday"
            .to_string(),
        "--name".to_string(),
        "Test Grand Campaign".to_string(),
        "--acronym".to_string(),
        "TGC".to_string(),
        "--output".to_string(),
        blueprint_path.to_string_lossy().to_string(),
    ])
    .unwrap();

    cmd_init_large_mod(&[
        "--blueprint".to_string(),
        blueprint_path.to_string_lossy().to_string(),
        "--output".to_string(),
        mod_root.to_string_lossy().to_string(),
    ])
    .unwrap();

    for (name, text) in [
        (
            "mod_index.json",
            "{\n  \"schema\": \"hoi4skill.mod_index.v1\"\n}\n",
        ),
        ("ai_context_contract.json", clean_ai_context_contract_json()),
        (
            "ownership_map.json",
            "{\n  \"schema\": \"hoi4skill.large_mod_ownership_map.v1\"\n}\n",
        ),
        (
            "dependency_graph.json",
            "{\n  \"schema\": \"hoi4skill.large_mod_dependency_graph.v1\",\n  \"cycle_count\": 0\n}\n",
        ),
        (
            "loc_audit.json",
            "{\n  \"schema\": \"hoi4skill.loc_audit.v1\",\n  \"missing_count\": 0\n}\n",
        ),
        ("text_alignment.json", clean_text_alignment_json()),
        (
            "gfx_audit.json",
            "{\n  \"schema\": \"hoi4skill.gfx_audit.v1\",\n  \"missing_sprites_count\": 0\n}\n",
        ),
        (
            "logic_audit.json",
            "{\n  \"schema\": \"hoi4skill.logic_audit.v1\",\n  \"issue_count\": 0\n}\n",
        ),
        ("validation.json", clean_strict_validation_report_json()),
        (
            "work_package_status.json",
            "{\n  \"schema\": \"hoi4skill.work_package_status.v1\",\n  \"status\": \"ok\"\n}\n",
        ),
        (
            "readiness.json",
            "{\n  \"schema\": \"hoi4skill.work_package_readiness.v1\",\n  \"blocked_count\": 0,\n  \"missing_package_count\": 0\n}\n",
        ),
    ] {
        fs::write(mod_root.join(".hoi4skill").join(name), text).unwrap();
    }

    cmd_large_mod_release_gate(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--output".to_string(),
        missing_output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let missing = read_utf8_lossy(&missing_output).unwrap();
    assert!(missing.contains("\"releasable\": false"));
    assert!(missing.contains("\"error_log_report.json\""));
    assert!(missing.contains("\"merge_gate.json\""));
    assert!(missing.contains("\"regression_gate.json\""));
    assert!(missing.contains("\"playtest_gate.json\""));

    fs::write(
        mod_root.join(".hoi4skill/regression_gate.json"),
        "{\n  \"schema\": \"hoi4skill.large_mod_regression_gate.v1\",\n  \"regression_passed\": false,\n  \"blocking_count\": 1\n}\n",
    )
    .unwrap();

    cmd_large_mod_release_gate(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--output".to_string(),
        failing_output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let failing = read_utf8_lossy(&failing_output).unwrap();
    assert!(failing.contains("\"releasable\": false"));
    assert!(failing.contains("regression_gate.json"));
    assert!(failing.contains("error_log_report.json"));
    assert!(failing.contains("merge_gate.json"));
    assert!(failing.contains("\"blocking_count=1\""));

    fs::write(
        mod_root.join(".hoi4skill/error_log_report.json"),
        clean_error_log_report_json(),
    )
    .unwrap();
    fs::write(
        mod_root.join(".hoi4skill/regression_gate.json"),
        "{\n  \"schema\": \"hoi4skill.large_mod_regression_gate.v1\",\n  \"regression_passed\": true,\n  \"blocking_count\": 0\n}\n",
    )
    .unwrap();
    fs::write(
        mod_root.join(".hoi4skill/playtest_gate.json"),
        "{\n  \"schema\": \"hoi4skill.large_mod_playtest_gate.v1\",\n  \"playtest_complete\": true,\n  \"missing_report_count\": 0,\n  \"needs_review_count\": 0,\n  \"blocked_package_count\": 0\n}\n",
    )
    .unwrap();
    fs::write(
        mod_root.join(".hoi4skill/merge_gate.json"),
        "{\n  \"schema\": \"hoi4skill.large_mod_merge_gate.v1\"\n}\n",
    )
    .unwrap();

    cmd_large_mod_release_gate(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--output".to_string(),
        missing_merge_evidence_output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let missing_merge_evidence = read_utf8_lossy(&missing_merge_evidence_output).unwrap();
    assert!(missing_merge_evidence.contains("\"releasable\": false"));
    assert!(missing_merge_evidence.contains("merge_gate.json"));
    assert!(missing_merge_evidence.contains("\"mergeable=missing_or_false\""));
    assert!(missing_merge_evidence.contains("\"blocking_count=missing_or_nonzero\""));

    fs::write(
        mod_root.join(".hoi4skill/merge_gate.json"),
        "{\n  \"schema\": \"hoi4skill.large_mod_merge_gate.v1\",\n  \"mergeable\": false,\n  \"blocking_count\": 1\n}\n",
    )
    .unwrap();

    cmd_large_mod_release_gate(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--output".to_string(),
        bad_merge_output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let bad_merge = read_utf8_lossy(&bad_merge_output).unwrap();
    assert!(bad_merge.contains("\"releasable\": false"));
    assert!(bad_merge.contains("merge_gate.json"));
    assert!(bad_merge.contains("\"blocking_count=1\""));

    fs::write(
        mod_root.join(".hoi4skill/merge_gate.json"),
        clean_large_mod_merge_gate_json(),
    )
    .unwrap();
    fs::write(
        mod_root.join(".hoi4skill/capability_audit.json"),
        clean_capability_audit_json(),
    )
    .unwrap();
    fs::write(
        mod_root.join(".hoi4skill/content_audit.json"),
        clean_content_audit_json(),
    )
    .unwrap();

    cmd_large_mod_release_gate(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--output".to_string(),
        passed_output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let passed = read_utf8_lossy(&passed_output).unwrap();
    assert!(passed.contains("\"releasable\": true"));
    assert!(passed.contains("\"missing_required_reports\": []"));
    assert!(passed.contains("\"blocking_count\": 0"));
}

