#[test]
fn large_mod_release_gate_requires_resolved_submod_dependencies() {
    let root = unique_temp_dir("large-mod-release-submod-dependencies");
    let blueprint_path = root.join("blueprint.yml");
    let mod_root = root.join("mod");
    let missing_output = root.join("release_gate_missing_dependencies.json");
    let unresolved_output = root.join("release_gate_unresolved_dependencies.json");
    let resolved_output = root.join("release_gate_resolved_dependencies.json");

    cmd_plan_large_mod(&[
        "--text".to_string(),
        "name: KXC Test Submod\ncountries: RUS".to_string(),
        "--name".to_string(),
        "KXC Test Submod".to_string(),
        "--acronym".to_string(),
        "KXCT".to_string(),
        "--output".to_string(),
        blueprint_path.to_string_lossy().to_string(),
    ])
    .unwrap();

    cmd_init_large_mod(&[
        "--blueprint".to_string(),
        blueprint_path.to_string_lossy().to_string(),
        "--output".to_string(),
        mod_root.to_string_lossy().to_string(),
    ])
    .unwrap();
    fs::write(
        mod_root.join("descriptor.mod"),
        "name=\"KXC Test Submod\"\ndependencies={ \"Kaiserredux\" }\nsupported_version=\"*\"\n",
    )
    .unwrap();

    for (name, text) in [
        (
            "mod_index.json",
            "{\n  \"schema\": \"hoi4skill.mod_index.v1\"\n}\n",
        ),
        ("ai_context_contract.json", clean_ai_context_contract_json()),
        (
            "ownership_map.json",
            "{\n  \"schema\": \"hoi4skill.large_mod_ownership_map.v1\"\n}\n",
        ),
        (
            "dependency_graph.json",
            "{\n  \"schema\": \"hoi4skill.large_mod_dependency_graph.v1\",\n  \"cycle_count\": 0\n}\n",
        ),
        (
            "loc_audit.json",
            "{\n  \"schema\": \"hoi4skill.loc_audit.v1\",\n  \"missing_count\": 0\n}\n",
        ),
        ("text_alignment.json", clean_text_alignment_json()),
        (
            "gfx_audit.json",
            "{\n  \"schema\": \"hoi4skill.gfx_audit.v1\",\n  \"missing_sprites_count\": 0\n}\n",
        ),
        (
            "logic_audit.json",
            "{\n  \"schema\": \"hoi4skill.logic_audit.v1\",\n  \"issue_count\": 0\n}\n",
        ),
        ("validation.json", clean_strict_validation_report_json()),
        ("error_log_report.json", clean_error_log_report_json()),
        (
            "regression_gate.json",
            "{\n  \"schema\": \"hoi4skill.large_mod_regression_gate.v1\",\n  \"regression_passed\": true,\n  \"blocking_count\": 0\n}\n",
        ),
        (
            "playtest_gate.json",
            "{\n  \"schema\": \"hoi4skill.large_mod_playtest_gate.v1\",\n  \"playtest_complete\": true,\n  \"missing_report_count\": 0,\n  \"needs_review_count\": 0,\n  \"blocked_package_count\": 0\n}\n",
        ),
        ("merge_gate.json", clean_large_mod_merge_gate_json()),
        ("capability_audit.json", clean_capability_audit_json()),
        ("content_audit.json", clean_content_audit_json()),
        (
            "work_package_status.json",
            "{\n  \"schema\": \"hoi4skill.work_package_status.v1\",\n  \"status\": \"ok\"\n}\n",
        ),
        (
            "readiness.json",
            "{\n  \"schema\": \"hoi4skill.work_package_readiness.v1\",\n  \"blocked_count\": 0,\n  \"missing_package_count\": 0\n}\n",
        ),
    ] {
        fs::write(mod_root.join(".hoi4skill").join(name), text).unwrap();
    }

    cmd_large_mod_release_gate(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--output".to_string(),
        missing_output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let missing = read_utf8_lossy(&missing_output).unwrap();
    assert!(missing.contains("\"releasable\": false"));
    assert!(missing.contains("\"mod_dependencies.json\""));
    assert!(missing.contains("\"mod_knowledge.json\""));
    assert!(missing.contains("resolve-mod-dependencies"));
    assert!(missing.contains("mod-knowledge"));

    fs::write(
        mod_root.join(".hoi4skill/mod_dependencies.json"),
        "{\n  \"schema\": \"hoi4skill.mod_dependencies.v1\",\n  \"dependency_names\": [\"Kaiserredux\"],\n  \"dependencies\": [{\"name\": \"Kaiserredux\", \"status\": \"missing\", \"candidates\": []}]\n}\n",
    )
    .unwrap();
    cmd_large_mod_release_gate(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--output".to_string(),
        unresolved_output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let unresolved = read_utf8_lossy(&unresolved_output).unwrap();
    assert!(unresolved.contains("\"releasable\": false"));
    assert!(unresolved.contains("mod_dependencies.json"));
    assert!(unresolved.contains("\"schema=hoi4skill.mod_dependencies.v1\""));
    assert!(unresolved.contains("\"status=missing\""));

    fs::write(
        mod_root.join(".hoi4skill/mod_dependencies.json"),
        "{\n  \"schema\": \"hoi4skill.mod_dependencies.v1\",\n  \"dependency_names\": [\"Kaiserredux\"],\n  \"recommended_mod_path_args\": [\"M:\\\\mods\\\\Kaiserredux\"],\n  \"dependencies\": [{\"name\": \"Kaiserredux\", \"status\": \"resolved\", \"candidates\": []}]\n}\n",
    )
    .unwrap();
    fs::write(
        mod_root.join(".hoi4skill/mod_knowledge.json"),
        "{\n  \"schema\": \"hoi4skill.mod_knowledge.v1\",\n  \"mod_kind\": \"submod\",\n  \"dependency_names\": [\"Kaiserredux\"],\n  \"dependency_mod_roots\": [\"M:\\\\mods\\\\Kaiserredux\"],\n  \"knowledge_base\": {},\n  \"markdown_summary\": \"dependency indexed\"\n}\n",
    )
    .unwrap();
    cmd_large_mod_release_gate(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--output".to_string(),
        resolved_output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let resolved = read_utf8_lossy(&resolved_output).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(resolved.contains("\"releasable\": true"));
    assert!(resolved.contains("\"missing_required_reports\": []"));
    assert!(resolved.contains("\"blocking_count\": 0"));
}

#[test]
fn identify_work_packages_maps_changed_files_to_strict_package_matches() {
    let root = unique_temp_dir("identify-work-packages");
    let blueprint_path = root.join("blueprint.yml");
    let mod_root = root.join("mod");
    let output = root.join("changed_work_packages.json");

    cmd_plan_large_mod(&[
        "--text".to_string(),
        "name: Test Grand Campaign\ncountries: RUS, GER\nregions: europe\nsystems: black monday"
            .to_string(),
        "--name".to_string(),
        "Test Grand Campaign".to_string(),
        "--acronym".to_string(),
        "TGC".to_string(),
        "--output".to_string(),
        blueprint_path.to_string_lossy().to_string(),
    ])
    .unwrap();

    cmd_init_large_mod(&[
        "--blueprint".to_string(),
        blueprint_path.to_string_lossy().to_string(),
        "--output".to_string(),
        mod_root.to_string_lossy().to_string(),
    ])
    .unwrap();

    let changed_file = root.join("changed.txt");
    fs::write(
        &changed_file,
        "events/rus_events.txt\ncommon/scripted_effects/black_monday_effects.txt\nhistory/states/64-Test.txt\n",
    )
    .unwrap();

    cmd_identify_work_packages(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--changed".to_string(),
        "events/ger_events.txt".to_string(),
        "--changed-file".to_string(),
        changed_file.to_string_lossy().to_string(),
        "--strict-names".to_string(),
        "--output".to_string(),
        output.to_string_lossy().to_string(),
    ])
    .unwrap();

    let json = read_utf8_lossy(&output).unwrap();
    assert!(json.contains("\"schema\": \"hoi4skill.changed_work_packages.v1\""));
    assert!(json.contains("\"strict_names\": true"));
    assert!(json.contains("\"changed_count\": 4"));
    assert!(json.contains("\"assigned_count\": 3"));
    assert!(json.contains("\"unassigned_count\": 1"));
    assert!(json.contains("\"ambiguous_count\": 0"));
    assert!(json.contains(
        "\"affected_packages\": [\"country_ger\", \"country_rus\", \"system_black_monday\"]"
    ));
    assert!(json.contains("\"path\": \"events/rus_events.txt\""));
    assert!(json.contains("\"id\": \"country_rus\""));
    assert!(json.contains("\"path\": \"events/ger_events.txt\""));
    assert!(json.contains("\"id\": \"country_ger\""));
    assert!(json.contains("\"path\": \"common/scripted_effects/black_monday_effects.txt\""));
    assert!(json.contains("\"id\": \"system_black_monday\""));
    assert!(json.contains("\"path\": \"history/states/64-Test.txt\""));
    assert!(json.contains("\"status\": \"unassigned\""));
    assert!(json.contains("check-work-package-boundary"));
}

#[test]
fn split_changed_work_packages_writes_per_package_changed_files() {
    let root = unique_temp_dir("split-changed-work-packages");
    let blueprint_path = root.join("blueprint.yml");
    let mod_root = root.join("mod");
    let output = root.join("split_changed.json");

    cmd_plan_large_mod(&[
        "--text".to_string(),
        "name: Test Grand Campaign\ncountries: RUS, GER\nregions: europe\nsystems: black monday"
            .to_string(),
        "--name".to_string(),
        "Test Grand Campaign".to_string(),
        "--acronym".to_string(),
        "TGC".to_string(),
        "--output".to_string(),
        blueprint_path.to_string_lossy().to_string(),
    ])
    .unwrap();

    cmd_init_large_mod(&[
        "--blueprint".to_string(),
        blueprint_path.to_string_lossy().to_string(),
        "--output".to_string(),
        mod_root.to_string_lossy().to_string(),
    ])
    .unwrap();

    fs::write(
        mod_root.join(".hoi4skill/changed_region_europe.txt"),
        "events/stale.txt\n",
    )
    .unwrap();

    let changed_file = root.join("changed.txt");
    fs::write(
        &changed_file,
        "events/rus_events.txt\ncommon/scripted_effects/black_monday_effects.txt\nhistory/states/64-Test.txt\n",
    )
    .unwrap();

    cmd_split_changed_work_packages(&[
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--changed".to_string(),
        "events/ger_events.txt".to_string(),
        "--changed-file".to_string(),
        changed_file.to_string_lossy().to_string(),
        "--strict-names".to_string(),
        "--output".to_string(),
        output.to_string_lossy().to_string(),
    ])
    .unwrap();

    let json = read_utf8_lossy(&output).unwrap();
    assert!(json.contains("\"schema\": \"hoi4skill.split_changed_work_packages.v1\""));
    assert!(json.contains("\"affected_package_count\": 3"));
    assert!(json.contains("\"unassigned_count\": 1"));
    assert!(json.contains("\"ambiguous_count\": 0"));
    assert!(json.contains("changed_country_rus.txt"));
    assert!(json.contains("changed_country_ger.txt"));
    assert!(json.contains("changed_system_black_monday.txt"));
    assert!(json.contains("check-work-package-boundary"));

    let rus_changed =
        read_utf8_lossy(&mod_root.join(".hoi4skill/changed_country_rus.txt")).unwrap();
    let ger_changed =
        read_utf8_lossy(&mod_root.join(".hoi4skill/changed_country_ger.txt")).unwrap();
    let system_changed =
        read_utf8_lossy(&mod_root.join(".hoi4skill/changed_system_black_monday.txt")).unwrap();
    let region_changed =
        read_utf8_lossy(&mod_root.join(".hoi4skill/changed_region_europe.txt")).unwrap();
    let unassigned = read_utf8_lossy(&mod_root.join(".hoi4skill/changed_unassigned.txt")).unwrap();
    let ambiguous = read_utf8_lossy(&mod_root.join(".hoi4skill/changed_ambiguous.txt")).unwrap();

    assert_eq!(rus_changed, "events/rus_events.txt\n");
    assert_eq!(ger_changed, "events/ger_events.txt\n");
    assert_eq!(
        system_changed,
        "common/scripted_effects/black_monday_effects.txt\n"
    );
    assert_eq!(region_changed, "");
    assert_eq!(unassigned, "history/states/64-Test.txt\n");
    assert_eq!(ambiguous, "");
}

