#[test]
fn game_index_collects_country_names_from_localisation() {
    let root = unique_temp_dir("game-index-country-localisation");
    fs::create_dir_all(root.join("common/country_tags")).unwrap();
    fs::create_dir_all(root.join("interface")).unwrap();
    fs::create_dir_all(root.join("localisation/simp_chinese")).unwrap();
    fs::write(
        root.join("common/country_tags/tst.txt"),
        "CHI = \"countries/China.txt\"\n",
    )
    .unwrap();
    fs::write(
        root.join("localisation/simp_chinese/countries_l_simp_chinese.yml"),
        "\u{feff}l_simp_chinese:\n CHI:0 \"中华民国\"\n CHI_DEF:0 \"中华民国\"\n CHI_ADJ:0 \"中华民国\"\n CPC:0 \"中共\"\n CPC_peoples_republic:0 \"中华人民共和国\"\n CPC_peoples_republic_DEF:0 \"中华人民共和国\"\n CPC_peoples_republic_ADJ:0 \"中国\"\n KMT_icon_sample:0 \"£GFX_kmt_party_icon §Y国民党§!\"\n",
    )
    .unwrap();
    fs::write(
        root.join("interface/icons.gfx"),
        r#"spriteType = { name = "GFX_kmt_party_icon" texturefile = "gfx/interface/kmt.dds" }"#,
    )
    .unwrap();

    let index = build_game_index_with_mod_paths(&root, &[]).unwrap();
    let json = game_index_json(&index);
    fs::remove_dir_all(&root).unwrap();

    let tags = index.country_name_tags.get("中华民国").unwrap();
    assert!(tags.contains("CHI"));
    assert_eq!(tags.len(), 1);
    let cosmetic_tags = index.country_name_tags.get("中华人民共和国").unwrap();
    assert!(cosmetic_tags.contains("CPC"));
    assert_eq!(cosmetic_tags.len(), 1);
    assert!(!index.country_name_tags.contains_key("中国"));
    let icons = index.localisation_icon_names.get("国民党").unwrap();
    assert!(icons.contains("GFX_kmt_party_icon"));
    assert_eq!(icons.len(), 1);
    assert!(json.contains("\"country_name_tags\": {"));
    assert!(json.contains("\"中华民国\": [\"CHI\"]"));
    assert!(json.contains("\"中华人民共和国\": [\"CPC\"]"));
    assert!(json.contains("\"localisation_icon_names\": {\"国民党\": [\"GFX_kmt_party_icon\"]}"));
}

#[test]
fn gfx_audit_reports_missing_textures_refs_orphans_and_unregistered_images() {
    let root = unique_temp_dir("gfx-audit");
    fs::create_dir_all(root.join("common/national_focus")).unwrap();
    fs::create_dir_all(root.join("interface")).unwrap();
    fs::create_dir_all(root.join("gfx/interface/goals")).unwrap();
    fs::write(root.join("gfx/interface/goals/used.dds"), "fake").unwrap();
    fs::write(root.join("gfx/interface/goals/unregistered.dds"), "fake").unwrap();
    fs::write(
        root.join("interface/tst.gfx"),
        r#"
spriteTypes = {
  spriteType = {
    name = "GFX_goal_used"
    texturefile = "gfx/interface/goals/used.dds"
  }
  spriteType = {
    name = "GFX_goal_missing_texture"
    texturefile = "gfx/interface/goals/missing.dds"
  }
  spriteType = {
    name = "GFX_goal_orphan"
    texturefile = "gfx/interface/goals/used.dds"
  }
  corneredTileSpriteType = {
    name = "GFX_goal_cornered"
    textureFile = "gfx/interface/goals/used.dds"
  }
}
"#,
    )
    .unwrap();
    fs::write(
        root.join("common/national_focus/tst.txt"),
        r#"
focus_tree = {
  id = tst_focus
  focus = {
    id = TST_used
    icon = GFX_goal_used
  }
  focus = {
    id = TST_missing
    icon = GFX_goal_missing_ref
  }
  focus = {
    id = TST_cornered
    icon = GFX_goal_cornered
  }
}
"#,
    )
    .unwrap();

    let output = root.join("gfx_audit.json");
    cmd_gfx_audit(&[
        root.to_string_lossy().to_string(),
        "--output".to_string(),
        output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let json = read_utf8_lossy(&output).unwrap();
    assert!(json.contains("\"schema\": \"hoi4skill.gfx_audit.v1\""));
    assert!(json.contains("\"missing_textures_count\": 1"));
    assert!(json.contains("\"id\": \"GFX_goal_missing_texture\""));
    assert!(json.contains("\"missing_sprites_count\": 1"));
    assert!(json.contains("\"id\": \"GFX_goal_missing_ref\""));
    assert!(json.contains("\"classification\": \"confirmed_missing\""));
    assert!(!json.contains("\"id\": \"GFX_goal_cornered\""));
    assert!(json.contains("\"orphan_sprites_count\": 2"));
    assert!(json.contains("\"id\": \"GFX_goal_orphan\""));
    assert!(json.contains("\"unregistered_images_count\": 1"));
    assert!(json.contains("gfx/interface/goals/unregistered.dds"));

    let changed_output = root.join("gfx_changed.json");
    cmd_gfx_audit(&[
        root.to_string_lossy().to_string(),
        "--changed-only".to_string(),
        "--changed".to_string(),
        "common/national_focus/tst.txt".to_string(),
        "--output".to_string(),
        changed_output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let changed_json = read_utf8_lossy(&changed_output).unwrap();
    assert!(changed_json.contains("\"missing_sprites_count\": 1"));
    assert!(changed_json.contains("\"missing_textures_count\": 0"));
    assert!(changed_json.contains("\"orphan_sprites_count\": 0"));

    fs::write(
        root.join("common/national_focus/tst.txt"),
        "focus_tree = { focus = { id = TST_new icon = GFX_goal_new_missing } }\n",
    )
    .unwrap();
    cmd_gfx_audit(&[
        root.to_string_lossy().to_string(),
        "--changed-only".to_string(),
        "--changed".to_string(),
        "common/national_focus/tst.txt".to_string(),
        "--output".to_string(),
        changed_output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let refreshed_json = read_utf8_lossy(&changed_output).unwrap();
    assert!(refreshed_json.contains("GFX_goal_new_missing"));
    assert!(!refreshed_json.contains("GFX_goal_missing_ref"));

    fs::remove_file(root.join("common/national_focus/tst.txt")).unwrap();
    cmd_gfx_audit(&[
        root.to_string_lossy().to_string(),
        "--output".to_string(),
        output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let deleted_json = read_utf8_lossy(&output).unwrap();
    assert!(!deleted_json.contains("GFX_goal_new_missing"));
}

#[test]
fn gui_layout_audit_reports_static_bounds_building_order_and_runtime_clipping() {
    let root = unique_temp_dir("gui-layout-audit");
    fs::create_dir_all(root.join("common/buildings")).unwrap();
    fs::create_dir_all(root.join("interface")).unwrap();
    fs::write(
        root.join("common/buildings/00_buildings.txt"),
        "buildings = { arms_factory = { shares_slots = no } industrial_complex = { shares_slots = yes } }\n",
    )
    .unwrap();
    fs::write(
        root.join("interface/countryconstructionsview.gui"),
        r#"guiTypes = {
  containerWindowType = {
    name = "building_construction_speeds"
    position = { x = 0 y = 0 }
    size = { width = 200 height = 100 }
    instantTextBoxType = { name = "arms_factory_speed" position = { x = 0 y = 0 } maxWidth = 50 maxHeight = 20 text = "speed" }
    instantTextBoxType = { name = "industrial_complex_speed" position = { x = 55 y = 0 } maxWidth = 50 maxHeight = 20 text = "speed" }
    buttonType = { name = "outside" position = { x = 180 y = 90 } size = { width = 40 height = 20 } }
  }
  containerWindowType = { name = "possible_constructions" position = { x = 0 y = 0 } size = { width = 250 height = 916 } }
}
"#,
    )
    .unwrap();
    let runtime_log = root.join("error.log");
    fs::write(
        &runtime_log,
        "[gui.cpp:1]: objects outside \"possible_constructions\" clipped\n",
    )
    .unwrap();
    let output = root.join("layout.json");

    cmd_gui_layout_audit(&[
        root.to_string_lossy().to_string(),
        "--runtime-log".to_string(),
        runtime_log.to_string_lossy().to_string(),
        "--output".to_string(),
        output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let json = read_utf8_lossy(&output).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(json.contains("\"schema\": \"hoi4skill.gui_layout_audit.v1\""));
    assert!(json.contains("static_child_out_of_bounds"));
    assert!(json.contains("building_order_fixed_overlay"));
    assert!(json.contains("runtime_object_clipped"));
    assert!(json.contains("\"classification\": \"confirmed_missing\""));
    assert!(json.contains("\"classification\": \"runtime_layout_required\""));
}

#[test]
fn logic_audit_reports_focus_graph_reference_issues() {
    let root = unique_temp_dir("logic-audit");
    fs::create_dir_all(root.join("common/national_focus")).unwrap();
    fs::create_dir_all(root.join("events")).unwrap();
    fs::write(
        root.join("common/national_focus/tst.txt"),
        r#"
focus_tree = {
  id = tst_focus
  country = { factor = 0 modifier = { add = 10 tag = TST } }
  focus = {
    id = TST_root
    x = 0
    y = 0
  }
  focus = {
    id = TST_child
    prerequisite = { focus = TST_missing }
    relative_position_id = TST_missing_position
    completion_reward = { country_event = { id = tst.missing } }
    x = 0
    y = 1
  }
  focus = {
    id = TST_left
    mutually_exclusive = { focus = TST_right }
    x = -1
    y = 0
  }
  focus = {
    id = TST_right
    x = 1
    y = 0
  }
}

focus_tree = {
  id = other_focus
  country = { factor = 0 modifier = { add = 10 tag = OTH } }
  focus = {
    id = OTH_root
    x = 0
    y = 0
  }
  focus = {
    id = OTH_cross
    prerequisite = { focus = TST_root }
    x = 0
    y = 1
  }
}
"#,
    )
    .unwrap();
    fs::write(
        root.join("events/tst_events.txt"),
        r#"
add_namespace = tst
country_event = {
  id = tst.1
  title = tst.1.t
  desc = tst.1.d
  is_triggered_only = yes
  option = { name = tst.1.a }
}
news_event = {
  id = tst.2
  title = tst.2.t
  desc = tst.2.d
  is_triggered_only = yes
  option = { name = tst.2.a }
}
"#,
    )
    .unwrap();

    let output = root.join("logic.json");
    cmd_logic_audit(&[
        root.to_string_lossy().to_string(),
        "--output".to_string(),
        output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let json = read_utf8_lossy(&output).unwrap();
    assert!(json.contains("\"schema\": \"hoi4skill.logic_audit.v1\""));
    assert!(json.contains("\"ok\": false"));
    assert!(json.contains("\"focus_total\": 6"));
    assert!(json.contains("\"focus_trees_total\": 2"));
    assert!(json.contains("\"broken_focus_refs_count\": 2"));
    assert!(json.contains("\"target\": \"TST_missing\""));
    assert!(json.contains("\"target\": \"TST_missing_position\""));
    assert!(json.contains("\"cross_tree_focus_refs_count\": 1"));
    assert!(json.contains("\"id\": \"OTH_cross\""));
    assert!(json.contains("\"asymmetric_mutual_exclusions_count\": 1"));
    assert!(json.contains("\"id\": \"TST_left\""));
    assert!(json.contains("\"unreachable_focuses_count\": 1"));
    assert!(json.contains("\"id\": \"TST_child\""));
    assert!(json.contains("\"event_total\": 2"));
    assert!(json.contains("\"event_refs_total\": 1"));
    assert!(json.contains("\"broken_event_refs_count\": 1"));
    assert!(json.contains("\"target\": \"tst.missing\""));
    assert!(json.contains("\"potential_orphan_events_count\": 2"));
    assert!(json.contains("\"id\": \"tst.1\""));

    let changed_output = root.join("logic_changed.json");
    cmd_logic_audit(&[
        root.to_string_lossy().to_string(),
        "--changed-only".to_string(),
        "--changed".to_string(),
        "common/national_focus/tst.txt".to_string(),
        "--output".to_string(),
        changed_output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let changed_json = read_utf8_lossy(&changed_output).unwrap();
    assert!(changed_json.contains("\"changed_files\": [\"common/national_focus/tst.txt\"]"));
    assert!(changed_json.contains("\"broken_focus_refs_count\": 2"));

    let missing_changed = cmd_logic_audit(&[
        root.to_string_lossy().to_string(),
        "--changed-only".to_string(),
    ]);
    assert!(missing_changed.is_err());
    assert!(missing_changed
        .unwrap_err()
        .contains("--changed-only requires"));
}

