fn write_zip_xml(
    zip: &mut zip::ZipWriter<fs::File>,
    options: zip::write::SimpleFileOptions,
    path: &str,
    xml: &str,
) {
    use std::io::Write;

    zip.start_file(path, options).unwrap();
    zip.write_all(xml.as_bytes()).unwrap();
}

fn write_minimal_docx(path: &Path, paragraphs: &[&str]) {
    let file = fs::File::create(path).unwrap();
    let mut zip = zip::ZipWriter::new(file);
    let options = zip::write::SimpleFileOptions::default();
    let body = paragraphs
        .iter()
        .map(|paragraph| {
            format!(
                r#"<w:p><w:r><w:t xml:space="preserve">{}</w:t></w:r></w:p>"#,
                xml_escape_text(paragraph)
            )
        })
        .collect::<Vec<_>>()
        .join("");
    write_zip_xml(
        &mut zip,
        options,
        "word/document.xml",
        &format!(
            r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>{body}</w:body></w:document>"#
        ),
    );
    zip.finish().unwrap();
}

fn write_minimal_docx_table(path: &Path, rows: &[&[&str]]) {
    let file = fs::File::create(path).unwrap();
    let mut zip = zip::ZipWriter::new(file);
    let options = zip::write::SimpleFileOptions::default();
    let table_rows = rows
        .iter()
        .map(|row| {
            let cells = row
                .iter()
                .map(|cell| {
                    format!(
                        r#"<w:tc><w:p><w:r><w:t xml:space="preserve">{}</w:t></w:r></w:p></w:tc>"#,
                        xml_escape_text(cell)
                    )
                })
                .collect::<Vec<_>>()
                .join("");
            format!("<w:tr>{cells}</w:tr>")
        })
        .collect::<Vec<_>>()
        .join("");
    write_zip_xml(
        &mut zip,
        options,
        "word/document.xml",
        &format!(
            r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body><w:tbl>{table_rows}</w:tbl></w:body></w:document>"#
        ),
    );
    zip.finish().unwrap();
}

fn xml_escape_text(text: &str) -> String {
    text.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
        .replace('\'', "&apos;")
}

fn write_fer_country_source(root: &Path) {
    fs::create_dir_all(root.join("common").join("country_tags")).unwrap();
    fs::create_dir_all(root.join("common").join("countries")).unwrap();
    fs::create_dir_all(root.join("localisation").join("simp_chinese")).unwrap();
    fs::write(
        root.join("common").join("country_tags").join("00_tags.txt"),
        "FER = \"countries/FER.txt\"\n",
    )
    .unwrap();
    fs::write(
        root.join("common").join("countries").join("FER.txt"),
        "graphical_culture = western_european_gfx\n",
    )
    .unwrap();
    let mut loc = vec![0xef, 0xbb, 0xbf];
    loc.extend_from_slice(
        "l_simp_chinese:\n FER:0 \"远东铁路共和国\"\n FER_DEF:0 \"远东铁路共和国\"\n FER_ADJ:0 \"远东\"\n".as_bytes(),
    );
    fs::write(
        root.join("localisation")
            .join("simp_chinese")
            .join("countries_l_simp_chinese.yml"),
        loc,
    )
    .unwrap();
}

fn write_country_knowledge_source(root: &Path, countries: &[(&str, &str, &str)]) {
    fs::create_dir_all(root.join("common").join("country_tags")).unwrap();
    fs::create_dir_all(root.join("common").join("countries")).unwrap();
    fs::create_dir_all(root.join("localisation").join("simp_chinese")).unwrap();
    fs::write(root.join("hoi4.exe"), "").unwrap();
    let mut tags = String::new();
    let mut loc = vec![0xef, 0xbb, 0xbf];
    loc.extend_from_slice(b"l_simp_chinese:\n");
    for (tag, file_name, name) in countries {
        tags.push_str(&format!("{tag} = \"countries/{file_name}\"\n"));
        fs::write(
            root.join("common").join("countries").join(file_name),
            "graphical_culture = western_european_gfx\n",
        )
        .unwrap();
        loc.extend_from_slice(format!(" {tag}:0 \"{name}\"\n").as_bytes());
    }
    fs::write(
        root.join("common")
            .join("country_tags")
            .join("00_countries.txt"),
        tags,
    )
    .unwrap();
    fs::write(
        root.join("localisation")
            .join("simp_chinese")
            .join("countries_l_simp_chinese.yml"),
        loc,
    )
    .unwrap();
}

