#[test]
fn prepare_edit_context_normalizes_tabular_inline_text_before_workflow_parse() {
    let root = unique_temp_dir("edit-context-inline-table-text");
    fs::create_dir_all(&root).unwrap();
    fs::write(
        root.join("descriptor.mod"),
        "name=\"Inline Table Context Test\"\nsupported_version=\"*\"\n",
    )
    .unwrap();
    let output = root.join("edit_context.md");
    let text = "包名;类型;名称;说明;事件ID;选项一;效果一;动态修正;本地化ID;本地化文本\n\
country_chi;事件;开局党政会议;各派抵达首都讨论路线;opening_congress;继续会议;政治点+25;;\n\
country_chi;动态修正;中国制造;建造速度+10%;;;;中国制造;;\n\
country_chi;本地化;;;;;;;chi_table_tt;【红色：中华民国】召开会议\n";

    cmd_prepare_edit_context(&[
        "--text".to_string(),
        text.to_string(),
        "--mod-root".to_string(),
        root.to_string_lossy().to_string(),
        "--tag".to_string(),
        "CHI".to_string(),
        "--prefix".to_string(),
        "chi_ctx".to_string(),
        "--output".to_string(),
        output.to_string_lossy().to_string(),
    ])
    .unwrap();

    let context = read_utf8_lossy(&output).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(context.contains("事件：开局党政会议"));
    assert!(context.contains("事件键：opening_congress"));
    assert!(context.contains("选项A：继续会议"));
    assert!(context.contains("效果A：政治点+25"));
    assert!(context.contains("本地化：chi_table_tt = 【红色：中华民国】召开会议"));
    assert!(!context.contains("\"动态修正\": \"中国制造"));
    assert!(!context.contains("\"本地化\": \"chi_table_tt"));
    assert!(
        context.contains("request parsed as focus_layout=false, feature_cards=0, event_cards=1")
    );
    assert!(context.contains(
        "request auxiliary inputs parsed as dynamic_modifier_intents=1, localisation_entries=1, localisation_token_issues=0"
    ));
    assert!(context.contains("\"dynamic_modifier_intents\": 1"));
    assert!(context.contains("\"localisation_entries\": 1"));
    assert!(context.contains("\"localisation_token_issues\": 0"));
    assert!(context.contains("\"中国制造 建造速度+10%\""));
    assert!(context.contains("plan-dynamic-modifier-change"));
    assert!(!context.contains("plan-history-edit"));
}

#[test]
fn edit_context_history_unknown_facts_do_not_block_event_prose_capital_word() {
    let index = GameIndex::default();
    let prose = "事件：开局党政会议\n描述：各派代表抵达首都讨论路线。\n选项A：继续\n";
    let facts = edit_context_unknown_facts(prose, "{}", &[], Some(&index));
    assert!(!facts
        .iter()
        .any(|fact| fact.contains("history/state/province/capital")));

    let history_request = "州效果：整顿首都工业\n州ID：64\n建筑：1个军工厂\n";
    let facts = edit_context_unknown_facts(history_request, "{}", &[], Some(&index));
    assert!(facts
        .iter()
        .any(|fact| fact.contains("history/state/province/capital")));
}

#[test]
fn workflow_dynamic_modifier_intents_collect_protocol_continuations() {
    let text = "动态修正：中国制造 建造速度+10%\n\
custom_effect_tooltip = CHI_made_in_china_tt\n\
set_temp_variable = { temp_CHI_made_in_china = 0.10 }\n\
change_CHI_made_in_china4 = yes\n\
事件：开局党政会议\n";

    let intents = workflow_dynamic_modifier_intents(text);

    assert_eq!(intents.len(), 1);
    assert!(intents[0].contains("中国制造 建造速度+10%"));
    assert!(intents[0].contains("custom_effect_tooltip = CHI_made_in_china_tt"));
    assert!(intents[0].contains("set_temp_variable = { temp_CHI_made_in_china = 0.10 }"));
    assert!(intents[0].contains("change_CHI_made_in_china4 = yes"));
    assert!(!intents[0].contains("事件：开局党政会议"));
}

