#[test]
fn ai_repair_bundle_runs_validate_and_builds_prompt_artifacts() {
    let root = unique_temp_dir("ai-repair-bundle");
    let game = unique_temp_dir("ai-repair-bundle-game");
    fs::create_dir_all(root.join("events")).unwrap();
    fs::create_dir_all(root.join("localisation").join("simp_chinese")).unwrap();
    fs::create_dir_all(game.join("documentation")).unwrap();
    fs::create_dir_all(game.join("events")).unwrap();
    fs::create_dir_all(game.join("events")).unwrap();
    fs::write(
        root.join("descriptor.mod"),
        "name=\"Repair Bundle Test\"\nsupported_version=\"*\"\n",
    )
    .unwrap();
    fs::write(
        root.join("events").join("bad_events.txt"),
        "add_namespace = tst\ncountry_event = {\n id = tst.1\n title = tst.1.t\n desc = tst.1.d\n is_triggered_only = yes\n option = {\n  name = tst.1.a\n  add_politicalpower = 25\n }\n}\n",
    )
    .unwrap();
    fs::write(
        root.join("localisation")
            .join("simp_chinese")
            .join("tst_l_simp_chinese.yml"),
        "l_simp_chinese:\n tst.1.t:0 \"测试事件\"\n tst.1.d:0 \"测试描述\"\n tst.1.a:0 \"确认\"\n",
    )
    .unwrap();
    fs::write(
        game.join("documentation").join("effects_documentation.md"),
        "## Effects\n\n## add_political_power\n\n## add_stability\n",
    )
    .unwrap();
    let edit_context = root.join("edit_context.md");
    fs::write(
        &edit_context,
        "# HOI4 Edit Context Pack\n\n## Write Gate\n\n- status: `BLOCKED`\n\n## AI Repair Insurance\n\n````json\n{\"schema\":\"hoi4skill.edit_context_repair_insurance.v1\",\"dry_run_issue_count\":1}\n````\n",
    )
    .unwrap();
    let output_dir = root.join(".hoi4skill").join("repair_bundle_test");
    let manifest = root.join("repair_bundle.json");

    cmd_ai_repair_bundle(&[
        root.to_string_lossy().to_string(),
        "--game-root".to_string(),
        game.to_string_lossy().to_string(),
        "--edit-context".to_string(),
        edit_context.to_string_lossy().to_string(),
        "--output-dir".to_string(),
        output_dir.to_string_lossy().to_string(),
        "--output".to_string(),
        manifest.to_string_lossy().to_string(),
    ])
    .unwrap();

    let manifest_json = read_utf8_lossy(&manifest).unwrap();
    let validation_json = read_utf8_lossy(&output_dir.join("validation.json")).unwrap();
    let repair_context = read_utf8_lossy(&output_dir.join("ai_repair_context.json")).unwrap();
    let failed_output = read_utf8_lossy(&output_dir.join("failed_output.md")).unwrap();
    let repair_prompt = read_utf8_lossy(&output_dir.join("repair_prompt.md")).unwrap();
    fs::remove_dir_all(&root).unwrap();
    fs::remove_dir_all(&game).unwrap();

    assert!(manifest_json.contains("\"schema\": \"hoi4skill.ai_repair_bundle.v1\""));
    assert!(manifest_json.contains("\"status\": \"repair_prompt_ready\""));
    assert!(manifest_json.contains("\"validation_ok\": false"));
    assert!(manifest_json.contains("\"name\": \"ai_repair_prompt\""));
    assert!(validation_json.contains("\"schema\": \"hoi4skill.validation_report.v1\""));
    assert!(validation_json.contains("add_politicalpower"));
    assert!(repair_context.contains("\"schema\": \"hoi4skill.validation_repair_context.v1\""));
    assert!(repair_context.contains("\"symbol\": \"add_politicalpower\""));
    assert!(failed_output.contains("schema: `hoi4skill.failed_output_pack.v1`"));
    assert!(failed_output.contains("add_politicalpower"));
    assert!(repair_prompt.contains("schema: `hoi4skill.ai_repair_prompt.v1`"));
    assert!(repair_prompt.contains("hoi4skill.failed_output_pack.v1"));
    assert!(repair_prompt.contains("hoi4skill.edit_context_repair_insurance.v1"));
}

