#[test]
fn strict_parse_event_cards_rejects_event_like_text_without_event_header() {
    let root = unique_temp_dir("strict-parse-event-like-without-header");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("events.txt");
    let output = root.join("events.json");
    fs::write(
        &input,
        "标题：陈独秀归来\n目标：CPC\n命名空间：cpc_chain\n选项A：召开扩大会议\n后续事件A：cpc_chain.17",
    )
    .unwrap();

    let err = cmd_parse_event_cards(&[
        "--input".to_string(),
        input.display().to_string(),
        "--tag".to_string(),
        "CPC".to_string(),
        "--prefix".to_string(),
        "cpc_chain".to_string(),
        "--strict-code-index".to_string(),
        "--output".to_string(),
        output.display().to_string(),
    ])
    .unwrap_err();
    let output_exists = output.exists();
    fs::remove_dir_all(&root).unwrap();

    assert!(err.contains("blocked malformed event cards"));
    assert!(err.contains("no event cards were parsed"));
    assert!(err.contains("事件：<标题>"));
    assert!(!output_exists);
}

