#[test]
fn read_text_document_reads_docx_paragraphs() {
    let root = unique_temp_dir("docx-text-document");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("events.docx");
    write_minimal_docx(
        &input,
        &[
            "事件：整风会议召开",
            "选项A：发布消息",
            "后续事件A：整风会议公报",
        ],
    );

    let text = read_text_document(&input).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(text.contains("事件：整风会议召开\n选项A：发布消息\n后续事件A：整风会议公报"));
}

