#[test]
fn parse_event_cards_command_uses_mod_root_existing_event_chain_ids() {
    let root = unique_temp_dir("parse-event-cards-mod-root-chain");
    let game = unique_temp_dir("parse-event-cards-mod-root-chain-game");
    fs::create_dir_all(root.join("events")).unwrap();
    fs::create_dir_all(game.join("common").join("country_tags")).unwrap();
    fs::create_dir_all(game.join("documentation")).unwrap();
    fs::write(
        root.join("events").join("cpc_existing_events.txt"),
        "add_namespace = cpc_chain\n\nnews_event = { id = cpc_chain.17 title = cpc_chain.17.t desc = cpc_chain.17.d option = { name = cpc_chain.17.a } }\n",
    )
    .unwrap();
    fs::write(
        game.join("common")
            .join("country_tags")
            .join("00_countries.txt"),
        "CPC = \"countries/CPC.txt\"\n",
    )
    .unwrap();
    fs::write(
        game.join("documentation").join("effects_documentation.md"),
        "## Effects\n\n## news_event\n",
    )
    .unwrap();
    let input = root.join("events.txt");
    let output = root.join("events.json");
    fs::write(
        &input,
        "事件：整风会议召开\n目标：CPC\n命名空间：cpc_chain\n选项A：发布旧案\n后续事件A：cpc_chain.17",
    )
    .unwrap();

    cmd_parse_event_cards(&[
        "--input".to_string(),
        input.display().to_string(),
        "--tag".to_string(),
        "CPC".to_string(),
        "--prefix".to_string(),
        "cpc_chain".to_string(),
        "--mod-root".to_string(),
        root.display().to_string(),
        "--game-root".to_string(),
        game.display().to_string(),
        "--strict-code-index".to_string(),
        "--output".to_string(),
        output.display().to_string(),
    ])
    .unwrap();

    let json = fs::read_to_string(&output).unwrap();
    fs::remove_dir_all(&root).unwrap();
    fs::remove_dir_all(&game).unwrap();

    assert!(json.contains("\"event_id\": \"cpc_chain.18\""));
    assert!(json.contains("\"target_event_id\": \"cpc_chain.17\""));
    assert!(json.contains("\"event_type\": \"news_event\""));
    assert!(json.contains("news_event = { id = cpc_chain.17 }"));
    assert!(json.contains("\"status\": \"resolved\""));
    assert!(!json.contains("<event id for cpc_chain.17>"));
}

#[test]
fn event_cards_json_reports_unresolved_and_ambiguous_chain_edges() {
    let unresolved = parse_event_cards_json(
        "事件：整风会议召开\n命名空间：cpc_chain\n选项A：继续整顿\n隐藏效果A：触发事件 不存在的后续事件",
        "CPC",
        "cpc_chain",
    );
    let ambiguous = parse_event_cards_json(
        "事件：整风会议召开\n命名空间：cpc_chain\n选项A：继续整顿\n隐藏效果A：触发事件 重复标题\n\n事件：重复标题\n命名空间：cpc_chain\n选项A：继续\n效果A：政治点+5\n\n事件：重复标题\n命名空间：cpc_chain\n选项A：继续\n效果A：政治点+5",
        "CPC",
        "cpc_chain",
    );

    assert!(unresolved.contains("\"event_chain\": ["));
    assert!(unresolved.contains("\"target\": \"不存在的后续事件\""));
    assert!(unresolved.contains("\"target_event_id\": null"));
    assert!(unresolved.contains("\"status\": \"unresolved\""));
    assert!(unresolved.contains("\"event_chain_edge_count\": 1"));
    assert!(unresolved.contains("\"event_chain_resolved_edge_count\": 0"));
    assert!(unresolved.contains("\"event_chain_unresolved_edge_count\": 1"));
    assert!(unresolved.contains("\"event_chain_ambiguous_edge_count\": 0"));
    assert!(unresolved.contains("\"event_chain_review_count\":"));
    assert!(unresolved.contains("\"event_chain_blocking_review_count\": 1"));
    assert!(unresolved.contains("\"kind\": \"unresolved_chain_target\""));
    assert!(unresolved.contains("\"severity\": \"error\""));
    assert!(unresolved.contains("\"target\": \"不存在的后续事件\""));
    assert!(unresolved.contains("add the missing event card"));
    assert!(unresolved.contains("event title was not found in this batch"));
    assert!(ambiguous.contains("\"target\": \"重复标题\""));
    assert!(ambiguous.contains("\"duplicate_chain_titles\": [\"重复标题\"]"));
    assert!(ambiguous.contains("\"status\": \"ambiguous\""));
    assert!(ambiguous.contains("\"event_chain_edge_count\": 1"));
    assert!(ambiguous.contains("\"event_chain_resolved_edge_count\": 0"));
    assert!(ambiguous.contains("\"event_chain_unresolved_edge_count\": 0"));
    assert!(ambiguous.contains("\"event_chain_ambiguous_edge_count\": 1"));
    assert!(ambiguous.contains("\"event_chain_review_count\":"));
    assert!(ambiguous.contains("\"event_chain_blocking_review_count\": 1"));
    assert!(ambiguous.contains("\"kind\": \"ambiguous_chain_target\""));
    assert!(ambiguous.contains("Add unique `事件键` values"));
    assert!(ambiguous.contains("add unique event keys"));
}

