#[test]
fn event_cards_reports_event_chain_entry_terminal_and_isolated_nodes() {
    let json = parse_event_cards_json(
        "事件：整风会议召开\n事件键：opening\n命名空间：cpc_chain\n选项A：继续整顿\n后续事件A：debate\n\n事件：路线辩论\n事件键：debate\n命名空间：cpc_chain\n选项A：提交表决\n后续事件A：resolution\n\n事件：最终决议\n事件键：resolution\n命名空间：cpc_chain\n选项A：通过\n效果A：政治点+25\n\n事件：地方来信\n事件键：local_letter\n命名空间：cpc_chain\n选项A：存档",
        "CPC",
        "cpc_chain",
    );

    assert!(json.contains("\"event_chain_entry_count\": 2"));
    assert!(json.contains("\"event_chain_entry_events\": [\"cpc_chain.1\", \"cpc_chain.4\"]"));
    assert!(json.contains("\"event_chain_terminal_count\": 2"));
    assert!(json.contains("\"event_chain_terminal_events\": [\"cpc_chain.3\", \"cpc_chain.4\"]"));
    assert!(json.contains("\"event_chain_isolated_count\": 1"));
    assert!(json.contains("\"event_chain_isolated_events\": [\"cpc_chain.4\"]"));
    assert!(json.contains("\"event_chain_layer_count\": 3"));
    assert!(json.contains(
        "\"event_chain_layers\": [[\"cpc_chain.1\", \"cpc_chain.4\"], [\"cpc_chain.2\"], [\"cpc_chain.3\"]]"
    ));
    assert!(json.contains("\"event_chain_unlayered_count\": 0"));
    assert!(json.contains("\"event_chain_unlayered_events\": []"));
    assert!(json.contains("\"event_chain_review_count\": 1"));
    assert!(json.contains("\"kind\": \"isolated_event\""));
    assert!(json.contains("\"source_event_id\": \"cpc_chain.4\""));
    assert!(json.contains("intentionally standalone"));
}

