#[test]
fn author_placeholder_plan_questions_unknown_icon_without_guessing() {
    let root = unique_temp_dir("author-placeholder-plan-unknown-icon");
    fs::create_dir_all(root.join("localisation").join("simp_chinese")).unwrap();
    fs::write(
        root.join("localisation")
            .join("simp_chinese")
            .join("tags_l_simp_chinese.yml"),
        "l_simp_chinese:\n CHI:0 \"中华民国\"\n",
    )
    .unwrap();
    let output = root.join("placeholder_plan.json");

    let err = cmd_author_placeholder_plan(&[
        "--text".to_string(),
        "【国民党党徽】【中华民国旗帜】中华民国国民政府宣布训政。".to_string(),
        "--game-root".to_string(),
        root.to_string_lossy().to_string(),
        "--output".to_string(),
        output.to_string_lossy().to_string(),
    ])
    .unwrap_err();

    let json = read_utf8_lossy(&output).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(err.contains("author placeholder plan blocked"));
    assert!(json.contains("\"ok\": false"));
    assert!(json.contains("\"status\": \"questions_required\""));
    assert!(json.contains("\"placeholder\": \"【国民党党徽】"));
    assert!(json.contains("\"asset_question_count\": 1"));
    assert!(json.contains("\"country_question_count\": 0"));
    assert!(json.contains("\"asset_questions\""));
    assert!(json.contains("这个概念是否已有图标"));
    assert!(json.contains("请提供 GFX sprite 名"));
    assert!(json.contains("\"replacement\": \"[CHI.GetFlag]\""));
    assert!(json.contains("\"compiled_text\": null"));
    assert!(!json.contains("£GFX_kmt_party_icon"));
}

