#[test]
fn apply_event_cards_writes_resolved_event_chain_calls() {
    let root = unique_temp_dir("apply-event-cards-chain");
    fs::create_dir_all(&root).unwrap();
    let cards = parse_cards(
        "事件：整风会议召开\n目标：CPC\n命名空间：cpc_chain\n标题：整风会议召开\n描述：会场里的争论开始转向组织纪律。\n选项A：继续整顿\n隐藏效果A：3天后触发事件 批评与自我批评\n\n事件：批评与自我批评\n目标：CPC\n命名空间：cpc_chain\n标题：批评与自我批评\n描述：代表们逐一发言，要求把争论变成制度。\n选项A：通过决议\n效果A：政治点+25",
        &["事件"],
    );

    let changed = apply_event_cards_to_mod(&root, &cards, "CPC", "cpc_chain").unwrap();

    let events = fs::read_to_string(root.join("events").join("cpc_chain_events.txt")).unwrap();
    let loc = String::from_utf8_lossy(&fs::read(target_localisation_path(&root, "CPC")).unwrap())
        .to_string();
    fs::remove_dir_all(&root).unwrap();

    assert_eq!(changed.len(), 2);
    assert!(events.contains("id = cpc_chain.1"));
    assert!(events.contains("\tid = cpc_chain.2\n"));
    assert!(events.contains("hidden_effect = {"));
    assert!(events.contains("country_event = { id = cpc_chain.2 days = 3 }"));
    assert!(!events.contains("<event id for"));
    assert!(loc.contains("cpc_chain.2.t:0 \"批评与自我批评\""));
}

