#[test]
fn apply_event_cards_rejects_duplicate_event_keys_before_write() {
    let root = unique_temp_dir("apply-event-cards-duplicate-event-key");
    fs::create_dir_all(&root).unwrap();
    let input = root.join("events.txt");
    fs::write(
        &input,
        "事件：整风会议召开\n事件键：rectification_opening\n命名空间：cpc_chain\n选项A：继续\n\n事件：整风会议的新阶段\n事件键：rectification_opening\n命名空间：cpc_chain\n选项A：继续",
    )
    .unwrap();

    let err = cmd_apply_event_cards(&[
        "--input".to_string(),
        input.display().to_string(),
        "--mod-root".to_string(),
        root.display().to_string(),
        "--tag".to_string(),
        "CPC".to_string(),
        "--prefix".to_string(),
        "cpc_chain".to_string(),
    ])
    .unwrap_err();
    let events_exists = root.join("events").exists();
    fs::remove_dir_all(&root).unwrap();

    assert!(err.contains("blocked malformed event cards"));
    assert!(err.contains("duplicate event key `rectification_opening`"));
    assert!(!events_exists);
}

