    apply_event_cards_to_mod_with_index(&root, &cards, "CPC", "cpc_chain", Some(&index)).unwrap();

    let events = fs::read_to_string(events_dir.join("cpc_existing_events.txt")).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(events.contains("id = cpc_chain.17"));
    assert!(events.contains("id = cpc_chain.18"));
