#[test]
fn plan_dynamic_modifier_change_execute_generates_dynamic_modifier_protocol() {
    let root = unique_temp_dir("plan-dynamic-modifier-change-execute");
    let game_root = root.join("game");
    let mod_root = root.join("mod");
    fs::create_dir_all(game_root.join("documentation")).unwrap();
    fs::create_dir_all(mod_root.join("common")).unwrap();
    fs::write(
        mod_root.join("descriptor.mod"),
        "name=\"Generated Dynamic\"\n",
    )
    .unwrap();
    fs::write(
        game_root.join("documentation").join("effects_documentation.md"),
        "## Effects\n\n## custom_effect_tooltip\n\n## set_temp_variable\n\n## add_to_variable\n\n## add_dynamic_modifier\n",
    )
    .unwrap();
    fs::write(
        game_root
            .join("documentation")
            .join("modifiers_documentation.md"),
        "## Modifiers\n\n## production_speed_buildings_factor\n\n## production_factory_max_efficiency_factor\n",
    )
    .unwrap();
    let output = root.join("dynamic_plan.json");

    cmd_plan_dynamic_modifier_change(&[
        "--text".to_string(),
        "tgc_rus_made_in_country 的效果 建造速度 +10%\n生产效率上限 +0.05".to_string(),
        "--mod-root".to_string(),
        mod_root.to_string_lossy().to_string(),
        "--tag".to_string(),
        "RUS".to_string(),
        "--prefix".to_string(),
        "tgc_rus".to_string(),
        "--game-root".to_string(),
        game_root.to_string_lossy().to_string(),
        "--execute".to_string(),
        "--final-check".to_string(),
        "--output".to_string(),
        output.to_string_lossy().to_string(),
    ])
    .unwrap();

    let json = read_utf8_lossy(&output).unwrap();
    let dynamic = read_utf8_lossy(
        &mod_root
            .join("common")
            .join("dynamic_modifiers")
            .join("tgc_rus_dynamic_modifiers.txt"),
    )
    .unwrap();
    let scripted = read_utf8_lossy(
        &mod_root
            .join("common")
            .join("scripted_effects")
            .join("tgc_rus_dynamic_modifier_effects.txt"),
    )
    .unwrap();
    let loc = read_utf8_lossy(&target_localisation_path(&mod_root, "RUS")).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(json.contains("\"executed\": true"));
    assert!(json.contains("\"can_apply\": true"));
    assert!(json.contains("tgc_rus_made_in_country"));
    assert!(json.contains("change_tgc_rus_made_in_country_build_speed"));
    assert!(dynamic.contains("tgc_rus_made_in_country = {"));
    assert!(
        dynamic.contains("production_speed_buildings_factor = tgc_rus_made_in_country_build_speed")
    );
    assert!(dynamic.contains(
        "production_factory_max_efficiency_factor = tgc_rus_made_in_country_max_efficiency"
    ));
    assert!(scripted.contains(
        "add_to_variable = { tgc_rus_made_in_country_build_speed = temp_tgc_rus_made_in_country }"
    ));
    assert!(scripted.contains("add_dynamic_modifier = { modifier = tgc_rus_made_in_country }"));
    assert!(loc.contains("tgc_rus_made_in_country"));
    assert!(loc.contains("建造速度"));
    assert!(loc.contains("生产效率上限"));
    assert!(!dynamic.contains("ideas ="));
    assert!(!scripted.contains("add_ideas"));
}

