#[test]
fn apply_intent_patch_plan_writes_generated_spirit_and_reports_effect() {
    let root = unique_temp_dir("apply-intent-patch-plan");
    let game_root = root.join("game");
    let mod_root = root.join("mod");
    fs::create_dir_all(game_root.join("documentation")).unwrap();
    fs::create_dir_all(game_root.join("interface")).unwrap();
    fs::create_dir_all(&mod_root).unwrap();
    fs::write(
        mod_root.join("descriptor.mod"),
        "name=\"Apply Intent Test\"\nsupported_version=\"1.*\"\n",
    )
    .unwrap();
    fs::write(
        game_root
            .join("documentation")
            .join("effects_documentation.md"),
        "## Effects\n\n## add_political_power\n\n## add_ideas\n",
    )
    .unwrap();
    fs::write(
        game_root
            .join("documentation")
            .join("modifiers_documentation.md"),
        "## Modifiers\n\n## stability_factor\n",
    )
    .unwrap();
    fs::write(
        game_root.join("interface").join("ideas.gfx"),
        r#"spriteType = { name = "GFX_idea_generic_production_bonus" texturefile = "gfx/interface/ideas/generic.dds" }"#,
    )
    .unwrap();
    let output = root.join("applied.json");

    cmd_apply_intent_patch_plan(&[
        "--text".to_string(),
        "中国国策：没收资本家\n效果：\n增加民族精神：\n资本家的反抗：\n稳定度 -10%".to_string(),
        "--kind".to_string(),
        "auto".to_string(),
        "--mod-root".to_string(),
        mod_root.display().to_string(),
        "--prefix".to_string(),
        "chi_reform".to_string(),
        "--tag".to_string(),
        "CHI".to_string(),
        "--game-root".to_string(),
        game_root.display().to_string(),
        "--final-check".to_string(),
        "--output".to_string(),
        output.display().to_string(),
    ])
    .unwrap();

    let report = read_utf8_lossy(&output).unwrap();
    let ideas = read_utf8_lossy(
        &mod_root
            .join("common")
            .join("ideas")
            .join("chi_reform_ideas.txt"),
    )
    .unwrap();
    let loc = read_utf8_lossy(&target_localisation_path(&mod_root, "CHI")).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(report.contains("\"schema\": \"hoi4skill.intent_patch_apply.v1\""));
    assert!(report.contains("\"effect_snippets\": [\"add_ideas = chi_reform_spirit_"));
    assert!(report.contains("\"changed_files\""));
    assert!(report.contains("\"patch_plan\""));
    assert!(ideas.contains("chi_reform_spirit_b24ce64a_idea"));
    assert!(ideas.contains("stability_factor = -0.1"));
    assert!(loc.contains("chi_reform_spirit_b24ce64a_idea:0 \"资本家的反抗\""));
    assert!(loc.contains("chi_reform_spirit_b24ce64a_idea_desc:0 \"\""));
}

