#[test]
fn author_intent_plan_routes_dynamic_modifier_without_idea_fallback() {
    let root = unique_temp_dir("author-intent-plan-dynamic-modifier");
    fs::create_dir_all(root.join("common").join("dynamic_modifiers")).unwrap();
    fs::create_dir_all(root.join("common").join("scripted_effects")).unwrap();
    fs::create_dir_all(root.join("documentation")).unwrap();
    fs::create_dir_all(root.join("localisation").join("simp_chinese")).unwrap();
    fs::write(
        root.join("common")
            .join("dynamic_modifiers")
            .join("chi_dynamic.txt"),
        "CHI_made_in_china = {\n icon = GFX_idea_factory\n production_speed_buildings_factor = CHI_made_in_china7\n}\n",
    )
    .unwrap();
    fs::write(
        root.join("common")
            .join("scripted_effects")
            .join("chi_scripted_effects.txt"),
        "change_CHI_made_in_china7 = { add_to_variable = { CHI_made_in_china7 = temp_CHI_made_in_china } custom_effect_tooltip = change_CHI_made_in_china7_tt }\n",
    )
    .unwrap();
    fs::write(
        root.join("documentation").join("effects_documentation.md"),
        "## Effects\n\n## custom_effect_tooltip\n\n## set_temp_variable\n",
    )
    .unwrap();
    fs::write(
        root.join("documentation")
            .join("modifiers_documentation.md"),
        "## Modifiers\n\n## production_speed_buildings_factor\n",
    )
    .unwrap();
    fs::write(
        root.join("localisation")
            .join("simp_chinese")
            .join("chi_l_simp_chinese.yml"),
        "l_simp_chinese:\n CHI_made_in_china:0 \"中国制造\"\n CHI_made_in_china_tt:0 \"§H中国制造§!追加效果：\\n\"\n change_CHI_made_in_china7_tt:0 \"建造速度：[?temp_CHI_made_in_china|+%]\\n\"\n",
    )
    .unwrap();
    let output = root.join("author_plan.json");

    cmd_author_intent_plan(&[
        "--text".to_string(),
        "中国制造 的效果 建造速度+10%".to_string(),
        "--game-root".to_string(),
        root.display().to_string(),
        "--strict-code-index".to_string(),
        "--output".to_string(),
        output.display().to_string(),
    ])
    .unwrap();

    let json = read_utf8_lossy(&output).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(json.contains("\"primary_writer\": \"plan-dynamic-modifier-change\""));
    assert!(json.contains("\"systems\": [\"dynamic_modifier\"]"));
    assert!(json.contains("\"effect_strategies\": [\"dynamic_modifier_scripted_effect_protocol\"]"));
    assert!(json.contains("custom_effect_tooltip = CHI_made_in_china_tt"));
    assert!(json.contains("change_CHI_made_in_china7 = yes"));
    assert!(json.contains("hoi4skill plan-dynamic-modifier-change --input <intent.txt>"));
    assert!(json.contains("Dynamic modifiers must use indexed custom_effect_tooltip"));
    assert!(!json.contains("add_ideas ="));
}

