#[test]
fn author_intent_workflow_writes_changed_files_and_runs_changed_validation() {
    let root = unique_temp_dir("author-intent-workflow-focus-spirit");
    let blueprint_path = root.join("blueprint.yml");
    let game_root = root.join("game");
    let mod_root = root.join("mod");
    let output = root.join("workflow.json");
    fs::create_dir_all(game_root.join("documentation")).unwrap();
    fs::create_dir_all(game_root.join("interface")).unwrap();
    fs::create_dir_all(game_root.join("common").join("country_tags")).unwrap();
    fs::write(
        game_root
            .join("common")
            .join("country_tags")
            .join("00_countries.txt"),
        "CHI = \"countries/China.txt\"\n",
    )
    .unwrap();
    fs::write(
        game_root
            .join("documentation")
            .join("effects_documentation.md"),
        "## Effects\n\n## add_ideas\n",
    )
    .unwrap();
    fs::write(
        game_root
            .join("documentation")
            .join("modifiers_documentation.md"),
        "## Modifiers\n\n## stability_factor\n",
    )
    .unwrap();
    fs::write(
        game_root.join("interface").join("goals.gfx"),
        r#"spriteType = { name = "GFX_goal_confiscate_capitalists" texturefile = "gfx/interface/goals/confiscate.dds" }"#,
    )
    .unwrap();
    fs::write(
        game_root.join("interface").join("ideas.gfx"),
        r#"spriteType = { name = "GFX_idea_generic_production_bonus" texturefile = "gfx/interface/ideas/generic.dds" }"#,
    )
    .unwrap();
    cmd_plan_large_mod(&[
        "--text".to_string(),
        "name: Author Workflow Test\ncountries: CHI\nsystems: focus, national spirit, localisation"
            .to_string(),
        "--name".to_string(),
        "Author Workflow Test".to_string(),
        "--acronym".to_string(),
        "AWT".to_string(),
        "--output".to_string(),
        blueprint_path.to_string_lossy().to_string(),
    ])
    .unwrap();
    cmd_init_large_mod(&[
        "--blueprint".to_string(),
        blueprint_path.to_string_lossy().to_string(),
        "--output".to_string(),
        mod_root.to_string_lossy().to_string(),
    ])
    .unwrap();

    cmd_author_intent_workflow(&[
        "--text".to_string(),
        "中国国策：没收资本家\n效果：\n增加民族精神：\n资本家的反抗：\n稳定度 -10%".to_string(),
        "--mod-root".to_string(),
        mod_root.display().to_string(),
        "--tag".to_string(),
        "CHI".to_string(),
        "--prefix".to_string(),
        "chi_reform".to_string(),
        "--hoi4-path".to_string(),
        game_root.display().to_string(),
        "--skip-audits".to_string(),
        "--output".to_string(),
        output.display().to_string(),
    ])
    .unwrap();

    let report = read_utf8_lossy(&output).unwrap();
    let changed = read_utf8_lossy(
        &mod_root
            .join(".hoi4skill")
            .join("author_intent_workflow_changed.txt"),
    )
    .unwrap();
    let author =
        read_utf8_lossy(&mod_root.join(".hoi4skill/author_intent_workflow_author.json")).unwrap();
    let evidence =
        read_utf8_lossy(&mod_root.join(".hoi4skill/author_intent_workflow_evidence.json")).unwrap();
    let validation = read_utf8_lossy(&mod_root.join(".hoi4skill/validation.json")).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(report.contains("\"schema\": \"hoi4skill.author_intent_workflow.v1\""));
    assert!(report.contains("\"ok\": true"));
    assert!(report.contains("\"strict_validation_ok\": true"));
    assert!(report.contains("\"supported_input_modes\""));
    assert!(report.contains("docx_word"));
    assert!(report.contains("xlsx_excel"));
    assert!(report.contains("\"delivery_artifacts\""));
    assert!(report.contains("\"name\": \"changed_list\""));
    assert!(changed.contains("common/national_focus/chi_reform_CHI_focus.txt"));
    assert!(changed.contains("common/ideas/chi_reform_ideas.txt"));
    assert!(changed.contains("localisation/simp_chinese/CHI_l_simp_chinese.yml"));
    assert!(author.contains("\"schema\": \"hoi4skill.focus_intent_apply.v1\""));
    assert!(evidence.contains("\"schema\": \"hoi4skill.large_mod_production_evidence_refresh.v1\""));
    assert!(evidence.contains("\"id\": \"strict_validation\", \"ok\": true"));
    assert!(validation.contains("common/national_focus/chi_reform_CHI_focus.txt"));
    assert!(validation.contains("\"changed_files\""));
}

