#[test]
fn validate_repair_context_emits_ai_repair_items_for_bad_effect() {
    let workspace = unique_temp_dir("validate-repair-context");
    let root = workspace.join("sub mod");
    let game = workspace.join("Hearts of Iron IV");
    fs::create_dir_all(root.join("events")).unwrap();
    fs::create_dir_all(root.join("localisation").join("simp_chinese")).unwrap();
    fs::create_dir_all(game.join("documentation")).unwrap();
    fs::create_dir_all(game.join("events")).unwrap();
    fs::write(
        root.join("descriptor.mod"),
        "name=\"Repair Context Test\"\nsupported_version=\"*\"\n",
    )
    .unwrap();
    fs::write(
        root.join("events").join("bad_events.txt"),
        "add_namespace = tst\ncountry_event = {\n id = tst.1\n title = tst.1.t\n desc = tst.1.d\n is_triggered_only = yes\n option = {\n  name = tst.1.a\n  add_politicalpower = 25\n }\n}\n",
    )
    .unwrap();
    fs::write(
        root.join("localisation")
            .join("simp_chinese")
            .join("tst_l_simp_chinese.yml"),
        "l_simp_chinese:\n tst.1.t:0 \"测试事件\"\n tst.1.d:0 \"测试描述\"\n tst.1.a:0 \"确认\"\n",
    )
    .unwrap();
    fs::write(
        game.join("documentation").join("effects_documentation.md"),
        "## Effects\n\n## add_political_power\n\n## add_stability\n",
    )
    .unwrap();
    fs::write(
        game.join("events").join("good_events.txt"),
        "add_namespace = good\ncountry_event = {\n id = good.1\n title = good.1.t\n desc = good.1.d\n is_triggered_only = yes\n option = {\n  name = good.1.a\n  add_political_power = 25\n }\n}\n",
    )
    .unwrap();
    let output = root.join("repair.json");

    cmd_validate_repair_context(&[
        root.to_string_lossy().to_string(),
        "--game-root".to_string(),
        game.to_string_lossy().to_string(),
        "--output".to_string(),
        output.to_string_lossy().to_string(),
    ])
    .unwrap();

    let json = read_utf8_lossy(&output).unwrap();
    fs::remove_dir_all(&workspace).unwrap();

    assert!(json.contains("\"schema\": \"hoi4skill.validation_repair_context.v1\""));
    assert!(json.contains("\"status\": \"needs_repair\""));
    assert!(json.contains("\"category\": \"unindexed_code_symbol\""));
    assert!(json.contains("\"kind\": \"effect\""));
    assert!(json.contains("\"symbol\": \"add_politicalpower\""));
    assert!(json.contains("\"symbol\": \"add_political_power\""));
    assert!(json.contains("\"code_example_retrieval\": {\"status\": \"ok\""));
    assert!(json.contains("\"repair_queries\""));
    assert!(json.contains("\"retrieved_code_examples\""));
    assert!(!json.contains("good_events.txt"));
    assert!(!json.contains("add_political_power = 25"));
    assert!(json.contains("do not invent a Clausewitz key"));
    assert!(json.contains("check-code-symbol --game-root"));
    assert!(json.contains("Hearts of Iron IV\\\""));
    assert!(json.contains("sub mod\\\""));
    assert!(json.contains("--kind effect --symbol add_politicalpower"));
}

#[test]
fn validate_strict_auto_writes_repair_context_with_semantic_evidence() {
    let workspace = unique_temp_dir("validate-auto-repair-context");
    let root = workspace.join("sub mod");
    let game = workspace.join("Hearts of Iron IV");
    fs::create_dir_all(root.join("events")).unwrap();
    fs::create_dir_all(root.join("localisation").join("simp_chinese")).unwrap();
    fs::create_dir_all(game.join("documentation")).unwrap();
    fs::create_dir_all(game.join("events")).unwrap();
    fs::write(
        root.join("descriptor.mod"),
        "name=\"Auto Repair Context Test\"\nsupported_version=\"*\"\n",
    )
    .unwrap();
    fs::write(
        root.join("events").join("bad_events.txt"),
        "add_namespace = tst\ncountry_event = {\n id = tst.1\n title = tst.1.t\n desc = tst.1.d\n is_triggered_only = yes\n option = {\n  name = tst.1.a\n  add_politicalpower = 25\n }\n}\n",
    )
    .unwrap();
    fs::write(
        root.join("localisation")
            .join("simp_chinese")
            .join("tst_l_simp_chinese.yml"),
        "l_simp_chinese:\n tst.1.t:0 \"测试事件\"\n tst.1.d:0 \"测试描述\"\n tst.1.a:0 \"确认\"\n",
    )
    .unwrap();
    fs::write(
        game.join("documentation").join("effects_documentation.md"),
        "## Effects\n\n## add_political_power\n\n## add_stability\n",
    )
    .unwrap();
    fs::write(
        game.join("events").join("good_events.txt"),
        "add_namespace = good\ncountry_event = {\n id = good.1\n title = good.1.t\n desc = good.1.d\n is_triggered_only = yes\n option = { name = good.1.a add_political_power = 25 }\n}\n",
    )
    .unwrap();
    let validation_output = root.join(".hoi4skill").join("validation.json");

    let err = cmd_validate(&[
        root.to_string_lossy().to_string(),
        "--game-root".to_string(),
        game.to_string_lossy().to_string(),
        "--strict-code-index".to_string(),
        "--output".to_string(),
        validation_output.to_string_lossy().to_string(),
    ])
    .unwrap_err();

    let repair_json =
        read_utf8_lossy(&root.join(".hoi4skill").join("ai_repair_context.json")).unwrap();
    let repair_md = read_utf8_lossy(&root.join(".hoi4skill").join("ai_repair_context.md")).unwrap();
    fs::remove_dir_all(&workspace).unwrap();

    assert!(err.contains("validation failed"));
    assert!(repair_json.contains("\"schema\": \"hoi4skill.validation_repair_context.v1\""));
    assert!(repair_json.contains("\"status\": \"needs_repair\""));
    assert!(repair_json.contains("\"symbol\": \"add_politicalpower\""));
    assert!(repair_json.contains("\"symbol\": \"add_political_power\""));
    assert!(!repair_json.contains("good_events.txt"));
    assert!(!repair_json.contains("add_political_power = 25"));
    assert!(repair_md.contains("# Validation Repair Context"));
    assert!(repair_md.contains("Related indexed code"));
    assert!(repair_md.contains("`effects` / `effect`: `add_political_power`"));
    assert!(!repair_md.contains("Retrieved local examples"));
    assert!(repair_md.contains("Do not fix by"));
    assert!(repair_md.contains("do not invent a Clausewitz key"));
    assert!(repair_md.contains("Anti Hallucination Rule"));
}

