#[test]
fn strict_validator_rejects_dynamic_modifier_used_as_national_spirit() {
    let root = unique_temp_dir("validate-dynamic-modifier-as-idea");
    fs::create_dir_all(root.join("common").join("national_focus")).unwrap();
    fs::create_dir_all(root.join("events")).unwrap();
    fs::write(
        root.join("descriptor.mod"),
        "name=\"Dynamic Modifier Misuse\"\nsupported_version=\"1.*\"\n",
    )
    .unwrap();
    fs::write(
        root.join("common")
            .join("national_focus")
            .join("bad_focus.txt"),
        "focus_tree = {\n id = tst_focus\n country = { factor = 0 modifier = { add = 10 tag = CHI } }\n focus = {\n  id = CHI_bad_dynamic_idea\n  icon = GFX_goal_unknown\n  x = 0\n  y = 0\n  cost = 10\n  completion_reward = { add_ideas = CHI_made_in_china }\n  available = { has_idea = CHI_made_in_china }\n }\n}\n",
    )
    .unwrap();
    fs::write(
        root.join("events").join("bad_events.txt"),
        "add_namespace = dyn_bad\ncountry_event = {\n id = dyn_bad.1\n title = dyn_bad.1.t\n desc = dyn_bad.1.d\n is_triggered_only = yes\n option = {\n  name = dyn_bad.1.a\n  swap_ideas = { remove_idea = CHI_made_in_china add_idea = CHI_other_dynamic }\n }\n}\n",
    )
    .unwrap();
    let mut index = GameIndex::default();
    index.country_tags.insert("CHI".to_string());
    index.effects.insert("add_ideas".to_string());
    index.effects.insert("swap_ideas".to_string());
    index.triggers.insert("has_idea".to_string());
    index
        .dynamic_modifiers
        .insert("CHI_made_in_china".to_string());
    index
        .dynamic_modifiers
        .insert("CHI_other_dynamic".to_string());

    let reporter = validate_mod_with_options(
        &root,
        Some(&index),
        ValidationOptions {
            strict_code_index: true,
        },
    )
    .unwrap();
    fs::remove_dir_all(&root).unwrap();

    let errors = reporter.errors.join("\n");
    assert!(errors.contains(
        "dynamic modifier CHI_made_in_china is used as a national spirit/idea reference"
    ));
    assert!(errors.contains(
        "dynamic modifier CHI_other_dynamic is used as a national spirit/idea reference"
    ));
    assert!(errors.contains("dynamic_modifier_scripted_effect_protocol"));
    assert!(errors.contains("not add_ideas/remove_ideas/has_idea/swap_ideas"));
}

