#[test]
fn validate_strict_accepts_large_mod_scopes_control_blocks_and_local_helpers() {
    let root = unique_temp_dir("validate-large-mod-legal-scopes");
    fs::create_dir_all(root.join("common").join("scripted_effects")).unwrap();
    fs::create_dir_all(root.join("common").join("scripted_triggers")).unwrap();
    fs::create_dir_all(root.join("common").join("decisions")).unwrap();
    fs::create_dir_all(root.join("common").join("game_rules")).unwrap();
    fs::write(
        root.join("descriptor.mod"),
        "name=\"Large Mod Legal Scopes\"\nsupported_version=\"*\"\n",
    )
    .unwrap();
    fs::write(
        root.join("common")
            .join("scripted_effects")
            .join("local_effects.txt"),
        "local_gain_effect = {\n if = { limit = { has_war = no } add_political_power = 50 }\n else = { add_political_power = 25 }\n CHN = { add_political_power = 5 }\n overlord = { add_political_power = 5 }\n 64 = { add_political_power = 1 }\n}\n",
    )
    .unwrap();
    fs::write(
        root.join("common")
            .join("scripted_triggers")
            .join("local_triggers.txt"),
        "local_check_trigger = {\n if = { limit = { has_war = no } CHN = { has_war = no } }\n else = { 608 = { has_war = no } }\n OVERLORD = { original_tag = CPC }\n controller = { has_war = no }\n CHN = { has_war = no }\n}\n",
    )
    .unwrap();
    fs::write(
        root.join("common").join("decisions").join("local_decisions.txt"),
        "local_category = { visible = { local_check_trigger = yes } local_decision = { visible = { local_check_trigger = yes } complete_effect = { local_gain_effect = yes } } }\n",
    )
    .unwrap();
    fs::write(
        root.join("common").join("game_rules").join("local_rules.txt"),
        "game_rules = { local_rule = { option = { name = local_rule_default text = local_rule_default_text allow_achievements = yes } } }\n",
    )
    .unwrap();

    let mut index = GameIndex::default();
    index.country_tags.insert("CHN".to_string());
    index.country_tags.insert("CPC".to_string());
    index.effects.insert("add_political_power".to_string());
    index.triggers.insert("has_war".to_string());

    let report = validate_mod_with_options(
        &root,
        Some(&index),
        ValidationOptions {
            strict_code_index: true,
        },
    )
    .unwrap();
    fs::remove_dir_all(&root).unwrap();

    let errors = report.errors.join("\n");
    assert!(report.errors.is_empty(), "{errors}");
    assert!(!errors.contains("unknown effect `if`"), "{errors}");
    assert!(!errors.contains("unknown effect `else`"), "{errors}");
    assert!(!errors.contains("unknown trigger `OVERLORD`"), "{errors}");
    assert!(!errors.contains("unknown trigger `controller`"), "{errors}");
    assert!(!errors.contains("unknown trigger `else`"), "{errors}");
    assert!(!errors.contains("unknown trigger `608`"), "{errors}");
    assert!(!errors.contains("unknown effect `overlord`"), "{errors}");
    assert!(
        !errors.contains("unknown effect `local_gain_effect`"),
        "{errors}"
    );
    assert!(
        !errors.contains("unknown trigger `local_check_trigger`"),
        "{errors}"
    );
    assert!(!errors.contains("unknown effect `text`"), "{errors}");
    assert!(
        !errors.contains("unknown effect `allow_achievements`"),
        "{errors}"
    );
}

