#[test]
fn strict_feature_card_gate_accepts_indexed_raw_trigger_assignment() {
    let root = unique_temp_dir("strict-feature-card-raw-trigger");
    let game = unique_temp_dir("strict-feature-card-raw-trigger-game");
    fs::create_dir_all(&root).unwrap();
    fs::create_dir_all(game.join("common").join("country_tags")).unwrap();
    fs::create_dir_all(game.join("documentation")).unwrap();
    fs::create_dir_all(game.join("interface")).unwrap();
    fs::write(
        root.join("descriptor.mod"),
        "name=\"Raw Trigger Test\"\nsupported_version=\"*\"\n",
    )
    .unwrap();
    fs::write(
        game.join("common")
            .join("country_tags")
            .join("00_countries.txt"),
        "CPC = \"countries/CPC.txt\"\n",
    )
    .unwrap();
    fs::write(
        game.join("documentation").join("triggers_documentation.md"),
        "## tag\n",
    )
    .unwrap();
    fs::write(
        game.join("documentation").join("effects_documentation.md"),
        "## add_political_power\n",
    )
    .unwrap();
    fs::write(
        game.join("interface").join("sprites.gfx"),
        "spriteType = { name = \"GFX_decision_category_generic_political_reform\" texturefile = \"gfx/interface/category.png\" }\nspriteType = { name = \"GFX_decision_generic_political_discourse\" texturefile = \"gfx/interface/decision.png\" }\n",
    )
    .unwrap();
    let input = root.join("cards.txt");
    fs::write(
        &input,
        "决议：召开支部整风会\n目标：CPC\n条件：tag = CPC\n效果：政治点+25\n描述：测试 raw trigger assignment。",
    )
    .unwrap();

    cmd_apply_feature_cards(&[
        "--input".to_string(),
        input.display().to_string(),
        "--mod-root".to_string(),
        root.display().to_string(),
        "--tag".to_string(),
        "CPC".to_string(),
        "--prefix".to_string(),
        "cpc_raw".to_string(),
        "--game-root".to_string(),
        game.display().to_string(),
        "--final-check".to_string(),
    ])
    .unwrap();
    let decisions = fs::read_to_string(
        root.join("common")
            .join("decisions")
            .join("cpc_raw_decisions.txt"),
    )
    .unwrap();
    fs::remove_dir_all(&root).unwrap();
    fs::remove_dir_all(&game).unwrap();

    assert!(decisions.contains("available = {"));
    assert!(decisions.contains("tag = CPC"));
    assert!(decisions.contains("add_political_power = 25"));
}

