#[test]
fn validator_errors_for_incomplete_focus_template() {
    let path = Path::new("M:\\mod\\common\\national_focus\\bad_focus.txt");
    let text = r#"
focus = {
    id = BAD_focus
    icon = GFX_goal_unknown
    x = 0
    y = 0
}
"#;
    let mut reporter = Reporter::default();

    check_national_focus_fields(path, &strip_comments(text), &mut reporter);

    assert!(reporter
        .errors
        .iter()
        .any(|msg| msg.contains("missing required template field `cost`")));
    assert!(reporter
        .errors
        .iter()
        .any(|msg| msg.contains("missing required template field `completion_reward`")));
    assert!(reporter
        .warnings
        .iter()
        .any(|msg| msg.contains("missing recommended generated-template field `ai_will_do`")));
    assert!(!reporter
        .errors
        .iter()
        .any(|msg| msg.contains("missing required template field `available`")));
}

#[test]
fn project_check_skips_authoring_template_rules_but_keeps_field_typos() {
    let path = Path::new("M:\\mod\\common\\national_focus\\project_focus.txt");
    let text = r#"
focus_tree = {
    id = project_tree
    country = SOV
    focus = {
        id = SOV_project_focus
        costs = 10
    }
}
"#;
    let mut reporter = Reporter::default();

    check_national_focus_fields_for_purpose(
        path,
        &strip_comments(text),
        ValidationPurpose::ProjectCheck,
        &mut reporter,
    );

    assert!(reporter.errors.iter().any(|message| message
        .contains("unknown near-match field `costs`")
        && message.contains("exact HOI4 field `cost`")));
    assert!(!reporter.errors.iter().any(|message| {
        message.contains("country selector")
            || message.contains("missing required template field")
            || message.contains("relative_position_id")
    }));
    assert!(reporter.warnings.is_empty());
}

