#[test]
fn work_package_style_context_combines_focus_idea_and_event_profiles() {
    let root = unique_temp_dir("work-package-style-context");
    fs::create_dir_all(root.join("common").join("national_focus")).unwrap();
    fs::create_dir_all(root.join("common").join("ideas")).unwrap();
    fs::create_dir_all(root.join("events")).unwrap();
    fs::create_dir_all(root.join("localisation").join("simp_chinese")).unwrap();
    fs::write(
        root.join("common")
            .join("national_focus")
            .join("sample_focus.txt"),
        "focus_tree = { id = sample_tree focus = { id = TST_party_congress } }\n",
    )
    .unwrap();
    fs::write(
        root.join("common").join("ideas").join("sample_ideas.txt"),
        "ideas = { country = { TST_party_unity_idea = { picture = generic_political_reform modifier = { stability_factor = 0.05 } } } }\n",
    )
    .unwrap();
    fs::write(
        root.join("events").join("sample_events.txt"),
        "add_namespace = tst\ncountry_event = { id = tst.1 title = tst.1.t desc = tst.1.d is_triggered_only = yes option = { name = tst.1.a } }\n",
    )
    .unwrap();
    fs::write(
        root.join("localisation")
            .join("simp_chinese")
            .join("sample_l_simp_chinese.yml"),
        "l_simp_chinese:\n TST_party_congress:0 \"召开党代会\"\n TST_party_congress_desc:0 \"漫长的派系争论终于被推到会场中央，代表们必须在纪律、路线和群众组织之间重新确立国家的方向。\"\n TST_party_unity_idea:0 \"党的团结\"\n TST_party_unity_idea_desc:0 \"干部系统暂时停止内斗，中央命令得以重新抵达基层组织。\"\n tst.1.t:0 \"代表抵达会场\"\n tst.1.d:0 \"清晨的会场外已经聚满代表，电报、报告与口号交织在一起，所有人都明白这场会议将改变国家的方向。\"\n tst.1.a:0 \"会议开始\"\n",
    )
    .unwrap();
    let output = root.join("style_context.md");

    cmd_work_package_style_context(&[
        "--style-mod".to_string(),
        root.to_string_lossy().to_string(),
        "--language".to_string(),
        "simp_chinese".to_string(),
        "--template".to_string(),
        "political_drama".to_string(),
        "--output".to_string(),
        output.to_string_lossy().to_string(),
    ])
    .unwrap();
    let context = read_utf8_lossy(&output).unwrap();
    fs::remove_dir_all(&root).unwrap();

    assert!(context.contains("hoi4skill.work_package_style_context.v1"));
    assert!(context.contains("selected_event_template: `political_drama`"));
    assert!(context.contains("matched_focuses: `1`"));
    assert!(context.contains("matched_ideas: `1`"));
    assert!(context.contains("matched_events: `1`"));
    assert!(context.contains("country_event"));
    assert!(context.contains("If an icon, tag, cosmetic tag"));
    assert!(!context.contains("漫长的派系争论终于被推到会场中央"));
    assert!(!context.contains("清晨的会场外已经聚满代表"));
}

#[test]
fn translate_localisation_prompt_reads_source_and_skips_existing_target_keys() {
    let root = unique_temp_dir("translate-localisation-prompt");
    fs::create_dir_all(root.join("localisation").join("english")).unwrap();
    fs::create_dir_all(root.join("localisation").join("simp_chinese")).unwrap();
    fs::write(
        root.join("localisation")
            .join("english")
            .join("sample_l_english.yml"),
        "l_english:\n TST_name:0 \"New Order\"\n TST_desc:0 \"We must protect $STATE|Y$ and [ROOT.GetName].\"\n TST_existing:0 \"Already done\"\n",
    )
    .unwrap();
    fs::write(
        root.join("localisation")
            .join("simp_chinese")
            .join("sample_l_simp_chinese.yml"),
        "l_simp_chinese:\n TST_existing:0 \"已经完成\"\n",
    )
    .unwrap();

    let map = parse_args(&[
        "--mod-root".to_string(),
        root.display().to_string(),
        "--from".to_string(),
        "english".to_string(),
        "--to".to_string(),
        "simp_chinese".to_string(),
    ]);
    let from = normalise_localisation_language(value(&map, "from").unwrap()).unwrap();
    let to = normalise_localisation_language(value(&map, "to").unwrap()).unwrap();
    let source_roots = source_localisation_roots(&map, Some(&root), &from).unwrap();
    let existing = target_existing_keys(Some(&root), &to).unwrap();
    let files =
        collect_localisation_source_files(Some(&root), &source_roots, &[], &existing, 100).unwrap();
    let prompt = render_localisation_translation_prompt_with_glossary(
        &from,
        &to,
        &files,
        &LocalisationGlossary::default(),
        None,
    );
    fs::remove_dir_all(&root).unwrap();

    assert_eq!(all_translation_entries(&files).len(), 2);
    assert!(prompt.contains("l_simp_chinese:"));
    assert!(prompt.contains("TST_name:0 \"New Order\""));
    assert!(prompt.contains("$STATE|Y$"));
    assert!(prompt.contains("[ROOT.GetName]"));
    assert!(prompt.contains("Do not translate tokens"));
    assert!(!prompt.contains("TST_existing:0"));
}

